local _, Lore = ...

Lore.storyData.Alliance = {
    {
        id = "q917",
        name = "Crown of the Earth",
        zone = "Teldrassil",
        minLevel = 1,
        maxLevel = 11,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 916 }, name = "Webwood Venom", level = 4, zone = "Teldrassil", giver = "Gilshalan Windwalker", giverMap = 1438, giverX = 57.8, giverY = 41.6, ender = "Gilshalan Windwalker", enderMap = 1438, enderX = 57.8, enderY = 41.6, objective = "Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.", summary = "I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this.$B$BFirst, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom." },
            { ids = { 917 }, name = "Webwood Egg", level = 5, zone = "Teldrassil", giver = "Gilshalan Windwalker", giverMap = 1438, giverX = 57.8, giverY = 41.6, ender = "Gilshalan Windwalker", enderMap = 1438, enderX = 57.8, enderY = 41.6, objective = "Bring a Webwood Egg to Gilshalan in Aldrassil.", summary = "Now that I have the spiders' venom, I'd like some live specimens to study.  Unfortunately, capturing a living, giant spider is more than I can ask of you, young $c.  And a giant spider is more than I could handle myself!$B$BBut if you can find an unhatched egg, then delivering specimens will be much easier, and I can then arrange for the unhatched spiders to be contained.$B$BThere must be a nest deep in the Shadowthread Cave.  Please, search for an egg in the nest and return it to me." },
            { ids = { 920 }, name = "Tenaron's Summons", level = 5, zone = "Teldrassil", giver = "Gilshalan Windwalker", giverMap = 1438, giverX = 57.8, giverY = 41.6, ender = "Tenaron Stormgrip", enderMap = 1438, enderX = 59.1, enderY = 39.5, objective = "Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.", summary = "$n, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.$b$bWe may live long lives, but it's best you not keep him waiting too long." },
            { ids = { 921 }, name = "Crown of the Earth", level = 5, zone = "Teldrassil", giver = "Tenaron Stormgrip", giverMap = 1438, giverX = 59.1, giverY = 39.5, ender = "Tenaron Stormgrip", enderMap = 1438, enderX = 59.1, enderY = 39.5, objective = "Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil.", summary = "It is time for you to set out to seek your destiny, $n. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history.$b$bMuch has changed with our people since the Battle of Mount Hyjal. Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion...$b$bThere is a task you must perform. Go to the moonwell north of Aldrassil and return me a phial of its water." },
            { ids = { 928 }, name = "Crown of the Earth", level = 5, zone = "Teldrassil", giver = "Tenaron Stormgrip", giverMap = 1438, giverX = 59.1, giverY = 39.5, ender = "Corithras Moonrage", enderMap = 1438, enderX = 56.1, enderY = 61.7, objective = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", summary = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.$b$bSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.$b$bMind you stay on the road though, $n. There are dangerous beasts in the forests of late." },
            { ids = { 929 }, name = "Crown of the Earth", level = 5, zone = "Teldrassil", giver = "Corithras Moonrage", giverMap = 1438, giverX = 56.1, giverY = 61.7, ender = "Corithras Moonrage", enderMap = 1438, enderX = 56.1, enderY = 61.7, objective = "Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar.", summary = "First, let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.$b$bTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. When you have completed your task, I shall continue the story where Tenaron left off..." },
            { ids = { 933 }, name = "Crown of the Earth", level = 9, zone = "Teldrassil", giver = "Corithras Moonrage", giverMap = 1438, giverX = 56.1, giverY = 61.7, ender = "Corithras Moonrage", enderMap = 1438, enderX = 56.1, enderY = 61.7, objective = "Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar.", summary = "There is another moonwell southeast of the entrance to Darnassus, on the shores of the Pools of Arlithrien. The Sentinels are having problems patrolling the area because of attacks and the growing ill-temperedness of the Gnarlpine furbolgs.$b$bBe wary as you seek out the well, and keep your weapons close at hand." },
            { ids = { 7383 }, name = "Crown of the Earth", level = 11, zone = "Teldrassil", giver = "Corithras Moonrage", giverMap = 1438, giverX = 56.1, giverY = 61.7, ender = "Corithras Moonrage", enderMap = 1438, enderX = 56.1, enderY = 61.7, objective = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", summary = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.$b$bHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me." },
            { ids = { 935 }, name = "Crown of the Earth", level = 11, zone = "Teldrassil", giver = "Corithras Moonrage", giverMap = 1438, giverX = 56.1, giverY = 61.7, ender = "Arch Druid Fandral Staghelm", enderMap = 1457, enderX = 34.8, enderY = 9.3, objective = "Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.", summary = "Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw. Strange beasts have been reported arising from the very ground of the tree, and crazed furbolgs attack passing travelers.$b$bI can only hope that the solution the Arch Druid is looking for will be found quickly. I will pour all the phials you brought into this vessel, for you to deliver to Darnassus.$b$bBring it to Fandral Staghelm, you will find him in the druid grove." },
        },
    },
    {
        id = "q475",
        name = "Gnarlpine Corruption",
        zone = "Teldrassil",
        minLevel = 4,
        maxLevel = 12,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 475 }, name = "A Troubling Breeze", level = 6, zone = "Teldrassil", giver = "Athridas Bearmantle", giverMap = 1438, giverX = 56.0, giverY = 57.3, ender = "Gaerolas Talvethren", enderMap = 1438, enderX = 66.3, enderY = 58.5, objective = "Seek out Gaerolas Talvethren in Starbreeze Village.", summary = "A troubling breeze blows through the forest.$b$bGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.$b$bBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely." },
            { ids = { 476 }, name = "Gnarlpine Corruption", level = 6, zone = "Teldrassil", giver = "Gaerolas Talvethren", giverMap = 1438, giverX = 66.3, giverY = 58.5, ender = "Athridas Bearmantle", enderMap = 1438, enderX = 56.0, enderY = 57.3, objective = "Return to Athridas Bearmantle in Dolanaar.", summary = "The Gnarlpine tribe has been corrupted!$b$bThe once peaceful furbolgs have turned against the protectors of the forest.  They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village.  Ursal the Mauler, their chieftain, is using the evil powers of the Fel Moss to drive them mad.$b$bI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young $c.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!" },
            { ids = { 483 }, name = "The Relics of Wakening", level = 9, zone = "Teldrassil", giver = "Athridas Bearmantle", giverMap = 1438, giverX = 56.0, giverY = 57.3, ender = "Athridas Bearmantle", enderMap = 1438, enderX = 56.0, enderY = 57.3, objective = "Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.", summary = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west.$b$bThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.$b$bJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual." },
            { ids = { 486 }, name = "Ursal the Mauler", level = 12, zone = "Teldrassil", giver = "Athridas Bearmantle", giverMap = 1438, giverX = 56.0, giverY = 57.3, ender = "Athridas Bearmantle", enderMap = 1438, enderX = 56.0, enderY = 57.3, objective = "Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.", summary = "Now the time has come to save the Druids of the Talon. If we fail now, $N, they will be forever lost in sleep.$b$bI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete.$b$bIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay him." },
        },
    },
    {
        id = "q918",
        name = "Timberling Seeds",
        zone = "Teldrassil",
        minLevel = 4,
        maxLevel = 9,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 918 }, name = "Timberling Seeds", level = 7, zone = "Teldrassil", giver = "Denalan", giverMap = 1438, giverX = 60.9, giverY = 68.5, ender = "Denalan", enderMap = 1438, enderX = 60.9, enderY = 68.5, objective = "Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.", summary = "The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.$B$BSo it is disturbing to see how angry the timberlings have become.$B$BI believe it has something to do with the soil.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?" },
            { ids = { 922 }, name = "Rellian Greenspyre", level = 7, zone = "Teldrassil", giver = "Denalan", giverMap = 1438, giverX = 60.9, giverY = 68.5, ender = "Rellian Greenspyre", enderMap = 1457, enderX = 38.2, enderY = 21.6, objective = "Bring a Timberling Seed to Rellian Greenspyre in Darnassus.", summary = "$N, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid in Darnassus, and when last we spoke he revealed his interest in my work with the Timberlings.  He had some ideas himself, and he will appreciate a specimen seed to work with.$B$BThank you, $N.  You have been a great help to me.  I hope that, some day, you will see the fruit of my labors.$B$BYou will usually find Rellian walking the pathways of the Cenarian Enclave in Darnassus." },
            { ids = { 923 }, name = "Tumors", level = 9, zone = "Darnassus", giver = "Rellian Greenspyre", giverMap = 1457, giverX = 38.2, giverY = 21.6, ender = "Rellian Greenspyre", enderMap = 1457, enderX = 38.2, enderY = 21.6, objective = "Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.", summary = "There is a malevolence growing in the timberlings.  We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help.  Those that wander Wellspring Lake in northern Teldrassil are the most tainted.  They must be removed!$B$BDestroy the Timberlings you find there, and gather the mossy tumors growing upon them.  Bring the tumors to me so that they may be burned." },
            { ids = { 2498 }, name = "Return to Denalan", level = 9, zone = "Darnassus", giver = "Rellian Greenspyre", giverMap = 1457, giverX = 38.2, giverY = 21.6, ender = "Denalan", enderMap = 1438, enderX = 60.9, enderY = 68.5, objective = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.", summary = "I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.$B$BMake haste, $N; he needs our help." },
            { ids = { 2499 }, name = "Oakenscowl", level = 9, zone = "Teldrassil", giver = "Denalan", giverMap = 1438, giverX = 60.9, giverY = 68.5, ender = "Denalan", enderMap = 1438, enderX = 60.9, enderY = 68.5, objective = "Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.", summary = "In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home.$B$BI dared not get too close, but even from a distance, it is obvious: Oakenscowl is being poisoned by the largest tumor I have ever seen...  I would call it gargantuan, even.$B$B$N, you have already done much to aid my efforts, but I ask of you one more task. Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home." },
        },
    },
    {
        id = "q937",
        name = "Grove of the Ancients",
        zone = "Teldrassil",
        minLevel = 6,
        maxLevel = 11,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 937 }, name = "The Enchanted Glade", level = 11, zone = "Teldrassil", giver = "Sentinel Arynia Cloudsbreak", giverMap = 1438, giverX = 38.3, giverY = 34.4, ender = "Sentinel Arynia Cloudsbreak", enderMap = 1438, enderX = 38.3, enderY = 34.4, objective = "Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.", summary = "I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.$b$bWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.$b$bIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds." },
            { ids = { 940 }, name = "Teldrassil", level = 11, zone = "Teldrassil", giver = "Sentinel Arynia Cloudsbreak", giverMap = 1438, giverX = 38.3, giverY = 34.4, ender = "Arch Druid Fandral Staghelm", enderMap = 1457, enderX = 34.8, enderY = 9.3, objective = "Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.", summary = "The forest whispers of your feats of valor, $n. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.$b$bDeliver this to him and know that the forest will see you safely along its paths to the forest of stone." },
            { ids = { 952 }, name = "Grove of the Ancients", level = 11, zone = "Darnassus", giver = "Arch Druid Fandral Staghelm", giverMap = 1457, giverX = 34.8, giverY = 9.3, ender = "Onu", enderMap = 1439, enderX = 43.5, enderY = 76.3, objective = "Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.", summary = "If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine.$b$bYou will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade." },
        },
    },
    {
        id = "q40",
        name = "Discover Rolf's Fate",
        zone = "Elwynn Forest",
        minLevel = 7,
        maxLevel = 10,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 40 }, name = "A Fishy Peril", level = 10, zone = "Elwynn Forest", giver = "Remy \"Two Times\"", giverMap = 1429, giverX = 42.1, giverY = 67.3, ender = "Marshal Dughan", enderMap = 1429, enderX = 42.1, enderY = 65.9, objective = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.", summary = "$N, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!$B$BI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.$B$BPlease, $N, speak to Dughan and persuade him to send more troops to the east!" },
            { ids = { 35 }, name = "Further Concerns", level = 10, zone = "Elwynn Forest", giver = "Marshal Dughan", giverMap = 1429, giverX = 42.1, giverY = 65.9, ender = "Guard Thomas", enderMap = 1429, enderX = 74.0, enderY = 72.2, objective = "Marshal Dughan wants you to speak with Guard Thomas.", summary = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.$B$BBring me his report." },
            { ids = { 37 }, name = "Find the Lost Guards", level = 10, zone = "Elwynn Forest", giver = "Guard Thomas", giverMap = 1429, giverX = 74.0, giverY = 72.2, ender = "A half-eaten body", enderMap = 1429, enderX = 72.7, enderY = 60.3, objective = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.", summary = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.$B$BTravel north along the river and find the guards... or their remains." },
            { ids = { 45 }, name = "Discover Rolf's Fate", level = 10, zone = "Elwynn Forest", giver = "A half-eaten body", giverMap = 1429, giverX = 72.7, giverY = 60.3, ender = "Rolf's corpse", enderMap = 1429, enderX = 79.8, enderY = 55.5, objective = "Search the murloc village for Rolf, or signs of his death.", summary = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.$B$BPerhaps Rolf's fate ended there..." },
            { ids = { 71 }, name = "Report to Thomas", level = 10, zone = "Elwynn Forest", giver = "Rolf's corpse", giverMap = 1429, giverX = 79.8, giverY = 55.5, ender = "Guard Thomas", enderMap = 1429, enderX = 74.0, enderY = 72.2, objective = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.", summary = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards." },
            { ids = { 39 }, name = "Deliver Thomas' Report", level = 10, zone = "Elwynn Forest", giver = "Guard Thomas", giverMap = 1429, giverX = 74.0, giverY = 72.2, ender = "Marshal Dughan", enderMap = 1429, enderX = 42.1, enderY = 65.9, objective = "Report to Marshal Dughan in Goldshire.", summary = "Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.$B$BI know we don't have many troops to spare, but hopefully Dughan can find someone." },
            { ids = { 59 }, name = "Cloth and Leather Armor", level = 10, zone = "Elwynn Forest", giver = "Marshal Dughan", giverMap = 1429, giverX = 42.1, giverY = 65.9, ender = "Sara Timberlain", enderMap = 1429, enderX = 79.5, enderY = 68.8, objective = "Give Sara Timberlain the Stormwind Armor Marker.", summary = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, $N, use it in the defense of Elwynn.$B$BThe Eastvale Logging Camp is beyond Guard Thomas' post to the east." },
        },
    },
    {
        id = "q298",
        name = "Protecting the Shipment",
        zone = "Loch Modan",
        minLevel = 10,
        maxLevel = 15,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 298 }, name = "Excavation Progress Report", level = 15, zone = "Loch Modan", giver = "Prospector Ironband", giverMap = 1432, giverX = 65.9, giverY = 65.6, ender = "Jern Hornhelm", enderMap = 1432, enderX = 37.2, enderY = 47.4, objective = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.", summary = "I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.$B$BIt's not a difficult task, but it must be done." },
            { ids = { 301 }, name = "Report to Ironforge", level = 15, zone = "Loch Modan", giver = "Jern Hornhelm", giverMap = 1432, giverX = 37.2, giverY = 47.4, ender = "Prospector Stormpike", enderMap = 1455, enderX = 74.6, enderY = 11.7, objective = "Take Ironband's Progress Report to Prospector Stormpike.", summary = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.$B$BHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.$B$BYou'll find Stormpike in the Assembly of Explorers." },
            { ids = { 302 }, name = "Powder to Ironband", level = 15, zone = "Ironforge", giver = "Prospector Stormpike", giverMap = 1455, giverX = 74.6, giverY = 11.7, ender = "Jern Hornhelm", enderMap = 1432, enderX = 37.2, enderY = 47.4, objective = "Speak with Jern Hornhelm in Thelsamar.", summary = "If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.$B$BAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open." },
            { ids = { 273 }, name = "Resupplying the Excavation", level = 15, zone = "Loch Modan", giver = "Jern Hornhelm", giverMap = 1432, giverX = 37.2, giverY = 47.4, ender = "Huldar", enderMap = 1432, enderX = 52.2, enderY = 69.3, objective = "Speak with Huldar.", summary = "It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.$b$bThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.$b$bShouldn't have a problem finding them unless they've already gotten there." },
            { ids = { 454 }, name = "After the Ambush", level = 15, zone = "Loch Modan", giver = "Huldar", giverMap = 1432, giverX = 52.2, giverY = 69.3, ender = "Miran", enderMap = 1432, enderX = 52.2, enderY = 69.4, objective = "Speak with Miran.", summary = "We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.$b$bI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?" },
            { ids = { 309 }, name = "Protecting the Shipment", level = 15, zone = "Loch Modan", giver = "Miran", giverMap = 1432, giverX = 52.2, giverY = 69.4, ender = "Prospector Ironband", enderMap = 1432, enderX = 65.9, enderY = 65.6, objective = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.", summary = "Ready to go, $n?$b$bFirst, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.$b$bI'll feel a lot better with you coming along." },
        },
    },
    {
        id = "q5923",
        name = "Body and Heart",
        zone = "Darnassus",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        races = { 4 },
        classes = { 11 },
        quests = {
            { ids = { 5923 }, name = "Heeding the Call", level = 10, zone = "Darnassus", giver = "Denatharion", giverMap = 1457, giverX = 34.8, giverY = 7.4, ender = "Mathrengyl Bearwalker", enderMap = 1457, enderX = 35.4, enderY = 8.4, objective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", summary = "Excuse me, friend...$B$BIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.$B$BHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree." },
            { ids = { 5921 }, name = "Moonglade", level = 10, zone = "Darnassus", giver = "Mathrengyl Bearwalker", giverMap = 1457, giverX = 35.4, giverY = 8.4, ender = "Dendrite Starblaze", enderMap = 1450, enderX = 56.2, enderY = 30.6, objective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", summary = "All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.$B$BAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid." },
            { ids = { 5929 }, name = "Great Bear Spirit", level = 10, zone = "Moonglade", giver = "Dendrite Starblaze", giverMap = 1450, giverX = 56.2, giverY = 30.6, ender = "Dendrite Starblaze", enderMap = 1450, enderX = 56.2, enderY = 30.6, objective = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", summary = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.$B$BGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches." },
            { ids = { 5931 }, name = "Back to Darnassus", level = 10, zone = "Moonglade", giver = "Dendrite Starblaze", giverMap = 1450, giverX = 56.2, giverY = 30.6, ender = "Mathrengyl Bearwalker", enderMap = 1457, enderX = 35.4, enderY = 8.4, objective = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.", summary = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Mathrengyl Bearwalker walks truly in balance with nature, even as he dwells precariously close to where the balance has faltered.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.$B$BGo now, young one.  We shall meet again." },
            { ids = { 6001 }, name = "Body and Heart", level = 10, zone = "Darnassus", giver = "Mathrengyl Bearwalker", giverMap = 1457, giverX = 35.4, giverY = 8.4, ender = "Mathrengyl Bearwalker", enderMap = 1457, enderX = 35.4, enderY = 8.4, objective = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.$B$BSpeak with Mathrengyl Bearwalker in Darnassus when you are done.", summary = "Directly east of Auberdine lay many moonkin caves.  The one closest to Auberdine has a Moonkin Stone inside it.  Lunaclaw, the defender of the stone, will face you only when Cenarion Moondust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.$B$BYou've earned the right to use this Cenarion Moondust, $N... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!" },
        },
    },
    {
        id = "q1679",
        name = "Beat Bartleby",
        zone = "Dun Morogh",
        minLevel = 10,
        maxLevel = 11,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 1679 }, name = "Muren Stormpike", level = 10, zone = "Dun Morogh", giver = "Granis Swiftaxe", giverMap = 1426, giverX = 47.4, giverY = 52.6, ender = "Muren Stormpike", enderMap = 1455, enderX = 70.8, enderY = 90.3, objective = "Speak with Muren Stormpike.", summary = "Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.$B$BYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior." },
            { ids = { 1678 }, name = "Vejrek", level = 11, zone = "Ironforge", giver = "Muren Stormpike", giverMap = 1455, giverX = 70.8, giverY = 90.3, ender = "Muren Stormpike", enderMap = 1455, enderX = 70.8, enderY = 90.3, objective = "Bring Vejrek's Head to Muren Stormpike in Ironforge.", summary = "If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.$B$BVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold$B$BBring me Vejrek's head and I'll know you have mettle." },
            { ids = { 1640 }, name = "Beat Bartleby", level = 10, zone = "Stormwind City", giver = "Bartleby", giverMap = 1453, giverX = 76.8, giverY = 52.5, ender = "Bartleby", enderMap = 1453, enderX = 76.8, enderY = 52.5, objective = "Beat Bartleby, then talk to him.", summary = "You want what??  You're crazy!$B$BThe only way you'll get this mug is if you pry it from my cold, dead fingers..." },
            { ids = { 1665 }, name = "Bartleby's Mug", level = 10, zone = "Stormwind City", giver = "Bartleby", giverMap = 1453, giverX = 76.8, giverY = 52.5, ender = "Harry Burlguard", enderMap = 1453, enderX = 77.1, enderY = 53.3, objective = "Bring Bartleby's Mug to Burlguard", summary = "Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go." },
            { ids = { 1666 }, name = "Marshal Haggard", level = 10, zone = "Stormwind City", giver = "Harry Burlguard", giverMap = 1453, giverX = 77.1, giverY = 53.3, ender = "Marshal Haggard", enderMap = 1429, enderX = 84.6, enderY = 69.4, objective = "Speak with Marshal Haggard.", summary = "You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.$B$BMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.$B$BLet him know I sent you, and with luck he'll have a spare weapon to offer." },
            { ids = { 1667 }, name = "Dead-tooth Jack", level = 10, zone = "Elwynn Forest", giver = "Marshal Haggard", giverMap = 1429, giverX = 84.6, giverY = 69.4, ender = "Marshal Haggard", enderMap = 1429, enderX = 84.6, enderY = 69.4, objective = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.", summary = "Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...$B$BA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!$B$BGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south." },
        },
    },
    {
        id = "q2205",
        name = "Snatch and Grab",
        zone = "Elwynn Forest",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        classes = { 4 },
        quests = {
            { ids = { 2205 }, name = "Seek out SI: 7", level = 10, zone = "Elwynn Forest", giver = "Keryn Sylvius", giverMap = 1429, giverX = 43.9, giverY = 65.9, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.", summary = "The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery $g boy:girl; instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.$B$BSpeaking of which, deliver this package to Mathias and he may give you a small task or two.$B$BGet cracking. " },
            { ids = { 2206 }, name = "Snatch and Grab", level = 10, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.", summary = "Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.$B$BI need you to infiltrate the dock house and get me that shipping schedule, $N. You will probably find it buried deep in the pockets of the Dockmaster.$B$B...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence." },
        },
    },
    {
        id = "q1685",
        name = "Surena Caledon",
        zone = "Elwynn Forest",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 1685 }, name = "Gakin's Summons", level = 10, zone = "Elwynn Forest", giver = "Remen Marcot", giverMap = 1429, giverX = 44.5, giverY = 66.3, ender = "Gakin the Darkbinder", enderMap = 1453, enderX = 39.2, enderY = 85.2, objective = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", summary = "Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.$b$bI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.$b$bYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it." },
            { ids = { 1688 }, name = "Surena Caledon", level = 10, zone = "Stormwind City", giver = "Gakin the Darkbinder", giverMap = 1453, giverX = 39.2, giverY = 85.2, ender = "Gakin the Darkbinder", enderMap = 1453, enderX = 39.2, enderY = 85.2, objective = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.", summary = "I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!$b$bThe thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.$b$bHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine." },
            { ids = { 1689 }, name = "The Binding", level = 10, zone = "Stormwind City", giver = "Gakin the Darkbinder", giverMap = 1453, giverX = 39.2, giverY = 85.2, ender = "Gakin the Darkbinder", enderMap = 1453, enderX = 39.2, enderY = 85.2, objective = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.", summary = "By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.$b$bWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.$b$bI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below." },
        },
    },
    {
        id = "q1683",
        name = "Ironband's Compound",
        zone = "Darnassus",
        minLevel = 10,
        maxLevel = 11,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 1683 }, name = "Vorlus Vilehoof", level = 10, zone = "Darnassus", giver = "Elanaria", giverMap = 1457, giverX = 57.3, giverY = 34.6, ender = "Elanaria", enderMap = 1457, enderX = 57.3, enderY = 34.6, objective = "Bring the Horn of Vorlus to Elanaria in Darnassus.", summary = "Before I can teach you, you must show me your resolve.$B$BThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.$B$BFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.$B$BThe path to the moonwell is hidden well, $N, but stay focused and alert and you will find it." },
            { ids = { 1680 }, name = "Tormus Deepforge", level = 11, zone = "Ironforge", giver = "Muren Stormpike", giverMap = 1455, giverX = 70.8, giverY = 90.3, ender = "Tormus Deepforge", enderMap = 1455, enderX = 48.6, enderY = 42.5, objective = "Speak with Tormus Deepforge.", summary = "Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.$B$BYou'll find Tormus here in Ironforge, at the Great Forge." },
            { ids = { 1681 }, name = "Ironband's Compound", level = 11, zone = "Ironforge", giver = "Tormus Deepforge", giverMap = 1455, giverX = 48.6, giverY = 42.5, ender = "Tormus Deepforge", enderMap = 1455, enderX = 48.6, enderY = 42.5, objective = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.", summary = "My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.$B$BBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!$B$BEnter Ironband's compound, $N, and avenge my master's death.  And bring me the load of umbral ore that caused it." },
            { ids = { 1682 }, name = "Grey Iron Weapons", level = 10, zone = "Ironforge", giver = "Tormus Deepforge", giverMap = 1455, giverX = 48.6, giverY = 42.5, ender = "Tormus Deepforge", enderMap = 1455, enderX = 48.6, enderY = 42.5 },
        },
    },
    {
        id = "q6071",
        name = "Training the Beast",
        zone = "Darnassus",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        races = { 4 },
        classes = { 3 },
        quests = {
            { ids = { 6071 }, name = "The Hunter's Path", level = 10, zone = "Darnassus", giver = "Jocaste", giverMap = 1457, giverX = 40.4, giverY = 8.6, ender = "Dazalar", enderMap = 1438, enderX = 56.7, enderY = 59.5, objective = "Speak with Dazalar in Dolanaar.", summary = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own." },
            { ids = { 6063 }, name = "Taming the Beast", level = 10, zone = "Teldrassil", giver = "Dazalar", giverMap = 1438, giverX = 56.7, giverY = 59.5, ender = "Dazalar", enderMap = 1438, enderX = 56.7, enderY = 59.5, objective = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", summary = "As a hunter, it is important to remember the responsibility you hold in your hands. Nature is not a power that can be bent to obey our desires; it is one that is to be respected and acknowledged as something stronger than your very existence.$B$B$N, you must prove your understanding of this before you will gain the ability to tame an animal to be your companion.$B$BYour first task is to take this taming rod. With it, you will be able to tame a webwood lurker. Tame it, and practice your skills as a hunter." },
            { ids = { 6101 }, name = "Taming the Beast", level = 10, zone = "Teldrassil", giver = "Dazalar", giverMap = 1438, giverX = 56.7, giverY = 59.5, ender = "Dazalar", enderMap = 1438, enderX = 56.7, enderY = 59.5, objective = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", summary = "The variance of nature is something that can be relied upon, $N. It is predictable in the way that it never remains the same; it is always changing.$B$BThe tasks I give to you will help you to see and appreciate the vast differences of the creatures you may choose as your companion.$B$BTake this taming rod and use it to tame a nightsaber stalker, found to the south. Practice your skills as a hunter. Then you will begin to understand the similarities and differences of nature." },
            { ids = { 6102 }, name = "Taming the Beast", level = 10, zone = "Teldrassil", giver = "Dazalar", giverMap = 1438, giverX = 56.7, giverY = 59.5, ender = "Dazalar", enderMap = 1438, enderX = 56.7, enderY = 59.5, objective = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", summary = "You have tamed two creatures that inhabit the land, now you must tame one that soars the skies. Use the taming rod to tame a strigid screecher, found west of here. Practice your skills with this mighty owl at your side.$B$BWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish." },
            { ids = { 6103 }, name = "Training the Beast", level = 10, zone = "Teldrassil", giver = "Dazalar", giverMap = 1438, giverX = 56.7, giverY = 59.5, ender = "Jocaste", enderMap = 1457, enderX = 40.4, enderY = 8.6, objective = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.", summary = "You now have the power to tame a pet, but you must also gain the skills to train it.$B$BTravel to Darnassus. There you must speak to one of our most revered hunters, Jocaste. She will give you the ability to train your new pet, so make haste.$B$BWhile Jocaste may seem stern, she is always pleased to see another hunter rising through the ranks. Treat her with respect and she will return in kind. Good luck, $N." },
        },
    },
    {
        id = "q6074",
        name = "Training the Beast",
        zone = "Ironforge",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        races = { 3 },
        classes = { 3 },
        quests = {
            { ids = { 6074 }, name = "The Hunter's Path", level = 10, zone = "Ironforge", giver = "Olmin Burningbeard", giverMap = 1455, giverX = 70.9, giverY = 83.6, ender = "Grif Wildheart", enderMap = 1426, enderX = 45.8, enderY = 53.0, objective = "Speak with Grif Wildheart in Kharanos.", summary = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own." },
            { ids = { 6064 }, name = "Taming the Beast", level = 10, zone = "Dun Morogh", giver = "Grif Wildheart", giverMap = 1426, giverX = 45.8, giverY = 53.0, ender = "Grif Wildheart", enderMap = 1426, enderX = 45.8, enderY = 53.0, objective = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", summary = "Hi there, $Glad:lass;! So, you'd be wanting to know how you can gain a pet of your own?$B$BWell, let's get started. There's nothing more important than yer equipment when it comes to hunting, but we can chat about my new Shrapnel Blaster some other time. Fer now, let's focus on something I'm sure you're quite interested in: a pet!$B$BThe best way to learn is for you to try out several creatures as companions and see what ya like. So, find a large crag boar, then use the taming rod to tame it." },
            { ids = { 6084 }, name = "Taming the Beast", level = 10, zone = "Dun Morogh", giver = "Grif Wildheart", giverMap = 1426, giverX = 45.8, giverY = 53.0, ender = "Grif Wildheart", enderMap = 1426, enderX = 45.8, enderY = 53.0, objective = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.", summary = "Those crag boars are quite burly; maybe you'd like something with a little more finesse? Alright then, I've got jus' the thing. South and east of here, you'll find large white cats called snow leopards. Just like an elegantly-carved rifle, behind their beautiful exterior lies a powerful fighter, capable of doing extreme damage. You'll find them to be much more agile an' swift than the boar you tamed.$B$BTake this taming rod and see how you like the snow leopard." },
            { ids = { 6085 }, name = "Taming the Beast", level = 10, zone = "Dun Morogh", giver = "Grif Wildheart", giverMap = 1426, giverX = 45.8, giverY = 53.0, ender = "Grif Wildheart", enderMap = 1426, enderX = 45.8, enderY = 53.0, objective = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", summary = "Perhaps you'd like a creature that possesses little more than brute strength. The ice claw bear is an excellent companion for a fledgling hunter like yourself, and can be found east of Kharanos. Here is the taming rod; try this animal as a pet and see if ya like it!$B$BWhen you return, I'll give ya the skills you will need to tame an animal of your choosing; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as ya like." },
            { ids = { 6086 }, name = "Training the Beast", level = 10, zone = "Dun Morogh", giver = "Grif Wildheart", giverMap = 1426, giverX = 45.8, giverY = 53.0, ender = "Belia Thundergranite", enderMap = 1455, enderX = 70.9, enderY = 85.8, objective = "Speak with Belia Thundergranite in Ironforge.", summary = "$N, ya now have the power to tame a pet, but you must also gain the skills ta train it.$B$BTravel to Ironforge and find the Hall of Arms. There you must speak to one of our most revered animal trainers, Belia Thundergranite. She'll give ya the power to train your new pet, so get goin', $Glad:lass;!$B$BBelia is a friendly sort; you should have no problems gaining her approval. Good luck, $N." },
        },
    },
    {
        id = "q2218",
        name = "Onin's Report",
        zone = "Dun Morogh",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        classes = { 4 },
        quests = {
            { ids = { 2218 }, name = "Road to Salvation", level = 10, zone = "Dun Morogh", giver = "Hogral Bakkan", giverMap = 1426, giverX = 47.6, giverY = 52.6, ender = "Hulfdan Blackbeard", enderMap = 1455, enderX = 52.0, enderY = 14.8, objective = "Speak with Hulfdan Blackbeard in Ironforge.", summary = "Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.$B$BWell, today's your lucky day, friend. Hogral's got the cure for your ailment.$B$BHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation." },
            { ids = { 2238 }, name = "Simple Subterfugin'", level = 10, zone = "Ironforge", giver = "Hulfdan Blackbeard", giverMap = 1455, giverX = 52.0, giverY = 14.8, ender = "Onin MacHammar", enderMap = 1426, enderX = 25.2, enderY = 44.5, objective = "Find Onin MacHammar by Gnomeregan.", summary = "Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.$B$BThe Hidden Circle has values, $N. We value valuables. Can ye understand?$B$BNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.$B$BWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful." },
            { ids = { 2239 }, name = "Onin's Report", level = 10, zone = "Dun Morogh", giver = "Onin MacHammar", giverMap = 1426, giverX = 25.2, giverY = 44.5, ender = "Hulfdan Blackbeard", enderMap = 1455, enderX = 52.0, enderY = 14.8, objective = "Take Onin's Report back to Hulfdan in Ironforge.", summary = "The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.$B$BMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.$B$BIt's all in the report, $r. Take it back to Hulfdan so he can plan the next step." },
        },
    },
    {
        id = "q6387",
        name = "Honor Students",
        zone = "Loch Modan",
        minLevel = 10,
        maxLevel = 10,
        importance = 1,
        kind = "world",
        races = { 3, 7 },
        quests = {
            { ids = { 6387 }, name = "Honor Students", level = 10, zone = "Loch Modan", giver = "Brock Stoneseeker", giverMap = 1432, giverX = 37.0, giverY = 47.8, ender = "Thorgrum Borrelson", enderMap = 1432, enderX = 33.9, enderY = 51.0, objective = "Bring Brock's List to Thorgrum Borrelson in Thelsamar.", summary = "I see a lot of young dwarves at my door, eager to learn the trade of mining.  And if there's one thing a miner needs more than anything, it's a pick!$B$BI have a list of mining students who scored high in their lessons and earned an honorary pick.  Take my list to Golnir Bouldertoe in Ironforge.  He'll get the picks ready.$B$BThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Thorgrum Borrelson, and speak with him about transport to Ironforge." },
            { ids = { 6391 }, name = "Ride to Ironforge", level = 10, zone = "Loch Modan", giver = "Thorgrum Borrelson", giverMap = 1432, giverX = 33.9, giverY = 51.0, ender = "Golnir Bouldertoe", enderMap = 1455, enderX = 51.5, enderY = 26.3, objective = "Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge.", summary = "For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Brock's list to Golnir Bouldertoe.  You'll find him in the Deep Mountain Mining Guild.  That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!$B$BSpeak to me again when you're ready for the journey." },
            { ids = { 6388 }, name = "Gryth Thurden", level = 10, zone = "Ironforge", giver = "Golnir Bouldertoe", giverMap = 1455, giverX = 51.5, giverY = 26.3, ender = "Gryth Thurden", enderMap = 1455, enderX = 55.5, enderY = 47.7, objective = "Bring the Honorary Picks to Gryth Thurden in Ironforge.", summary = "Here are the honorary picks for Brock's students.  If you've already been to Thelsamar, then you should fly a gryphon back there!$B$BTake the picks to our gryphon master, Gryth Thurden, and speak with him about a ride back to Thelsamar." },
            { ids = { 6392 }, name = "Return to Brock", level = 10, zone = "Ironforge", giver = "Gryth Thurden", giverMap = 1455, giverX = 55.5, giverY = 47.7, ender = "Brock Stoneseeker", enderMap = 1432, enderX = 37.0, enderY = 47.8, objective = "Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar.", summary = "For a small fee you can buy a gryphon ride to Thelsamar... as long as you've already been there.  Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later.$B$BYou've already been to Thorgrum, the gryphon master of Thelsamar, so now you can return to him.  And once in Thelsamar, you can deliver the picks to Brock Stoneseeker.$B$BSpeak with me when you're ready to go." },
        },
    },
    {
        id = "q984",
        name = "The Blackwood Corrupted",
        zone = "Darkshore",
        minLevel = 10,
        maxLevel = 18,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 984 }, name = "How Big a Threat?", level = 14, zone = "Darkshore", giver = "Terenthis", giverMap = 1439, giverX = 39.4, giverY = 43.5, ender = "Terenthis", enderMap = 1439, enderX = 39.4, enderY = 43.5, objective = "Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.", summary = "Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.$B$BI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?" },
            { ids = { 4761 }, name = "Thundris Windweaver", level = 15, zone = "Darkshore", giver = "Terenthis", giverMap = 1439, giverX = 39.4, giverY = 43.5, ender = "Thundris Windweaver", enderMap = 1439, enderX = 37.4, enderY = 40.1, objective = "Speak with Thundris Windweaver in Auberdine.", summary = "Your scouting of the furbolg camp is information that Thundris Windweaver should be made aware of.  He graciously serves as the elder of Auberdine, offering sage and just stewardship of the day to day affairs of the village.  Please - share with him your findings to date on the furbolg situation.$B$BI believe he has some ideas of his own on the reasons behind their corruption.  Perhaps you can work with him to enact a plan to restore the balance of nature here!" },
            { ids = { 4762 }, name = "The Cliffspring River", level = 15, zone = "Darkshore", giver = "Thundris Windweaver", giverMap = 1439, giverX = 37.4, giverY = 40.1, ender = "Thundris Windweaver", enderMap = 1439, enderX = 37.4, enderY = 40.1, objective = "Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.$B$BReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.", summary = "The Cliffspring River has begun turning foul and corrupted.  It empties into the Mist's Edge, and I fear the wash will affect Auberdine soon.  I suspect the Blackwood furbolgs up-river are the cause of the taint, but I also suspect that they aren't the true root of it.$B$BTake this sampling tube and go to the mouth of the river to our north.  Proceed inland to the first waterfall and draw a sample from the pool there.  You'll see a bridge overhead.  Once you have a sample, return to me in Auberdine." },
            { ids = { 4763 }, name = "The Blackwood Corrupted", level = 18, zone = "Darkshore", giver = "Thundris Windweaver", giverMap = 1439, giverX = 37.4, giverY = 40.1, ender = "Thundris Windweaver", enderMap = 1439, enderX = 37.4, enderY = 40.1, objective = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.$B$BGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.$B$BMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.$B$BTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.", summary = "We've learned that a source of furbolg corruption is from the satyr.  They hold sway via talismans that they channel magic through.  If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!$B$BFill this bowl at our moonwell and take samples of the furbolgs' food from their northern camp.  Mix them and place it near the bonfire by the river; any furbolgs who eat will be cleansed just long enough to lure out the satyr corruptor... who then you must slay!" },
        },
    },
    {
        id = "q6344",
        name = "Flight to Auberdine",
        zone = "Darnassus",
        minLevel = 10,
        maxLevel = 10,
        importance = 1,
        kind = "world",
        races = { 4 },
        quests = {
            { ids = { 6344 }, name = "Nessa Shadowsong", level = 10, zone = "Darnassus", giver = "Mydrannul", giverMap = 1457, giverX = 70.7, giverY = 45.4, ender = "Nessa Shadowsong", enderMap = 1438, enderX = 56.3, enderY = 92.4, objective = "Speak with Nessa Shadowsong.", summary = "A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village.  She needs a parcel taken to Darkshore, and is looking for someone to help her.$B$BIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village.  You will find the portal west of the Temple Gardens." },
            { ids = { 6341 }, name = "The Bounty of Teldrassil", level = 10, zone = "Teldrassil", giver = "Nessa Shadowsong", giverMap = 1438, giverX = 56.3, giverY = 92.4, ender = "Vesprystus", enderMap = 1438, enderX = 58.4, enderY = 94.0, objective = "Bring Nessa's Collection to Vesprystus.", summary = "The fishermen of Rut'theran village do very well, for the fish here are extremely large and abundant.  I would like to compare the bounty here with that of the mainland.$B$BI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore.  His name is Laird, he is a fish vendor in the village of Auberdine.$B$BBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine." },
            { ids = { 6342 }, name = "Flight to Auberdine", level = 10, zone = "Teldrassil", giver = "Vesprystus", giverMap = 1438, giverX = 58.4, giverY = 94.0, ender = "Laird", enderMap = 1439, enderX = 36.8, enderY = 44.3, objective = "Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird.", summary = "From Rut'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph.  Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.$B$BIt is sound advice to speak with the hippogryph master in every town that has one.  Once you speak to the master, you can then fly there from other towns.$B$BHere is Nessa's collection.  Speak with me again when you are ready to fly to Auberdine and deliver Nessa's collection to Laird." },
            { ids = { 6343 }, name = "Return to Nessa", level = 10, zone = "Darkshore", giver = "Laird", giverMap = 1439, giverX = 36.8, giverY = 44.3, ender = "Nessa Shadowsong", enderMap = 1438, enderX = 56.3, enderY = 92.4, objective = "Bring Laird's Response to Nessa Shadowsong.", summary = "I must send a response to Nessa.  She'll be very interested to know how different the fish here are from those along Teldrassil's coastline.  We can only guess the cause, but it is my suspicion that the world tree itself is affecting the wildlife around it!$B$BPlease, take this response to Nessa.  If you wish to take a hippogryph back to Rut'theran then speak with the hippogryph master Caylais Moonfeather.  If you wish to take the ferry, then one regularly departs from the dock to the northwest." },
        },
    },
    {
        id = "q6181",
        name = "A Swift Message",
        zone = "Westfall",
        minLevel = 10,
        maxLevel = 10,
        importance = 1,
        kind = "world",
        races = { 1 },
        quests = {
            { ids = { 6181 }, name = "A Swift Message", level = 10, zone = "Westfall", giver = "Quartermaster Lewis", giverMap = 1436, giverX = 57, giverY = 47.2, ender = "Thor", enderMap = 1436, enderX = 56.5, enderY = 52.6, objective = "Bring Lewis' Note to Thor the gryphon master.", summary = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.$B$BOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?$B$BThe fastest way to Stormwind is through Thor, our gryphon master.  He's just down the hill; bring him my note, and then take a gryphon to Stormwind." },
            { ids = { 6281 }, name = "Continue to Stormwind", level = 10, zone = "Westfall", giver = "Thor", giverMap = 1436, giverX = 56.5, giverY = 52.6, ender = "Osric Strang", enderMap = 1453, enderX = 77.2, enderY = 61.0, objective = "Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", summary = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Lewis' note to Osric.  You won't get there faster any other way.$B$BIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!" },
            { ids = { 6261 }, name = "Dungar Longdrink", level = 10, zone = "Stormwind City", giver = "Osric Strang", giverMap = 1453, giverX = 77.2, giverY = 61.0, ender = "Dungar Longdrink", enderMap = 1453, enderX = 71.0, enderY = 72.5, objective = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", summary = "$N, I gathered into this crate everything Lewis asked for.  Can you take it to him?$B$BIf you've already spoken to Thor in Westfall, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.$B$BSpeak with Dungar, then get this crate to Lewis as fast as you can.  We don't want our fighting men and women in Westfall to go without fresh equipment!" },
            { ids = { 6285 }, name = "Return to Lewis", level = 10, zone = "Stormwind City", giver = "Dungar Longdrink", giverMap = 1453, giverX = 71.0, giverY = 72.5, ender = "Quartermaster Lewis", enderMap = 1436, enderX = 57, enderY = 47.2, objective = "Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill.", summary = "The gryphon master in Westfall is Thor.  If you've spoken to him before, then you can take one of my gryphons to him.$B$BThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.$B$BYou've already been to Thor, so just speak with me again when you're ready to take a gryphon to Westfall.  Once there, you can deliver Osric's Crate to Quartermaster Lewis." },
        },
    },
    {
        id = "q2997",
        name = "The Tome of Divinity",
        zone = "Dun Morogh",
        minLevel = 12,
        maxLevel = 13,
        importance = 2,
        kind = "class",
        races = { 3 },
        classes = { 2 },
        quests = {
            { ids = { 2997 }, name = "Tome of Divinity", level = 12, zone = "Dun Morogh", giver = "Azar Stronghammer", giverMap = 1426, giverX = 47.6, giverY = 52.1, ender = "Tiza Battleforge", enderMap = 1455, enderX = 27.6, enderY = 12.2, objective = "Speak to Tiza Battleforge in Ironforge.", summary = "Hello, $N. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.$B$BYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, $N." },
            { ids = { 1646 }, name = "The Tome of Divinity", level = 12, ender = "Tiza Battleforge", enderMap = 1455, enderX = 27.6, enderY = 12.2, objective = "Speak to Tiza Battleforge in Ironforge.", summary = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it." },
            { ids = { 1647 }, name = "The Tome of Divinity", level = 12, zone = "Ironforge", giver = "Tiza Battleforge", giverMap = 1455, giverX = 27.6, giverY = 12.2, ender = "John Turner", enderMap = 1455, enderX = 23.3, enderY = 61.9, objective = "Search the outer ring of Ironforge for John Turner.", summary = "Your task then, $N, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.$B$BDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also." },
            { ids = { 1648 }, name = "The Tome of Divinity", level = 13, zone = "Ironforge", giver = "John Turner", giverMap = 1455, giverX = 23.3, giverY = 61.9, ender = "John Turner", enderMap = 1455, enderX = 23.3, enderY = 61.9, objective = "Bring 10 Linen Cloth to John Turner in Ironforge.", summary = "My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.$B$BThis trip's been agonizingly slow, and not very productive.$B$BIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home." },
            { ids = { 1778 }, name = "The Tome of Divinity", level = 13, zone = "Ironforge", giver = "John Turner", giverMap = 1455, giverX = 23.3, giverY = 61.9, ender = "Tiza Battleforge", enderMap = 1455, enderX = 27.6, enderY = 12.2, objective = "Speak to Tiza Battleforge in Ironforge.", summary = "I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, $c." },
            { ids = { 1779 }, name = "The Tome of Divinity", level = 13, zone = "Ironforge", giver = "Tiza Battleforge", giverMap = 1455, giverX = 27.6, giverY = 12.2, ender = "Muiredon Battleforge", enderMap = 1455, enderX = 23.5, enderY = 8.3, objective = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.", summary = "I want you to take this, $N. It is called the Symbol of Life.$B$BYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.$B$BMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.$B$BTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you." },
            { ids = { 1783 }, name = "The Tome of Divinity", level = 13, zone = "Ironforge", giver = "Muiredon Battleforge", giverMap = 1455, giverX = 23.5, giverY = 8.3, ender = "Narm Faulk", enderMap = 1426, enderX = 78.3, enderY = 58.1, objective = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.", summary = "We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.$B$BNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.$B$BNarm needs help, an' I'll not rest till he gets it.$B$BC'n ya help, $N?" },
            { ids = { 1784 }, name = "The Tome of Divinity", level = 13, zone = "Dun Morogh", giver = "Narm Faulk", giverMap = 1426, giverX = 78.3, giverY = 58.1, ender = "Muiredon Battleforge", enderMap = 1455, enderX = 23.5, enderY = 8.3, objective = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.", summary = "Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.$B$BSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.$B$BGet one of those scripts and take it back to Muiredon, $N." },
            { ids = { 1785 }, name = "The Tome of Divinity", level = 13, zone = "Ironforge", giver = "Muiredon Battleforge", giverMap = 1455, giverX = 23.5, giverY = 8.3, ender = "Tiza Battleforge", enderMap = 1455, enderX = 27.6, enderY = 12.2, objective = "Speak to Tiza Battleforge in Ironforge.", summary = "I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.$B$BLight be witcha, mighty $c. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes." },
        },
    },
    {
        id = "q2998",
        name = "The Tome of Divinity",
        zone = "Elwynn Forest",
        minLevel = 12,
        maxLevel = 13,
        importance = 2,
        kind = "class",
        races = { 1 },
        classes = { 2 },
        quests = {
            { ids = { 2998 }, name = "Tome of Divinity", level = 12, zone = "Elwynn Forest", giver = "Brother Wilhelm", giverMap = 1429, giverX = 41.1, giverY = 66.0, ender = "Duthorian Rall", enderMap = 1453, enderX = 50.5, enderY = 47.5, objective = "Speak to Duthorian Rall in Stormwind.", summary = "Greetings, $Gbrother:sister;. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.$B$BIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time." },
            { ids = { 1642 }, name = "The Tome of Divinity", level = 12, ender = "Duthorian Rall", enderMap = 1453, enderX = 50.5, enderY = 47.5, objective = "Speak to Duthorian Rall in Stormwind.", summary = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it." },
            { ids = { 1643 }, name = "The Tome of Divinity", level = 12, zone = "Stormwind City", giver = "Duthorian Rall", giverMap = 1453, giverX = 50.5, giverY = 47.5, ender = "Stephanie Turner", enderMap = 1453, enderX = 63.8, enderY = 72.2, objective = "Search the Trade District of Stormwind for Stephanie Turner.", summary = "Your task then, $N, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.$B$BDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light." },
            { ids = { 1644 }, name = "The Tome of Divinity", level = 13, zone = "Stormwind City", giver = "Stephanie Turner", giverMap = 1453, giverX = 63.8, giverY = 72.2, ender = "Stephanie Turner", enderMap = 1453, enderX = 63.8, enderY = 72.2, objective = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.", summary = "Bless their hearts, most of them have no families because of the Scourge attacks in the last decade.$B$BMy husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads.$B$BWhat's that? You'd be willing to help? Oh, thank the Light, and thank you, $N.$B$BIf you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so much." },
            { ids = { 1780 }, name = "The Tome of Divinity", level = 13, zone = "Stormwind City", giver = "Stephanie Turner", giverMap = 1453, giverX = 63.8, giverY = 72.2, ender = "Duthorian Rall", enderMap = 1453, enderX = 50.5, enderY = 47.5, objective = "Speak to Duthorian Rall in Stormwind.", summary = "I'll take these to the children this very day. Please be safe, good $c. It is not often $G men:women; of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.$B$BFarewell." },
            { ids = { 1781 }, name = "The Tome of Divinity", level = 13, zone = "Stormwind City", giver = "Duthorian Rall", giverMap = 1453, giverX = 50.5, giverY = 47.5, ender = "Gazin Tenorm", enderMap = 1453, enderX = 49.5, enderY = 45.0, objective = "Take the Symbol of Life to Gazin Tenorm in Stormwind.", summary = "Take this, $N. It is called the Symbol of Life.$B$BYou've proven charitable and patient, and now the time has come to see if you're powerful enough to focus one of the Light's greatest gifts.$B$BMy friend Gazin returned recently from an encounter with some Defias in Elwynn near Heroes' Vigil--he barely escaped with his life. He's near the altar having his wounds healed by our priests.$B$BTake the Symbol and speak to him. If you can help him, then we will speak again soon. May you bask in the Light's glory." },
            { ids = { 1786 }, name = "The Tome of Divinity", level = 13, zone = "Stormwind City", giver = "Gazin Tenorm", giverMap = 1453, giverX = 49.5, giverY = 45.0, ender = "Henze Faulk", enderMap = 1429, enderX = 72.6, enderY = 51.4, objective = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.", summary = "Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.$B$BWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.$B$BHenze held them off for me while I escaped... the daft fool, going and being brave.$B$BHe's out there now, Henze is. Can you help us, $N?" },
            { ids = { 1787 }, name = "The Tome of Divinity", level = 13, zone = "Elwynn Forest", giver = "Henze Faulk", giverMap = 1429, giverX = 72.6, giverY = 51.4, ender = "Gazin Tenorm", enderMap = 1453, enderX = 49.5, enderY = 45.0, objective = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.", summary = "We'll have time to talk more about the Symbol at a later time. What's important now is to get those papers we saw the Defias going over. If we can get our hands on them, we'll be able to prove the Defias have infiltrated Elwynn and hopefully gain some insight into what their plans are.$B$BI'm in no shape for battle as of now, $N. Do you think you're strong enough to get those papers from the Defias here on the island?$B$BIf you're able to get them, bring them back to Gazin and let him know I'm all right." },
            { ids = { 1788 }, name = "The Tome of Divinity", level = 13, zone = "Stormwind City", giver = "Gazin Tenorm", giverMap = 1453, giverX = 49.5, giverY = 45.0, ender = "Duthorian Rall", enderMap = 1453, enderX = 50.5, enderY = 47.5, objective = "Speak to Duthorian Rall in Stormwind.", summary = "I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!$B$BThank you again, $N. I hope we meet again. You're surely an ally I'm proud to call friend." },
        },
    },
    {
        id = "q965",
        name = "The Tower of Althalaxx",
        zone = "Darkshore",
        minLevel = 13,
        maxLevel = 31,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 965 }, name = "The Tower of Althalaxx", level = 18, zone = "Darkshore", giver = "Sentinel Elissa Starbreeze", giverMap = 1439, giverX = 39.0, giverY = 43.5, ender = "Balthule Shadowstrike", enderMap = 1439, enderX = 55.0, enderY = 24.9, objective = "Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.", summary = "Hail, young $r. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.$b$bTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.$b$bIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well." },
            { ids = { 966 }, name = "The Tower of Althalaxx", level = 18, zone = "Darkshore", giver = "Balthule Shadowstrike", giverMap = 1439, giverX = 55.0, giverY = 24.9, ender = "Balthule Shadowstrike", enderMap = 1439, enderX = 55.0, enderY = 24.9, objective = "Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.", summary = "A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.$b$bDelgren suspected such a company might be gathering at the tower, but did not know why.$b$bA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!" },
            { ids = { 967 }, name = "The Tower of Althalaxx", level = 18, zone = "Darkshore", giver = "Balthule Shadowstrike", giverMap = 1439, giverX = 55.0, giverY = 24.9, ender = "Delgren the Purifier", enderMap = 1440, enderX = 26.2, enderY = 38.7, objective = "Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.", summary = "My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.$b$bDelgren must know of the cult's operations immediately.$b$bYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour." },
            { ids = { 970 }, name = "The Tower of Althalaxx", level = 21, zone = "Ashenvale", giver = "Delgren the Purifier", giverMap = 1440, giverX = 26.2, giverY = 38.7, ender = "Delgren the Purifier", enderMap = 1440, enderX = 26.2, enderY = 38.7, objective = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.", summary = "Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power.$b$bBring it to me, and I will be able to decipher the secrets held within." },
            { ids = { 973 }, name = "The Tower of Althalaxx", level = 24, zone = "Ashenvale", giver = "Delgren the Purifier", giverMap = 1440, giverX = 26.2, giverY = 38.7, ender = "Delgren the Purifier", enderMap = 1440, enderX = 26.2, enderY = 38.7, objective = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.", summary = "Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale.$b$bHe had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come." },
            { ids = { 1140 }, name = "The Tower of Althalaxx", level = 28, zone = "Ashenvale", giver = "Delgren the Purifier", giverMap = 1440, giverX = 26.2, giverY = 38.7, ender = "Delgren the Purifier", enderMap = 1440, enderX = 26.2, enderY = 38.7, objective = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.", summary = "The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.$b$bFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.$b$bBe careful out there, $n, the satyrs' blood-soaked temples can be unsettling even for a seasoned $c such as yourself." },
            { ids = { 1167 }, name = "The Tower of Althalaxx", level = 28, zone = "Ashenvale", giver = "Delgren the Purifier", giverMap = 1440, giverX = 26.2, giverY = 38.7, ender = "Balthule Shadowstrike", enderMap = 1439, enderX = 55.0, enderY = 24.9, objective = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.", summary = "Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments." },
            { ids = { 1143 }, name = "The Tower of Althalaxx", level = 31, zone = "Darkshore", giver = "Balthule Shadowstrike", giverMap = 1439, giverX = 55.0, giverY = 24.9, ender = "Balthule Shadowstrike", enderMap = 1439, enderX = 55.0, enderY = 24.9, objective = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.", summary = "I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before." },
            { ids = { 981 }, name = "The Tower of Althalaxx", level = 31, zone = "Darkshore", giver = "Balthule Shadowstrike", giverMap = 1439, giverX = 55.0, giverY = 24.9, ender = "Delgren the Purifier", enderMap = 1440, enderX = 26.2, enderY = 38.7, objective = "Talk to Delgren the Purifier at Maestra's Post.", summary = "For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered." },
        },
    },
    {
        id = "q65",
        name = "The Defias Brotherhood",
        zone = "Westfall",
        minLevel = 14,
        maxLevel = 22,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 65 }, name = "The Defias Brotherhood", level = 18, zone = "Westfall", giver = "Gryan Stoutmantle", giverMap = 1436, giverX = 56.3, giverY = 47.5, ender = "Wiley the Black", enderMap = 1433, enderX = 21.4, enderY = 45.4, objective = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.", summary = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.$b$bTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can." },
            { ids = { 132 }, name = "The Defias Brotherhood", level = 18, zone = "Redridge Mountains", giver = "Wiley the Black", giverMap = 1433, giverX = 21.4, giverY = 45.4, ender = "Gryan Stoutmantle", enderMap = 1436, enderX = 56.3, enderY = 47.5, objective = "Take Wiley's Note to Gryan Stoutmantle in Westfall.", summary = "What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.$b$bTake this note to Stoutmantle.  It explains as much as I know on the subject." },
            { ids = { 135 }, name = "The Defias Brotherhood", level = 18, zone = "Westfall", giver = "Gryan Stoutmantle", giverMap = 1436, giverX = 56.3, giverY = 47.5, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Take Wiley's Note to Mathias Shaw in Stormwind.", summary = "I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town." },
            { ids = { 141 }, name = "The Defias Brotherhood", level = 18, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Gryan Stoutmantle", enderMap = 1436, enderX = 56.3, enderY = 47.5, objective = "Take Shaw's report to Gryan Stoutmantle in Westfall.", summary = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.$b$bI have written a more detailed account for your Master in Westfall.  Take this to him at once!" },
            { ids = { 142 }, name = "The Defias Brotherhood", level = 18, zone = "Westfall", giver = "Gryan Stoutmantle", giverMap = 1436, giverX = 56.3, giverY = 47.5, ender = "Gryan Stoutmantle", enderMap = 1436, enderX = 56.3, enderY = 47.5, objective = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", summary = "We need to discover the location of the Defias hideout.  $N, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying." },
            { ids = { 155 }, name = "The Defias Brotherhood", level = 18, zone = "Westfall", giver = "The Defias Traitor", giverMap = 1436, giverX = 55.7, giverY = 47.5, ender = "Gryan Stoutmantle", enderMap = 1436, enderX = 56.3, enderY = 47.5, objective = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood.  Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", summary = "So Stoutmantle sends a scrawny $r like you to protect me?  Guess you'll have to do.  Better bring some friends too. $b$bYou know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me.$b$bLet me know when you and any friends you can round up are ready to go." },
            { ids = { 166 }, name = "The Defias Brotherhood", level = 22, zone = "Westfall", giver = "Gryan Stoutmantle", giverMap = 1436, giverX = 56.3, giverY = 47.5, ender = "Gryan Stoutmantle", enderMap = 1436, enderX = 56.3, enderY = 47.5, objective = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.", summary = "There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done." },
        },
    },
    {
        id = "q120",
        name = "Messenger to Westfall",
        zone = "Redridge Mountains",
        minLevel = 14,
        maxLevel = 18,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 120 }, name = "Messenger to Stormwind", level = 14, zone = "Redridge Mountains", giver = "Magistrate Solomon", giverMap = 1433, giverX = 24.9, giverY = 44.5, ender = "General Marcus Jonathan", enderMap = 1453, enderX = 69.2, enderY = 82.7, objective = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind.  The judge wants you to return to him as soon as the delivery has been made.", summary = "These are trying times, $c.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. $b$bNow make haste!" },
            { ids = { 121 }, name = "Messenger to Stormwind", level = 14, zone = "Stormwind City", giver = "General Marcus Jonathan", giverMap = 1453, giverX = 69.2, giverY = 82.7, ender = "Magistrate Solomon", enderMap = 1433, enderX = 24.9, enderY = 44.5, objective = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.", summary = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. $b$bDismissed, $c!" },
            { ids = { 143 }, name = "Messenger to Westfall", level = 14, zone = "Redridge Mountains", giver = "Magistrate Solomon", giverMap = 1433, giverX = 24.9, giverY = 44.5, ender = "Gryan Stoutmantle", enderMap = 1436, enderX = 56.3, enderY = 47.5, objective = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.", summary = "Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.$b$bTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves." },
            { ids = { 144 }, name = "Messenger to Westfall", level = 14, zone = "Westfall", giver = "Gryan Stoutmantle", giverMap = 1436, giverX = 56.3, giverY = 47.5, ender = "Magistrate Solomon", enderMap = 1433, enderX = 24.9, enderY = 44.5, objective = "Return to Magistrate Solomon with Gryan Stoutmantle's response.", summary = "Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.$b$bTake this response to your master in Redridge, $c.  And let him know that my heart is heavy with the loss of good men." },
            { ids = { 145 }, name = "Messenger to Darkshire", level = 18, zone = "Redridge Mountains", giver = "Magistrate Solomon", giverMap = 1433, giverX = 24.9, giverY = 44.5, ender = "Lord Ello Ebonlocke", enderMap = 1431, enderX = 71.9, enderY = 46.4, objective = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.", summary = "I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads." },
            { ids = { 146 }, name = "Messenger to Darkshire", level = 18, zone = "Duskwood", giver = "Lord Ello Ebonlocke", giverMap = 1431, giverX = 71.9, giverY = 46.4, ender = "Magistrate Solomon", enderMap = 1433, enderX = 24.9, enderY = 44.5, objective = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.", summary = "If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge.$b$bTake this letter of response to your Master in Lakeshire." },
        },
    },
    {
        id = "q730",
        name = "The Absent Minded Prospector",
        zone = "Darnassus",
        minLevel = 14,
        maxLevel = 24,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 730 }, name = "Trouble In Darkshore?", level = 14, zone = "Darnassus", giver = "Chief Archaeologist Greywhisker", giverMap = 1457, giverX = 31.2, giverY = 84.5, ender = "Archaeologist Hollee", enderMap = 1439, enderX = 37.4, enderY = 41.8, objective = "Travel to Auberdine and look for signs of the dwarven excavation team.", summary = "How nice it is to see a $c interested in the great archeological wonders of our world.$b$bOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.$b$bI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.$b$bTravel to Auberdine and look for a clue as to their whereabouts." },
            { ids = { 729 }, name = "The Absent Minded Prospector", level = 20, zone = "Darkshore", giver = "Archaeologist Hollee", giverMap = 1439, giverX = 37.4, giverY = 41.8, ender = "Prospector Remtravel", enderMap = 1439, enderX = 35.7, enderY = 83.7, objective = "Travel south and check on Prospector Remtravel.", summary = "What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.$b$bBut the prospector is rather... um... oblivious ...to his surroundings.$b$bWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.$b$bPlease travel south and see if the prospector is ok!" },
            { ids = { 731 }, name = "The Absent Minded Prospector", level = 20, zone = "Darkshore", giver = "Prospector Remtravel", giverMap = 1439, giverX = 35.7, giverY = 83.7, ender = "Archaeologist Hollee", enderMap = 1439, enderX = 37.4, enderY = 41.8, objective = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.", summary = "So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?$b$bBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.$b$bLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.$b$bSo are you ready yet?" },
            { ids = { 741 }, name = "The Absent Minded Prospector", level = 20, zone = "Darkshore", giver = "Archaeologist Hollee", giverMap = 1439, giverX = 37.4, giverY = 41.8, ender = "Chief Archaeologist Greywhisker", enderMap = 1457, enderX = 31.2, enderY = 84.5, objective = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", summary = "So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.$b$bHere, $n, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus." },
            { ids = { 942 }, name = "The Absent Minded Prospector", level = 20, zone = "Darnassus", giver = "Chief Archaeologist Greywhisker", giverMap = 1457, giverX = 31.2, giverY = 84.5, ender = "Archaeologist Flagongut", enderMap = 1437, enderX = 10.8, enderY = 60.4, objective = "Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.", summary = "This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.$b$bLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.$b$bThe ship to Menethil departs from Auberdine." },
            { ids = { 943 }, name = "The Absent Minded Prospector", level = 24, zone = "Wetlands", giver = "Archaeologist Flagongut", giverMap = 1437, giverX = 10.8, giverY = 60.4, ender = "Archaeologist Flagongut", enderMap = 1437, enderX = 10.8, enderY = 60.4, objective = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.", summary = "Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil.$b$bWhile I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts.$B$BBring me both the Stone of Relu, and the original fossil he holds." },
        },
    },
    {
        id = "q373",
        name = "The Unsent Letter",
        zone = "Stormwind City",
        minLevel = 16,
        maxLevel = 31,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 373 }, name = "The Unsent Letter", level = 22, zone = "Stormwind City", ender = "Baros Alexston", enderMap = 1453, enderX = 57.7, enderY = 47.9, objective = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.", summary = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.$B$BIt appears to be recently written and sealed." },
            { ids = { 389 }, name = "Bazil Thredd", level = 22, zone = "Stormwind City", giver = "Baros Alexston", giverMap = 1453, giverX = 57.7, giverY = 47.9, ender = "Warden Thelwater", enderMap = 1453, enderX = 51.5, enderY = 69.4, objective = "Speak with Warden Thelwater in the Stockade.", summary = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.$B$BWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.$b$bHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade." },
            { ids = { 391 }, name = "The Stockade Riots", level = 29, zone = "Stormwind City", giver = "Warden Thelwater", giverMap = 1453, giverX = 51.5, giverY = 69.4, ender = "Warden Thelwater", enderMap = 1453, enderX = 51.5, enderY = 69.4, objective = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.", summary = "Let's get one thing straight, $N: I don't trust you. But, with the situation as it is, you probably won't make a difference.$B$BSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots." },
            { ids = { 392 }, name = "The Curious Visitor", level = 29, zone = "Stormwind City", giver = "Warden Thelwater", giverMap = 1453, giverX = 51.5, giverY = 69.4, ender = "Baros Alexston", enderMap = 1453, enderX = 57.7, enderY = 47.9, objective = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.", summary = "During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.$B$BAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.$B$BHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore." },
            { ids = { 393 }, name = "Shadow of the Past", level = 29, zone = "Stormwind City", giver = "Baros Alexston", giverMap = 1453, giverX = 57.7, giverY = 47.9, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.", summary = "I really haven't a clue, $N. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.$B$BIf anyone knows, it'd be him." },
            { ids = { 350 }, name = "Look to an Old Friend", level = 31, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Elling Trias", enderMap = 1453, enderX = 66.0, enderY = 74.1, objective = "Speak to Elling Trias in Stormwind.", summary = "That Marzon would be contacting a member of the Defias and have ties to Lescovar...$B$BHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.$B$BYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city." },
            { ids = { 2745 }, name = "Infiltrating the Castle", level = 31, zone = "Stormwind City", giver = "Elling Trias", giverMap = 1453, giverX = 66.0, giverY = 74.1, ender = "Tyrion", enderMap = 1453, enderX = 73.2, enderY = 35.6, objective = "Speak to Tyrion in Stormwind Castle.", summary = "Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.$B$BLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?$B$BYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this." },
            { ids = { 2746 }, name = "Items of Some Consequence", level = 31, zone = "Stormwind City", giver = "Tyrion", giverMap = 1453, giverX = 73.2, giverY = 35.6, ender = "Tyrion", enderMap = 1453, enderX = 73.2, enderY = 35.6, objective = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.", summary = "Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get $g his:her; hands dirty, understand? Good.$B$BOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.$B$BBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples." },
            { ids = { 434 }, name = "The Attack!", level = 31, zone = "Stormwind City", giver = "Tyrion", giverMap = 1453, giverX = 73.2, giverY = 35.6, ender = "Elling Trias", enderMap = 1453, enderX = 66.0, enderY = 74.1, objective = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.", summary = "After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.$B$BWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.$B$BLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias." },
            { ids = { 394 }, name = "The Head of the Beast", level = 31, zone = "Stormwind City", giver = "Elling Trias", giverMap = 1453, giverX = 66.0, giverY = 74.1, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Speak to Mathias Shaw in Stormwind.", summary = "Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.$B$BHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, $N. The nobles can think they rule the city all they want, but some things remain out of their hands." },
            { ids = { 395 }, name = "Brotherhood's End", level = 31, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Baros Alexston", enderMap = 1453, enderX = 57.7, enderY = 47.9, objective = "Speak with Baros Alexston in Stormwind.", summary = "Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.$B$BA bit of advice, $N: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.$B$BAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it." },
            { ids = { 396 }, name = "An Audience with the King", level = 31, zone = "Stormwind City", giver = "Baros Alexston", giverMap = 1453, giverX = 57.7, giverY = 47.9, ender = "Lady Katrana Prestor", enderMap = 1453, enderX = 80.1, enderY = 38.2, objective = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.", summary = "I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.$B$BYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep." },
        },
    },
    {
        id = "q250",
        name = "A Dark Threat Looms",
        zone = "Loch Modan",
        minLevel = 16,
        maxLevel = 20,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 250 }, name = "A Dark Threat Looms", level = 18, zone = "Loch Modan", giver = "Chief Engineer Hinderweir VII", giverMap = 1432, giverX = 46.0, giverY = 13.6, ender = "Suspicious Barrel", enderMap = 1432, enderX = 56.0, enderY = 13.2, objective = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.", summary = "Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector.$b$bThat's why I need you, $N.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue." },
            { ids = { 199 }, name = "A Dark Threat Looms", level = 18, zone = "Loch Modan", giver = "Suspicious Barrel", giverMap = 1432, giverX = 56.0, giverY = 13.2, ender = "Chief Engineer Hinderweir VII", enderMap = 1432, enderX = 46.0, enderY = 13.6, objective = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.", summary = "You take a sample of the strange smelling powder." },
            { ids = { 161 }, name = "A Dark Threat Looms", level = 18, zone = "Loch Modan", giver = "Chief Engineer Hinderweir VII", giverMap = 1432, giverX = 46.0, giverY = 13.6, ender = "Ashlan Stonesmirk", enderMap = 1437, enderX = 50.0, enderY = 18.2, objective = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert in Dun Modr.", summary = "If my suspicions are correct, this is some type of explosive powder.  This must be analyzed by an explosives expert so we know just what we're dealing with here.  Ashlan Stonesmirk was assigned to the regiment guarding Dun Modr and the Thandol Span.  I need you to make a grave and perilous journey, $N.$b$bTravel through the Algaz Gate, follow the road through the Wetlands and seek out Stonesmirk in Dun Modr.  Heed my advice: stick to the roads and stop for nothing!" },
            { ids = { 274 }, name = "A Dark Threat Looms", level = 18, zone = "Wetlands", giver = "Ashlan Stonesmirk", giverMap = 1437, giverX = 50.0, giverY = 18.2, ender = "Chief Engineer Hinderweir VII", enderMap = 1432, enderX = 46.0, enderY = 13.6, objective = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery.", summary = "This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain.$b$bThe chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!" },
            { ids = { 278 }, name = "A Dark Threat Looms", level = 18, zone = "Loch Modan", giver = "Chief Engineer Hinderweir VII", giverMap = 1432, giverX = 46.0, giverY = 13.6, ender = "Chief Engineer Hinderweir VII", enderMap = 1432, enderX = 46.0, enderY = 13.6, objective = "Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.", summary = "Begin collecting the disarming materials immediately, $N.  Lurker Venom can be found on the indigenous spiders in Loch Modan.  Crocolisk tears are found here in the Loch as well.  But a Mo'Grosh crystal will be very difficult to procure.  The ogres to the northeast mine them but the crystals are a very rare commodity.$b$bWe need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture." },
            { ids = { 280 }, name = "A Dark Threat Looms", level = 18, zone = "Loch Modan", giver = "Chief Engineer Hinderweir VII", giverMap = 1432, giverX = 46.0, giverY = 13.6, ender = "Explosive Charge", enderMap = 1432, enderX = 50.6, enderY = 14.3, objective = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.", summary = "Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg.  No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!  Let me combine all these ingredients into the Disarming Mixture.  There we go.$b$bNow I need you to take this mixture and stir it into the keg before it's too late!  Hurry!" },
            { ids = { 283 }, name = "A Dark Threat Looms", level = 20, zone = "Loch Modan", giver = "Explosive Charge", giverMap = 1432, giverX = 50.6, giverY = 14.3, ender = "Chief Engineer Hinderweir VII", enderMap = 1432, enderX = 46.0, enderY = 13.6, objective = "The Disarming Mixture seemed to take effect.  Return to Chief Engineer Hinderweir to report the good news.", summary = "The keg fizzles slightly." },
        },
    },
    {
        id = "q1483",
        name = "Super Reaper 6000",
        zone = "The Barrens",
        minLevel = 16,
        maxLevel = 27,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1483 }, name = "Ziz Fizziks", level = 21, zone = "The Barrens", giver = "Sputtervalve", giverMap = 1413, giverX = 63.0, giverY = 37.2, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Speak with Ziz Fizziks in Windshear Crag.", summary = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.$b$bA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.$b$bMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag." },
            { ids = { 1093 }, name = "Super Reaper 6000", level = 21, zone = "Stonetalon Mountains", giver = "Ziz Fizziks", giverMap = 1442, giverX = 59.0, giverY = 62.6, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", summary = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!$b$bLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!$b$bTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators." },
            { ids = { 1094 }, name = "Further Instructions", level = 21, zone = "Stonetalon Mountains", giver = "Ziz Fizziks", giverMap = 1442, giverX = 59.0, giverY = 62.6, ender = "Sputtervalve", enderMap = 1413, enderX = 63.0, enderY = 37.2, objective = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.", summary = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.$b$bSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow." },
            { ids = { 1095 }, name = "Further Instructions", level = 27, zone = "The Barrens", giver = "Sputtervalve", giverMap = 1413, giverX = 63.0, giverY = 37.2, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.", summary = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.$b$bRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.$b$bWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him." },
            { ids = { 1096 }, name = "Gerenzo Wrenchwhistle", level = 27, zone = "Stonetalon Mountains", giver = "Ziz Fizziks", giverMap = 1442, giverX = 59.0, giverY = 62.6, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", summary = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.$b$bNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.$b$bIf you kill him for me, I'll make it worth your while!" },
        },
    },
    {
        id = "q1070",
        name = "Reception from Tyrande",
        zone = "Ashenvale",
        minLevel = 17,
        maxLevel = 28,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 1070 }, name = "On Guard in Stonetalon", level = 21, zone = "Ashenvale", giver = "Sentinel Thenysil", giverMap = 1440, giverX = 34.9, giverY = 49.8, ender = "Kaela Shadowspear", enderMap = 1442, enderX = 59.9, enderY = 66.8, objective = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.", summary = "Hello, $N.$B$BYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.$B$BRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.$B$BWould you find her and report back to me?" },
            { ids = { 1085 }, name = "On Guard in Stonetalon", level = 21, zone = "Stonetalon Mountains", giver = "Kaela Shadowspear", giverMap = 1442, giverX = 59.9, giverY = 66.8, ender = "Gaxim Rustfizzle", enderMap = 1442, enderX = 59.5, enderY = 67.2, objective = "Speak to Gaxim.", summary = "The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.$B$BThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.$B$BDo not judge Gaxim prematurely; he understands the need for us to work together.$B$BIf you wish to aid us, then start by speaking to Gaxim.$B$BI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon." },
            { ids = { 1071 }, name = "A Gnome's Respite", level = 21, zone = "Stonetalon Mountains", giver = "Gaxim Rustfizzle", giverMap = 1442, giverX = 59.5, giverY = 67.2, ender = "Gaxim Rustfizzle", enderMap = 1442, enderX = 59.5, enderY = 67.2, objective = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.", summary = "You see, $N, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.$B$BBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!$B$BI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east..." },
            { ids = { 1072 }, name = "An Old Colleague", level = 21, zone = "Stonetalon Mountains", giver = "Gaxim Rustfizzle", giverMap = 1442, giverX = 59.5, giverY = 67.2, ender = "Lomac Gearstrip", enderMap = 1455, enderX = 72.1, enderY = 51.9, objective = "Speak to Lomac Gearstrip in Ironforge.", summary = "The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.$B$BAnd for that, we're going to need some potent explosives: Nitromirglyceronium.$B$BThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.$B$BYou talk him into making us some NG-5, I'll get to work on placement for my devices." },
            { ids = { 1075 }, name = "A Scroll from Mauren", level = 21, zone = "Stonetalon Mountains", giver = "Gaxim Rustfizzle", giverMap = 1442, giverX = 59.5, giverY = 67.2, ender = "Collin Mauren", enderMap = 1453, enderX = 53.0, enderY = 86.6, objective = "Find Collin Mauren in Stormwind.", summary = "Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?$B$BOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.$B$BBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss." },
            { ids = { 1073 }, name = "Ineptitude + Chemicals = Fun", level = 21, zone = "Ironforge", giver = "Lomac Gearstrip", giverMap = 1455, giverX = 72.1, giverY = 51.9, ender = "Lomac Gearstrip", enderMap = 1455, enderX = 72.1, enderY = 51.9, objective = "Bring 4 Minor Mana Potions and 2 Elixirs of Fortitude to Lomac Gearstrip in Ironforge.", summary = "Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!$B$BI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.$B$BThere's a problem though: I'm all out.$B$BBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.$B$BThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation." },
            { ids = { 1076 }, name = "Devils in Westfall", level = 21, zone = "Stormwind City", giver = "Collin Mauren", giverMap = 1453, giverX = 53.0, giverY = 86.6, ender = "Collin Mauren", enderMap = 1453, enderX = 53.0, enderY = 86.6, objective = "Bring Dust Devil Debris to Collin Mauren in Stormwind.", summary = "Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.$B$BI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.$B$BWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.$B$BI'll be here when you return." },
            { ids = { 1074 }, name = "Ineptitude + Chemicals = Fun", level = 21, zone = "Ironforge", giver = "Lomac Gearstrip", giverMap = 1455, giverX = 72.1, giverY = 51.9, ender = "Gaxim Rustfizzle", enderMap = 1442, enderX = 59.5, enderY = 67.2, objective = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.", summary = "Here you go, stranger. Take heed with it though... it's volatile stuff.$B$BIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up." },
            { ids = { 1077 }, name = "Special Delivery for Gaxim", level = 21, zone = "Stormwind City", giver = "Collin Mauren", giverMap = 1453, giverX = 53.0, giverY = 86.6, ender = "Gaxim Rustfizzle", enderMap = 1442, enderX = 59.5, enderY = 67.2, objective = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.", summary = "Here you are, $N. This should do nicely.$B$BPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.$B$BFare well." },
            { ids = { 1079 }, name = "Covert Ops - Alpha", level = 22, zone = "Stonetalon Mountains", giver = "Gaxim Rustfizzle", giverMap = 1442, giverX = 59.5, giverY = 67.2, ender = "Gaxim Rustfizzle", enderMap = 1442, enderX = 59.5, enderY = 67.2, objective = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.", summary = "This is it, $N. Pay close attention. The devices are done, and ready to be used.$B$BTake these pages--they'll explain more about the detonators and explosives, and where you should place them.$B$BRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake." },
            { ids = { 1080 }, name = "Covert Ops - Beta", level = 22, zone = "Stonetalon Mountains", giver = "Gaxim Rustfizzle", giverMap = 1442, giverX = 59.5, giverY = 67.2, ender = "Gaxim Rustfizzle", enderMap = 1442, enderX = 59.5, enderY = 67.2, objective = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.", summary = "Plan Beta's just like Plan Alpha, $N.$B$BWe cause a distraction and then steal their precious letters.$B$BThe key is to get their letters... remember that.$B$BThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters...." },
            { ids = { 1091 }, name = "Kaela's Update", level = 22, zone = "Stonetalon Mountains", giver = "Gaxim Rustfizzle", giverMap = 1442, giverX = 59.5, giverY = 67.2, ender = "Kaela Shadowspear", enderMap = 1442, enderX = 59.9, enderY = 66.8, objective = "Bring the Venture Co. Letters to Kaela Shadowspear.", summary = "$N, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.$B$BMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic." },
            { ids = { 1083 }, name = "Enraged Spirits", level = 26, zone = "Stonetalon Mountains", giver = "Kaela Shadowspear", giverMap = 1442, giverX = 59.9, giverY = 66.8, ender = "Kaela Shadowspear", enderMap = 1442, enderX = 59.9, enderY = 66.8, objective = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.", summary = "I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.$B$BThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.$B$BBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.$B$BThe land has no chance to see Elune's smile while these creatures roam free.$B$BBring me their smoldering embers to show you've reduced their numbers." },
            { ids = { 1084 }, name = "Wounded Ancients", level = 28, zone = "Stonetalon Mountains", giver = "Kaela Shadowspear", giverMap = 1442, giverX = 59.9, giverY = 66.8, ender = "Kaela Shadowspear", enderMap = 1442, enderX = 59.9, enderY = 66.8, objective = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.", summary = "It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.$B$BGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.$B$BI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.$B$BBring me some of the shrapnel so the gnome can tell me more..." },
            { ids = { 1082 }, name = "Update for Sentinel Thenysil", level = 22, zone = "Stonetalon Mountains", giver = "Kaela Shadowspear", giverMap = 1442, giverX = 59.9, giverY = 66.8, ender = "Sentinel Thenysil", enderMap = 1440, enderX = 34.9, enderY = 49.8, objective = "Return to Sentinel Thenysil in Ashenvale.", summary = "$N, you have done a great deed by lending a hand here.$B$BThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.$B$BFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news." },
            { ids = { 1081 }, name = "Reception from Tyrande", level = 28, zone = "Ashenvale", giver = "Sentinel Thenysil", giverMap = 1440, giverX = 34.9, giverY = 49.8, ender = "Tyrande Whisperwind", enderMap = 1457, enderX = 39.1, enderY = 81.6, objective = "Find Tyrande Whisperwind in Darnassus.", summary = "$N, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.$B$BIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.$B$BIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus." },
        },
    },
    {
        id = "q164",
        name = "The Shadowy Figure",
        zone = "Duskwood",
        minLevel = 17,
        maxLevel = 32,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 164 }, name = "Deliveries to Sven", level = 23, zone = "Duskwood", giver = "Elaine Carevin", giverMap = 1431, giverX = 75.3, giverY = 48.8, ender = "Sven Yorgen", enderMap = 1431, enderX = 7.8, enderY = 34.1, objective = "Deliver the supplies to Sven.", summary = "Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.$b$bUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?" },
            { ids = { 95 }, name = "Sven's Revenge", level = 25, zone = "Duskwood", giver = "Sven Yorgen", giverMap = 1431, giverX = 7.8, giverY = 34.1, ender = "Mound of loose dirt", enderMap = 1431, enderX = 49.9, enderY = 77.7, objective = "Go to Sven's Farm and find what was buried behind the old stump.", summary = "I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!$B$BWhen I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden.$B$BIf you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my barn." },
            { ids = { 230 }, name = "Sven's Camp", level = 25, zone = "Duskwood", giver = "Mound of loose dirt", giverMap = 1431, giverX = 49.9, giverY = 77.7, ender = "Sven Yorgen", enderMap = 1431, enderX = 7.8, enderY = 34.1, objective = "Bring the Book from Sven's Farm to Sven.", summary = "Digging through the mound, you find a small, dirt-stained book.$B$BThe book has no title, but...it has information Sven would like to know." },
            { ids = { 262 }, name = "The Shadowy Figure", level = 25, zone = "Duskwood", giver = "Sven Yorgen", giverMap = 1431, giverX = 7.8, giverY = 34.1, ender = "Madame Eva", enderMap = 1431, enderX = 75.8, enderY = 45.3, objective = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.", summary = "I must know who was that skulker in the shadows I saw the night my family was killed!$B$BPlease, $N, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!$B$BI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner." },
            { ids = { 265 }, name = "The Shadowy Search Continues", level = 25, zone = "Duskwood", giver = "Madame Eva", giverMap = 1431, giverX = 75.8, giverY = 45.3, ender = "Clerk Daltry", enderMap = 1431, enderX = 72.5, enderY = 46.9, objective = "See if other townsfolk have clues about the shadowy figure.", summary = "Here is your book back, $N, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.$B$BAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here." },
            { ids = { 266 }, name = "Inquire at the Inn", level = 25, zone = "Duskwood", giver = "Clerk Daltry", giverMap = 1431, giverX = 72.5, giverY = 46.9, ender = "Tavernkeep Smitts", enderMap = 1431, enderX = 73.8, enderY = 44.5, objective = "Search the inn for clues about the shadowy figure.", summary = "Here is your book, and good luck with your inquiries.$B$BYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there." },
            { ids = { 453 }, name = "Finding the Shadowy Figure", level = 25, zone = "Duskwood", giver = "Tavernkeep Smitts", giverMap = 1431, giverX = 73.8, giverY = 44.5, ender = "Jitters", enderMap = 1431, enderX = 18.4, enderY = 56.4, objective = "Find the Shadowy Figure.  Your clues:$B$BHe is not native to Darkshire.$B$BHe is a nervous, jittery person.$B$BHe left Darkshire and headed west.", summary = "Good luck, $N.  I hope you find the chap, and I hope you find him alive.$B$BIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds." },
            { ids = { 268 }, name = "Return to Sven", level = 25, zone = "Duskwood", giver = "Jitters", giverMap = 1431, giverX = 18.4, giverY = 56.4, ender = "Sven Yorgen", enderMap = 1431, enderX = 7.8, enderY = 34.1, objective = "Return to Sven with Jitters' completed journal.", summary = "The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...$B$BHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.$B$BAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!" },
            { ids = { 323 }, name = "Proving Your Worth", level = 28, zone = "Duskwood", giver = "Sven Yorgen", giverMap = 1431, giverX = 7.8, giverY = 34.1, ender = "Sven Yorgen", enderMap = 1431, enderX = 7.8, enderY = 34.1, objective = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.", summary = "Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength.$B$BYou have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions." },
            { ids = { 269 }, name = "Seeking Wisdom", level = 29, zone = "Duskwood", giver = "Sven Yorgen", giverMap = 1431, giverX = 7.8, giverY = 34.1, ender = "Bishop Farthing", enderMap = 1453, enderX = 49.9, enderY = 46.0, objective = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.", summary = "Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel.$B$BAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us.$B$BYour mission is perilous, but hurry, $N.  With each passing hour, the shadows of Duskwood grow ever darker." },
            { ids = { 270 }, name = "The Doomed Fleet", level = 29, zone = "Stormwind City", giver = "Bishop Farthing", giverMap = 1453, giverX = 49.9, giverY = 46.0, ender = "Glorin Steelbrow", enderMap = 1437, enderX = 10.6, enderY = 60.6, objective = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.", summary = "Years ago, the Third Fleet of Kul'Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the Dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron.$B$BThis metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon.$B$BGo to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look." },
            { ids = { 321 }, name = "Lightforge Iron", level = 29, zone = "Wetlands", giver = "Glorin Steelbrow", giverMap = 1437, giverX = 10.6, giverY = 60.6, ender = "Waterlogged Chest", enderMap = 1437, enderX = 12.1, enderY = 64.2, objective = "Search the wreckage of The Flying Osprey in the Wetlands.", summary = "The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.$B$BThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons...$B$BEnough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me." },
            { ids = { 324 }, name = "The Lost Ingots", level = 29, zone = "Wetlands", giver = "Waterlogged Chest", giverMap = 1437, giverX = 12.1, giverY = 64.2, ender = "Glorin Steelbrow", enderMap = 1437, enderX = 10.6, enderY = 60.6, objective = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.", summary = "Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron." },
            { ids = { 322 }, name = "Blessed Arm", level = 29, zone = "Wetlands", giver = "Glorin Steelbrow", giverMap = 1437, giverX = 10.6, giverY = 60.6, ender = "Grimand Elmore", enderMap = 1453, enderX = 59.7, enderY = 33.8, objective = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.", summary = "There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore.$B$BI've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!" },
            { ids = { 325 }, name = "Armed and Ready", level = 29, zone = "Stormwind City", giver = "Grimand Elmore", giverMap = 1453, giverX = 59.7, giverY = 33.8, ender = "Sven Yorgen", enderMap = 1431, enderX = 7.8, enderY = 34.1, objective = "Bring Morbent's Bane to Sven in Duskwood.", summary = "Here is the weapon against the fiend of which you spoke.  You're all ready, $N.  Best of luck to you, and I look forward to your tale of glory!" },
            { ids = { 55 }, name = "Morbent Fel", level = 32, zone = "Duskwood", giver = "Sven Yorgen", giverMap = 1431, giverX = 7.8, giverY = 34.1, ender = "Sven Yorgen", enderMap = 1431, enderX = 7.8, enderY = 34.1, objective = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.", summary = "Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end...$B$BUse Morbent's Bane against him.  It will render his protective magics powerless.$B$BSlay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!" },
        },
    },
    {
        id = "q165",
        name = "Bride of the Embalmer",
        zone = "Duskwood",
        minLevel = 17,
        maxLevel = 30,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 165 }, name = "The Hermit", level = 25, zone = "Duskwood", giver = "Elaine Carevin", giverMap = 1431, giverX = 75.3, giverY = 48.8, ender = "Abercrombie", enderMap = 1431, enderX = 28.1, enderY = 31.5, objective = "Check on the old man in the shack near Raven Hill cemetery.", summary = "There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss." },
            { ids = { 148 }, name = "Supplies from Darkshire", level = 24, zone = "Duskwood", giver = "Abercrombie", giverMap = 1431, giverX = 28.1, giverY = 31.5, ender = "Madame Eva", enderMap = 1431, enderX = 75.8, enderY = 45.3, objective = "Speak with Madame Eva.", summary = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.$B$BCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square." },
            { ids = { 149 }, name = "Ghost Hair Thread", level = 24, zone = "Duskwood", giver = "Madame Eva", giverMap = 1431, giverX = 75.8, giverY = 45.3, ender = "Blind Mary", enderMap = 1431, enderX = 82.0, enderY = 59.1, objective = "Bring the Spectral Comb to Blind Mary.", summary = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.$B$BHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.$B$BAnd take care, for dark things now lurk near that house..." },
            { ids = { 154 }, name = "Return the Comb", level = 24, zone = "Duskwood", giver = "Blind Mary", giverMap = 1431, giverX = 82.0, giverY = 59.1, ender = "Madame Eva", enderMap = 1431, enderX = 75.8, enderY = 45.3, objective = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", summary = "NO!!!!!$B$BTake it, take this comb away from me!$B$BI'm a monster, and no one will ever think me lovely again!" },
            { ids = { 157 }, name = "Deliver the Thread", level = 24, zone = "Duskwood", giver = "Madame Eva", giverMap = 1431, giverX = 75.8, giverY = 45.3, ender = "Abercrombie", enderMap = 1431, enderX = 28.1, enderY = 31.5, objective = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.", summary = "Here is your thread, $N.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects." },
            { ids = { 158 }, name = "Zombie Juice", level = 24, zone = "Duskwood", giver = "Abercrombie", giverMap = 1431, giverX = 28.1, giverY = 31.5, ender = "Tavernkeep Smitts", enderMap = 1431, enderX = 73.8, enderY = 44.5, objective = "Speak with Tavernkeep Smitts.", summary = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.$B$BAnd please hurry, $N.  These nights get cold, and I need that drink to put fire in my veins again!" },
            { ids = { 156 }, name = "Gather Rot Blossoms", level = 24, zone = "Duskwood", giver = "Tavernkeep Smitts", giverMap = 1431, giverX = 73.8, giverY = 44.5, ender = "Tavernkeep Smitts", enderMap = 1431, enderX = 73.8, enderY = 44.5, objective = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.", summary = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.$B$BRot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!$B$BThe Raven Hill Cemetery and the Tranquil Gardens are both lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful." },
            { ids = { 159 }, name = "Juice Delivery", level = 24, zone = "Duskwood", giver = "Tavernkeep Smitts", giverMap = 1431, giverX = 73.8, giverY = 44.5, ender = "Abercrombie", enderMap = 1431, enderX = 28.1, enderY = 31.5, objective = "Bring the Zombie Juice to Abercrombie at his shack.", summary = "Here's your Zombie Juice...$B$B...and be careful with this stuff.  It's strong enough to raise the dead!" },
            { ids = { 133 }, name = "Ghoulish Effigy", level = 27, zone = "Duskwood", giver = "Abercrombie", giverMap = 1431, giverX = 28.1, giverY = 31.5, ender = "Abercrombie", enderMap = 1431, enderX = 28.1, enderY = 31.5, objective = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.", summary = "I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!$B$BI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.$B$BGet the ribs for me, and I will repay you with some coin." },
            { ids = { 134 }, name = "Ogre Thieves", level = 30, zone = "Duskwood", giver = "Abercrombie", giverMap = 1431, giverX = 28.1, giverY = 31.5, ender = "Abercrombie", enderMap = 1431, enderX = 28.1, enderY = 31.5, objective = "Return Abercrombie's Crate to Abercrombie.", summary = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.$B$BAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.$B$BPlease, $N, retrieve this crate for me for I miss it sorely." },
            { ids = { 160 }, name = "Note to the Mayor", level = 30, zone = "Duskwood", giver = "Abercrombie", giverMap = 1431, giverX = 28.1, giverY = 31.5, ender = "Lord Ello Ebonlocke", enderMap = 1431, enderX = 71.9, enderY = 46.4, objective = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", summary = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.$B$BHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!" },
            { ids = { 251 }, name = "Translate Abercrombie's Note", level = 30, zone = "Duskwood", giver = "Lord Ello Ebonlocke", giverMap = 1431, giverX = 71.9, giverY = 46.4, ender = "Sirra Von'Indi", enderMap = 1431, enderX = 72.6, enderY = 47.6, objective = "Bring the Letter to Ello to Sirra Von'Indi.", summary = "Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he." },
            { ids = { 401 }, name = "Wait for Sirra to Finish", level = 30, zone = "Duskwood", giver = "Sirra Von'Indi", giverMap = 1431, giverX = 72.6, giverY = 47.6, ender = "Sirra Von'Indi", enderMap = 1431, enderX = 72.6, enderY = 47.6, objective = "Wait a moment, then speak with Sirra Von'Indi again.", summary = "I'm almost finished translating that note.  If you come back in a few moments I should be done." },
            { ids = { 252 }, name = "Translation to Ello", level = 30, zone = "Duskwood", giver = "Sirra Von'Indi", giverMap = 1431, giverX = 72.6, giverY = 47.6, ender = "Lord Ello Ebonlocke", enderMap = 1431, enderX = 71.9, enderY = 46.4, objective = "Bring the Translated Letter to Lord Ello Ebonlocke", summary = "Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.$B$BYou better bring the translated note back to Ello.$B$BAnd do so quickly, for I fear a doom already lumbers toward our town..." },
            { ids = { 253 }, name = "Bride of the Embalmer", level = 30, zone = "Duskwood", giver = "Lord Ello Ebonlocke", giverMap = 1431, giverX = 71.9, giverY = 46.4, ender = "Lord Ello Ebonlocke", enderMap = 1431, enderX = 71.9, enderY = 46.4, objective = "Find Eliza's grave.  Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.", summary = "The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse.$B$BThis revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried.$B$BHis heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken." },
        },
    },
    {
        id = "q991",
        name = "Raene's Cleansing",
        zone = "Ashenvale",
        minLevel = 18,
        maxLevel = 30,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 991 }, name = "Raene's Cleansing", level = 19, zone = "Ashenvale", giver = "Raene Wolfrunner", giverMap = 1440, giverX = 36.6, giverY = 49.6, ender = "Teronis' Corpse", enderMap = 1440, enderX = 20.3, enderY = 42.3, objective = "Find Teronis in Ashenvale.", summary = "$N, a longtime friend of mine is also aiding the Sentinels here in Ashenvale, but he has yet to return.$B$BHe had leads on finding an item that he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.$B$BBefore he left here, he mentioned seeking out a gem for the rod.$B$BHe mentioned the gem possibly being hidden at the shrine in Lake Falathim at the base of the mountain to the west. The gem was being held there before it was overrun.$B$BFind my friend, $N, please." },
            { ids = { 1023 }, name = "Raene's Cleansing", level = 21, zone = "Ashenvale", giver = "Teronis' Corpse", giverMap = 1440, giverX = 20.3, giverY = 42.3, ender = "Raene Wolfrunner", enderMap = 1440, enderX = 36.6, enderY = 49.6, objective = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.", summary = "As you rummage through Teronis' belongings, you find a journal that is still in good condition.$B$BYou take the journal and leave Teronis' corpse as is.$B$BThe only thing left to do is find the gem Teronis was seeking. Raene mentioned it being in the area. Perhaps the murlocs have it..." },
            { ids = { 1024 }, name = "Raene's Cleansing", level = 21, zone = "Ashenvale", giver = "Raene Wolfrunner", giverMap = 1440, giverX = 36.6, giverY = 49.6, ender = "Shael'dryn", enderMap = 1440, enderX = 53.5, enderY = 46.2, objective = "Find Shael'dryn at the moonwell to the northeast.", summary = "You'll have to do the research yourself, but from what notes Teronis has made, it sounds like your next course of action is to find the other pieces of the rod Dartol created. I would start by heading to the moonwell east of Iris Lake. When you're ready, follow the road and turn north when you reach a small sitting area on your left.$B$BA dryad there named Shael'dryn is better suited to guide you. Seek her out.$B$BKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod." },
            { ids = { 1026 }, name = "Raene's Cleansing", level = 27, zone = "Ashenvale", giver = "Shael'dryn", giverMap = 1440, giverX = 53.5, giverY = 46.2, ender = "Shael'dryn", enderMap = 1440, enderX = 53.5, enderY = 46.2, objective = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.", summary = "I wish your tidings were better.$B$BRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.$B$BIf your goal is to find the next piece of the rod, then you'll have to find the key to open the chest it's in.$B$BThe wooden key is on one of the treants northeast of here, near Felwood. Once you have it, look for a small glade west of the road near the Felwood border... the chest should be hidden around there." },
            { ids = { 1027 }, name = "Raene's Cleansing", level = 28, zone = "Ashenvale", giver = "Shael'dryn", giverMap = 1440, giverX = 53.5, giverY = 46.2, ender = "Shael'dryn", enderMap = 1440, enderX = 53.5, enderY = 46.2, objective = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.", summary = "The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that.$B$BAll I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much.$B$BWhen you find the final piece, bring it to me and I will help you reconstruct the rod." },
            { ids = { 1028 }, name = "Raene's Cleansing", level = 28, zone = "Ashenvale", giver = "Shael'dryn", giverMap = 1440, giverX = 53.5, giverY = 46.2, ender = "Hidden Shrine", enderMap = 1440, enderX = 56.4, enderY = 49.2, objective = "Find the hidden shrine and re-enchant Dartol's Rod.", summary = "Here is the completed rod, $N. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part.$B$BWith some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much.$B$BHead southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade.$B$BOnce there, place the rod within the shrine... the rest is magic. Hehe." },
            { ids = { 1055 }, name = "Raene's Cleansing", level = 28, zone = "Ashenvale", giver = "Hidden Shrine", giverMap = 1440, giverX = 56.4, giverY = 49.2, ender = "Shael'dryn", enderMap = 1440, enderX = 53.5, enderY = 46.2, objective = "Return to Shael'dryn at the moonwell.", summary = "The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success." },
            { ids = { 1029 }, name = "Raene's Cleansing", level = 28, zone = "Ashenvale", giver = "Shael'dryn", giverMap = 1440, giverX = 53.5, giverY = 46.2, ender = "Raene Wolfrunner", enderMap = 1440, enderX = 36.6, enderY = 49.6, objective = "Return to Raene Wolfrunner in Astranaar.", summary = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.$B$BGood luck, $N." },
            { ids = { 1030 }, name = "Raene's Cleansing", level = 28, zone = "Ashenvale", giver = "Raene Wolfrunner", giverMap = 1440, giverX = 36.6, giverY = 49.6, ender = "Krolg", enderMap = 1440, enderX = 50.8, enderY = 75.1, objective = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.", summary = "Alas, I'm not completely certain what he had in mind next.$B$BIf what he said was true about the rod's power, then it will allow you to take on another form altogether. Which form, I do not know.$B$BPerhaps he meant to use its powers to get closer to the tainted furbolgs, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was safe from the effects of Fel Moss.$B$BI would start your search southeast of Mystral Lake." },
            { ids = { 1045 }, name = "Raene's Cleansing", level = 30, zone = "Ashenvale", giver = "Krolg", giverMap = 1440, giverX = 50.8, giverY = 75.1, ender = "Krolg", enderMap = 1440, enderX = 50.8, enderY = 75.1, objective = "Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral.", summary = "The night elves are as old as time, but their arrogance destroys their very world. And now it destroys our lives too. But that can no longer be controlled...$B$BI blame the elves for much, but we are still responsible for our actions. Even beyond the corruption, we are capable of great evil.$B$BRan Bloodtooth is one such evil. Power hungry, lusting... the corruption has only made him stronger. My hatred for the elves burns, but I do not wish ill upon their children, so we must police our own." },
            { ids = { 1046 }, name = "Raene's Cleansing", level = 30, zone = "Ashenvale", giver = "Krolg", giverMap = 1440, giverX = 50.8, giverY = 75.1, ender = "Raene Wolfrunner", enderMap = 1440, enderX = 36.6, enderY = 49.6, objective = "Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar.", summary = "Return to your own tribe and let them know of your victory here.$B$BShow them your trophy, and bask in the glory..." },
        },
    },
    {
        id = "q1198",
        name = "Blackfathom Villainy",
        zone = "Darnassus",
        minLevel = 18,
        maxLevel = 27,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 1198 }, name = "In Search of Thaelrid", level = 24, zone = "Darnassus", giver = "Dawnwatcher Shaedlass", giverMap = 1457, giverX = 55.4, giverY = 25.0, ender = "Argent Guard Thaelrid", enderMap = 1440, enderX = 14.5, enderY = 14.2, enderInside = "Blackfathom Deeps", objective = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.", summary = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.$b$bMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.$b$bIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.$b$bMy other scouts are preoccupied with pressing matters.$b$bSeek out and aid Thaelrid for me, $n." },
            { ids = { 1200 }, name = "Blackfathom Villainy", level = 27, zone = "Blackfathom Deeps", giver = "Argent Guard Thaelrid", giverMap = 1440, giverX = 14.5, giverY = 14.2, giverInside = "Blackfathom Deeps", ender = "Dawnwatcher Selgorm", enderMap = 1457, enderX = 56.2, enderY = 24.4, objective = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.", summary = "Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.$b$bAku'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.$b$bSlay Kelris and bring his head to Selgorm in Darnassus, $N, please." },
        },
    },
    {
        id = "q468",
        name = "Nek'rosh's Gambit",
        zone = "Loch Modan",
        minLevel = 19,
        maxLevel = 32,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 468 }, name = "Report to Mountaineer Rockgar", level = 21, zone = "Loch Modan", giver = "Mountaineer Kadrell", giverMap = 1432, giverX = 32.6, giverY = 49.7, ender = "Mountaineer Rockgar", enderMap = 1432, enderX = 25.4, enderY = 10.4, objective = "Speak with Mountaineer Rockgar.", summary = "Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  $B$BIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower." },
            { ids = { 455 }, name = "The Algaz Gauntlet", level = 21, zone = "Loch Modan", giver = "Mountaineer Rockgar", giverMap = 1432, giverX = 25.4, giverY = 10.4, ender = "Valstag Ironjaw", enderMap = 1437, enderX = 10.1, enderY = 56.9, objective = "Traverse Dun Algaz.$B$BKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.$B$BReport to Valstag Ironjaw in Menethil Harbor.", summary = "Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands.$B$BBreak through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor.$B$BMenethil is through Dun Algaz, then north along the road, then west at the fork.$B$BWe're counting on you, $N.  Do not fail." },
            { ids = { 473 }, name = "Report to Captain Stoutfist", level = 28, zone = "Wetlands", giver = "Valstag Ironjaw", giverMap = 1437, giverX = 10.1, giverY = 56.9, ender = "Captain Stoutfist", enderMap = 1437, enderX = 9.9, enderY = 57.5, objective = "Speak with Captain Stoutfist.", summary = "$N.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room." },
            { ids = { 464 }, name = "War Banners", level = 28, zone = "Wetlands", giver = "Captain Stoutfist", giverMap = 1437, giverX = 9.9, giverY = 57.5, ender = "Captain Stoutfist", enderMap = 1437, enderX = 9.9, enderY = 57.5, objective = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.", summary = "The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.$B$BNow they've gained strength, and have an encampment northeast of Menethil.$B$BWe want you to attack that encampment.  Gather and bring me their war banners as proof." },
            { ids = { 465 }, name = "Nek'rosh's Gambit", level = 31, zone = "Wetlands", giver = "Captain Stoutfist", giverMap = 1437, giverX = 9.9, giverY = 57.5, ender = "Dragonmaw Catapult", enderMap = 1437, enderX = 47.5, enderY = 47.0, objective = "Destroy the Dragonmaw catapults.", summary = "While you were fighting the Dragonmaws, we discovered more of their plans.$B$BNek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements!$B$BYou need to take out those catapults.  They're in the Dragonmaw encampment.$B$BHere, take this tinder.  Fight your way to the catapults and light them with the tinder.$B$BAnd after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck." },
            { ids = { 474 }, name = "Defeat Nek'rosh", level = 32, zone = "Wetlands", giver = "Dragonmaw Catapult", giverMap = 1437, giverX = 47.5, giverY = 47.0, ender = "Captain Stoutfist", enderMap = 1437, enderX = 9.9, enderY = 57.5, objective = "Kill Chieftain Nek'rosh$B$BBring Nek'rosh's Head to Captain Stoutfist.", summary = "Now that the catapults have been burned, find and kill Chieftain Nek'rosh." },
        },
    },
    {
        id = "q2360",
        name = "Klaven's Tower",
        zone = "Stormwind City",
        minLevel = 20,
        maxLevel = 24,
        importance = 2,
        kind = "class",
        classes = { 4 },
        quests = {
            { ids = { 2360 }, name = "Mathias and the Defias", level = 20, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Agent Kearnen", enderMap = 1436, enderX = 68.5, enderY = 70.1, objective = "Travel to Westfall and find Agent Kearnen for your debriefing.", summary = "Not a moment too soon, $N. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.$B$BIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.$B$BGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.$B$B...and $N, should you be discovered, SI:7 will disavow all knowledge of your existence. " },
            { ids = { 2359 }, name = "Klaven's Tower", level = 24, zone = "Westfall", giver = "Agent Kearnen", giverMap = 1436, giverX = 68.5, giverY = 70.1, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.", summary = "I've been staking out this tower for weeks, $N. Recently a major shipment came through from Duskwood, and along with it came those guards.$B$BWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.$B$BAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.$B$BGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias." },
            { ids = { 2607 }, name = "The Touch of Zanzil", level = 20, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Doc Mixilpixil", enderMap = 1453, enderX = 80.1, enderY = 69.9, objective = "Speak with Doc Mixilpixil in the cellar of the Barracks.", summary = "It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, $N.$B$BA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help." },
            { ids = { 2608 }, name = "The Touch of Zanzil", level = 20, zone = "Stormwind City", giver = "Doc Mixilpixil", giverMap = 1453, giverX = 80.1, giverY = 69.9, ender = "Doc Mixilpixil", enderMap = 1453, enderX = 80.1, enderY = 69.9, objective = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?", summary = "Oh my, you look like death. Correction - I've seen death, you look worse than death. You, $g sir:miss;, would be what death coughed up at his last physical.$B$BHah! You hear that Noarm? Write that one down!$B$B*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, $N." },
            { ids = { 2609 }, name = "The Touch of Zanzil", level = 20, zone = "Stormwind City", giver = "Doc Mixilpixil", giverMap = 1453, giverX = 80.1, giverY = 69.9, ender = "Doc Mixilpixil", enderMap = 1453, enderX = 80.1, enderY = 69.9, objective = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young $g fella:lady;. ", summary = "It's unanimous, $N. You've got the 'itis.'$B$BLuckily, I have a cure for the 'itis.'$B$BHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.$B$BHurry along now, $N, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine." },
        },
    },
    {
        id = "q1649",
        name = "The Test of Righteousness",
        zone = "",
        minLevel = 20,
        maxLevel = 25,
        importance = 2,
        kind = "class",
        races = { 1, 3 },
        classes = { 2 },
        quests = {
            { ids = { 1649 }, name = "The Tome of Valor", level = 20, ender = "Duthorian Rall", enderMap = 1453, enderX = 50.5, enderY = 47.5, objective = "Speak to Duthorian Rall in Stormwind.", summary = "Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.$B$BThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot." },
            { ids = { 1650 }, name = "The Tome of Valor", level = 23, zone = "Stormwind City", giver = "Duthorian Rall", giverMap = 1453, giverX = 50.5, giverY = 47.5, ender = "Daphne Stilwell", enderMap = 1436, enderX = 41.7, enderY = 89.2, objective = "Find Daphne Stilwell in Westfall.", summary = "Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.$B$BAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.$B$BReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there." },
            { ids = { 1651 }, name = "The Tome of Valor", level = 25, zone = "Westfall", giver = "Daphne Stilwell", giverMap = 1436, giverX = 41.7, giverY = 89.2, ender = "Daphne Stilwell", enderMap = 1436, enderX = 41.7, enderY = 89.2, objective = "Defend Daphne Stilwell from the Defias attack.$B$BNeither of your spirits must be released from their mortal coils if you wish to succeed.$B$BAfter you are successful, speak to Daphne Stilwell again.", summary = "Now, they'll be coming again soon, I'd wager, so get yourself ready.$B$BI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.$B$BI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.$B$BAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.$B$BWe make our stand near the house!" },
            { ids = { 1652 }, name = "The Tome of Valor", level = 25, zone = "Westfall", giver = "Daphne Stilwell", giverMap = 1436, giverX = 41.7, giverY = 89.2, ender = "Duthorian Rall", enderMap = 1453, enderX = 50.5, enderY = 47.5, objective = "Speak to Duthorian Rall in Stormwind.", summary = "Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.$B$BHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.$B$BOh, how I miss my husband. I can't wait till he returns." },
            { ids = { 1653 }, name = "The Test of Righteousness", level = 21, zone = "Stormwind City", giver = "Duthorian Rall", giverMap = 1453, giverX = 50.5, giverY = 47.5, ender = "Jordan Stilwell", enderMap = 1426, enderX = 52.5, enderY = 36.9, objective = "Speak to Jordan Stilwell in Ironforge", summary = "Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.$B$BJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.$B$BHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air." },
            { ids = { 1654 }, name = "The Test of Righteousness", level = 22, zone = "Dun Morogh", giver = "Jordan Stilwell", giverMap = 1426, giverX = 52.5, giverY = 36.9, ender = "Jordan Stilwell", enderMap = 1426, enderX = 52.5, enderY = 36.9, objective = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.", summary = "I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.$B$BI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, $c?" },
            { ids = { 1806 }, name = "The Test of Righteousness", level = 22, zone = "Dun Morogh", giver = "Jordan Stilwell", giverMap = 1426, giverX = 52.5, giverY = 36.9, ender = "Jordan Stilwell", enderMap = 1426, enderX = 52.5, enderY = 36.9, objective = "Wait for Jordan Stilwell to finish forging a weapon for you.", summary = "Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.$B$BWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.$B$BI'll be somewhat honest, $N, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy." },
        },
    },
    {
        id = "q1698",
        name = "Fire Hardened Mail",
        zone = "Ironforge",
        minLevel = 20,
        maxLevel = 30,
        importance = 2,
        kind = "class",
        races = { 1 },
        classes = { 1 },
        quests = {
            { ids = { 1698 }, name = "Yorus Barleybrew", level = 20, zone = "Ironforge", giver = "Kelv Sternhammer", giverMap = 1455, giverX = 70.3, giverY = 90.7, ender = "Yorus Barleybrew", enderMap = 1433, enderX = 21.5, enderY = 44.7, objective = "Speak with Yorus Barleybrew.", summary = "Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial." },
            { ids = { 1699 }, name = "The Rethban Gauntlet", level = 22, zone = "Redridge Mountains", giver = "Yorus Barleybrew", giverMap = 1433, giverX = 21.5, giverY = 44.7, ender = "Yorus Barleybrew", enderMap = 1433, enderX = 21.5, enderY = 44.7, objective = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.$B$BYou must not die and release your spirit.", summary = "I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...$B$BYou have to return within an hour.$B$BThere are whole heaps of Redridge Gnolls in the way.$B$BBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!$B$BSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?" },
            { ids = { 1702 }, name = "The Shieldsmith", level = 22, zone = "Redridge Mountains", giver = "Yorus Barleybrew", giverMap = 1433, giverX = 21.5, giverY = 44.7, ender = "Furen Longbeard", enderMap = 1453, enderX = 64.6, enderY = 37.2, objective = "Bring the Cask of Scalder to Furen Longbeard.", summary = "You really showed what you were made of when you ran the Rethban Gauntlet, $N.  And I'm true to my word.  I'll get you the reward I promised...$B$BExcept it's in Stormwind.$B$BTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.$B$BHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one." },
            { ids = { 1701 }, name = "Fire Hardened Mail", level = 28, zone = "Stormwind City", giver = "Furen Longbeard", giverMap = 1453, giverX = 64.6, giverY = 37.2, ender = "Furen Longbeard", enderMap = 1453, enderX = 64.6, enderY = 37.2, objective = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.", summary = "So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you.$B$BWhat do you say, $N?  If you're up for the challenge, then I'll give you a list of what to get and where to get them." },
            { ids = { 1782 }, name = "Furen's Armor", level = 28, zone = "Stormwind City", giver = "Furen Longbeard", giverMap = 1453, giverX = 64.6, giverY = 37.2, ender = "Furen Longbeard", enderMap = 1453, enderX = 64.6, enderY = 37.2 },
            { ids = { 1700 }, name = "Grimand Elmore", level = 28, zone = "Stormwind City", giver = "Furen Longbeard", giverMap = 1453, giverX = 64.6, giverY = 37.2, ender = "Grimand Elmore", enderMap = 1453, enderX = 59.7, enderY = 33.8, objective = "Bring Furen's Notes to Grimand Elmore.", summary = "I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.$B$BAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me..." },
            { ids = { 1705 }, name = "Burning Blood", level = 28, zone = "Stormwind City", giver = "Grimand Elmore", giverMap = 1453, giverX = 59.7, giverY = 33.8, ender = "Grimand Elmore", enderMap = 1453, enderX = 59.7, enderY = 33.8, objective = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.", summary = "I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, $N, then you can have the armor.$B$BTo make this armor, I need samples of burning blood and a burning rock.$B$BThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.$B$BMay fortune grant you speed, $N." },
            { ids = { 1706 }, name = "Grimand's Armor", level = 30, zone = "Stormwind City", giver = "Grimand Elmore", giverMap = 1453, giverX = 59.7, giverY = 33.8, ender = "Grimand Elmore", enderMap = 1453, enderX = 59.7, enderY = 33.8 },
        },
    },
    {
        id = "q2927",
        name = "The Only Cure is More Green Glow",
        zone = "Ironforge",
        minLevel = 20,
        maxLevel = 30,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 2927 }, name = "The Day After", level = 27, zone = "Ironforge", giver = "Gnoarn", giverMap = 1455, giverX = 69.2, giverY = 50.5, ender = "Ozzie Togglevolt", enderMap = 1426, enderX = 45.9, enderY = 49.4, objective = "Speak with Ozzie Togglevolt in Kharanos.", summary = "You don't think I was always bald, do you? No $g sir:ma'am;! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.$B$B<Gnoarn shakes his fist in the air.>$B$BDamn those damned dirty troggs - damn them all!!$B$BPerhaps it's not too late, $N. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution." },
            { ids = { 2926 }, name = "Gnogaine", level = 27, zone = "Dun Morogh", giver = "Ozzie Togglevolt", giverMap = 1426, giverX = 45.9, giverY = 49.4, ender = "Ozzie Togglevolt", enderMap = 1426, enderX = 45.9, enderY = 49.4, objective = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", summary = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, $N.$B$BLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!" },
            { ids = { 2962 }, name = "The Only Cure is More Green Glow", level = 30, zone = "Dun Morogh", giver = "Ozzie Togglevolt", giverMap = 1426, giverX = 45.9, giverY = 49.4, ender = "Ozzie Togglevolt", enderMap = 1426, enderX = 45.9, enderY = 49.4, objective = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.$B$BOzzie will also require your Heavy Leaden Collection Phial when the task is complete.", summary = "Not only was your sample insufficient in quantity, it was also impure.$B$BWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered." },
        },
    },
    {
        id = "q2923",
        name = "Save Techbot's Brain!",
        zone = "Stormwind City",
        minLevel = 20,
        maxLevel = 26,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 2923 }, name = "Tinkmaster Overspark", level = 26, zone = "Stormwind City", giver = "Brother Sarno", giverMap = 1453, giverX = 51.1, giverY = 48.4, ender = "Tinkmaster Overspark", enderMap = 1455, enderX = 69.5, enderY = 50.3, objective = "Speak with Tinkmaster Overspark in Ironforge.", summary = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.$B$BVery sad.  But with luck perhaps he can be fixed!$B$BSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help." },
            { ids = { 2922 }, name = "Save Techbot's Brain!", level = 26, zone = "Ironforge", giver = "Tinkmaster Overspark", giverMap = 1455, giverX = 69.5, giverY = 50.3, ender = "Tinkmaster Overspark", enderMap = 1455, enderX = 69.5, enderY = 50.3, objective = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", summary = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!$B$BBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.$B$B" },
        },
    },
    {
        id = "q66",
        name = "The Legend of Stalvan",
        zone = "Duskwood",
        minLevel = 22,
        maxLevel = 35,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 66 }, name = "The Legend of Stalvan", level = 28, zone = "Duskwood", giver = "Madame Eva", giverMap = 1431, giverX = 75.8, giverY = 45.3, ender = "Clerk Daltry", enderMap = 1431, enderX = 72.5, enderY = 46.9, objective = "Seek out the Clerk Daltry in the Darkshire Town Hall.", summary = "Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.$b$bAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.$b$bSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all." },
            { ids = { 67 }, name = "The Legend of Stalvan", level = 28, zone = "Duskwood", giver = "Clerk Daltry", giverMap = 1431, giverX = 72.5, giverY = 46.9, ender = "Old Footlocker", enderMap = 1436, enderX = 41.5, enderY = 66.7, objective = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.", summary = "Stalvan, eh?  Let me check the town registry.$b$bStalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated!$b$bDo me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean." },
            { ids = { 68 }, name = "The Legend of Stalvan", level = 28, zone = "Westfall", giver = "Old Footlocker", giverMap = 1436, giverX = 41.5, giverY = 66.7, ender = "Clerk Daltry", enderMap = 1431, enderX = 72.5, enderY = 46.9, objective = "Take the Dusty Unsent Letter to Clerk Daltry.", summary = "You find a Dusty Unsent Letter in the old footlocker." },
            { ids = { 69 }, name = "The Legend of Stalvan", level = 28, zone = "Duskwood", giver = "Clerk Daltry", giverMap = 1431, giverX = 72.5, giverY = 46.9, ender = "Innkeeper Farley", enderMap = 1429, enderX = 43.8, enderY = 65.8, objective = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.", summary = "Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, $N." },
            { ids = { 70 }, name = "The Legend of Stalvan", level = 28, zone = "Elwynn Forest", giver = "Innkeeper Farley", giverMap = 1429, giverX = 43.8, giverY = 65.8, ender = "Caretaker Folsom", enderMap = 1453, enderX = 42.5, enderY = 72.4, objective = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.", summary = "The name Stalvan rings a bell.  I remember now.$b$bMany years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour.$b$bIn his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it." },
            { ids = { 72 }, name = "The Legend of Stalvan", level = 28, zone = "Stormwind City", giver = "Caretaker Folsom", giverMap = 1453, giverX = 42.5, giverY = 72.4, ender = "Sealed Crate", enderMap = 1453, enderX = 42.5, enderY = 72.0, objective = "Search through the packed up possessions for a clue.", summary = "My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there.$b$bThe last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find." },
            { ids = { 74 }, name = "The Legend of Stalvan", level = 28, zone = "Stormwind City", giver = "Sealed Crate", giverMap = 1453, giverX = 42.5, giverY = 72.0, ender = "Marshal Haggard", enderMap = 1429, enderX = 84.6, enderY = 69.4, objective = "The Torn Journal page you discovered provides your next clue.", summary = "Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page." },
            { ids = { 75 }, name = "The Legend of Stalvan", level = 28, zone = "Elwynn Forest", giver = "Marshal Haggard", giverMap = 1429, giverX = 84.6, giverY = 69.4, ender = "Marshal Haggard", enderMap = 1429, enderX = 84.6, enderY = 69.4, objective = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.", summary = "There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. $b$bDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can." },
            { ids = { 78 }, name = "The Legend of Stalvan", level = 28, zone = "Elwynn Forest", giver = "Marshal Haggard", giverMap = 1429, giverX = 84.6, giverY = 69.4, ender = "Tavernkeep Smitts", enderMap = 1431, enderX = 73.8, enderY = 44.5, objective = "Take the Faded Journal Page to Tavernkeep Smitts.", summary = "I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it." },
            { ids = { 79 }, name = "The Legend of Stalvan", level = 28, zone = "Duskwood", giver = "Tavernkeep Smitts", giverMap = 1431, giverX = 73.8, giverY = 44.5, ender = "Commander Althea Ebonlocke", enderMap = 1431, enderX = 73.5, enderY = 46.8, objective = "Take the muddy page to Commander Ebonlocke.", summary = "I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!" },
            { ids = { 80 }, name = "The Legend of Stalvan", level = 28, zone = "Duskwood", giver = "Commander Althea Ebonlocke", giverMap = 1431, giverX = 73.5, giverY = 46.8, ender = "Clerk Daltry", enderMap = 1431, enderX = 72.5, enderY = 46.9, objective = "Show Clerk Daltry the Bloodstained Journal Page.", summary = "I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.$b$bIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature." },
            { ids = { 97 }, name = "The Legend of Stalvan", level = 28, zone = "Duskwood", giver = "Clerk Daltry", giverMap = 1431, giverX = 72.5, giverY = 46.9, ender = "Commander Althea Ebonlocke", enderMap = 1431, enderX = 73.5, enderY = 46.8, objective = "Report the news to Commander Ebonlocke.", summary = "Let Commander Ebonlocke know immediately that the handwriting matched, $N!  Her suspicions were correct!" },
            { ids = { 98 }, name = "The Legend of Stalvan", level = 35, zone = "Duskwood", giver = "Commander Althea Ebonlocke", giverMap = 1431, giverX = 73.5, giverY = 46.8, ender = "Madame Eva", enderMap = 1431, enderX = 75.8, enderY = 45.3, objective = "Kill Stalvan Mistmantle and show Madame Eva his family ring.", summary = "Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, $C, and execute Stalvan, once and for all.$b$bWhen the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her." },
        },
    },
    {
        id = "q288",
        name = "Cleansing the Eye",
        zone = "Wetlands",
        minLevel = 22,
        maxLevel = 30,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 288 }, name = "The Third Fleet", level = 27, zone = "Wetlands", giver = "First Mate Fitzsimmons", giverMap = 1437, giverX = 10.9, giverY = 59.6, ender = "First Mate Fitzsimmons", enderMap = 1437, enderX = 10.9, enderY = 59.6, objective = "Buy First Mate Fitzsimmons a Flagon of Mead.", summary = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs!$B$BWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...$B$B...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale." },
            { ids = { 289 }, name = "The Cursed Crew", level = 29, zone = "Wetlands", giver = "First Mate Fitzsimmons", giverMap = 1437, giverX = 10.9, giverY = 59.6, ender = "First Mate Fitzsimmons", enderMap = 1437, enderX = 10.9, enderY = 59.6, objective = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig.  Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.", summary = "<Bolstered, Fitzsimmons continues his tale...>$B$BI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.$B$BBut if you can free some of my brothers, then perhaps you can break their curse." },
            { ids = { 290 }, name = "Lifting the Curse", level = 30, zone = "Wetlands", giver = "First Mate Fitzsimmons", giverMap = 1437, giverX = 10.9, giverY = 59.6, ender = "Intrepid's Locked Strongbox", enderMap = 1437, enderX = 14.4, enderY = 24.0, objective = "Get the Intrepid Strongbox Key from Captain Halyndor.$B$BUse the key to open the Intrepid's Locked Strongbox.", summary = "To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over.$B$BMy old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox.$B$BThen, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town." },
            { ids = { 292 }, name = "The Eye of Paleth", level = 30, zone = "Wetlands", giver = "Intrepid's Locked Strongbox", giverMap = 1437, giverX = 14.4, giverY = 24.0, ender = "Glorin Steelbrow", enderMap = 1437, enderX = 10.6, enderY = 60.6, objective = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.", summary = "Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth.$B$BTake the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse." },
            { ids = { 293 }, name = "Cleansing the Eye", level = 30, zone = "Wetlands", giver = "Glorin Steelbrow", giverMap = 1437, giverX = 10.6, giverY = 60.6, ender = "Archbishop Benedictus", enderMap = 1453, enderX = 50.3, enderY = 45.5, objective = "Bring Archbishop Benedictus the Cursed Eye of Paleth.  Benedictus is in the Cathedral of Light, in the city of Stormwind.", summary = "I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help.$B$BI hope, for your sake." },
        },
    },
    {
        id = "q637",
        name = "A King's Tribute",
        zone = "Ironforge",
        minLevel = 25,
        maxLevel = 31,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 637 }, name = "Sully Balloo's Letter", level = 30, zone = "Ironforge", ender = "Sara Balloo", enderMap = 1455, enderX = 63.5, enderY = 67.3, objective = "Deliver Sully Balloo's Letter to Sara Balloo.", summary = "The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care.$b$bThe letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, \"My dear Sara....\"" },
            { ids = { 683 }, name = "Sara Balloo's Plea", level = 30, zone = "Ironforge", giver = "Sara Balloo", giverMap = 1455, giverX = 63.5, giverY = 67.3, ender = "King Magni Bronzebeard", enderMap = 1455, enderX = 39.1, enderY = 56.2, objective = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.", summary = "$n, I have but a small request to ask of you.$b$bTake this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far.$b$bFor me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand." },
            { ids = { 686 }, name = "A King's Tribute", level = 30, zone = "Ironforge", giver = "King Magni Bronzebeard", giverMap = 1455, giverX = 39.1, giverY = 56.2, ender = "Grand Mason Marblesten", enderMap = 1455, enderX = 39.0, enderY = 88.0, objective = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.", summary = "I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.$b$bWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.$b$bI am going to commission a memorial to Sully Balloo to be built by Grand Mason Mablesten.$b$bSend word to him now, $c. You shall be custodian of my bidding." },
            { ids = { 689 }, name = "A King's Tribute", level = 31, zone = "Ironforge", giver = "Grand Mason Marblesten", giverMap = 1455, giverX = 39.0, giverY = 88.0, ender = "Grand Mason Marblesten", enderMap = 1455, enderX = 39.0, enderY = 88.0, objective = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.", summary = "So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy?$b$bBah, will there ever be peace on Azeroth?$b$bNonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite." },
            { ids = { 700 }, name = "A King's Tribute", level = 31, zone = "Ironforge", giver = "Grand Mason Marblesten", giverMap = 1455, giverX = 39.0, giverY = 88.0, ender = "King Magni Bronzebeard", enderMap = 1455, enderX = 39.1, enderY = 56.2, objective = "Report to King Magni Bronzebeard.", summary = "Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles.$b$bBut the Memorial came out quite well! I should think the King will be most pleased with it.$b$bNow if you will, please send word to His Majesty that the Memorial is complete as requested. " },
        },
    },
    {
        id = "q1022",
        name = "The Carevin Family",
        zone = "Ashenvale",
        minLevel = 25,
        maxLevel = 30,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 1022 }, name = "The Howling Vale", level = 30, zone = "Ashenvale", giver = "Sentinel Melyria Frostshadow", giverMap = 1440, giverX = 22.2, giverY = 53.0, ender = "Sentinel Melyria Frostshadow", enderMap = 1440, enderX = 22.2, enderY = 53.0, objective = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at the Shrine of Aessina.", summary = "Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale.$b$bTo the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come." },
            { ids = { 1037 }, name = "Velinde Starsong", level = 30, zone = "Ashenvale", giver = "Sentinel Melyria Frostshadow", giverMap = 1440, giverX = 22.2, giverY = 53.0, ender = "Thyn'tel Bladeweaver", enderMap = 1457, enderX = 61.8, enderY = 39.2, objective = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.", summary = "Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.$b$bI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.$b$bSurely she will understand the import of such information." },
            { ids = { 1038 }, name = "Velinde's Effects", level = 30, zone = "Darnassus", giver = "Thyn'tel Bladeweaver", giverMap = 1457, giverX = 61.8, giverY = 39.2, ender = "Thyn'tel Bladeweaver", enderMap = 1457, enderX = 61.8, enderY = 39.2, objective = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.", summary = "The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that.$b$bI should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust." },
            { ids = { 1039 }, name = "The Barrens Port", level = 30, zone = "Darnassus", giver = "Thyn'tel Bladeweaver", giverMap = 1457, giverX = 61.8, giverY = 39.2, ender = "Wharfmaster Dizzywig", enderMap = 1413, enderX = 63.4, enderY = 38.5, objective = "Speak with Wharfmaster Dizzywig in Ratchet.", summary = "Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.$b$bFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, $n, warriors of the Horde patrol the land. You will be safe at the port, though." },
            { ids = { 1040 }, name = "Passage to Booty Bay", level = 30, zone = "The Barrens", giver = "Wharfmaster Dizzywig", giverMap = 1413, giverX = 63.4, giverY = 38.5, ender = "Caravaneer Ruzzgot", enderMap = 1434, enderX = 27.4, enderY = 74.1, objective = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.", summary = "Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.$b$bVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.$b$bNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.$b$bMove along, now. I haven't all day for you." },
            { ids = { 1041 }, name = "The Caravan Road", level = 30, zone = "Stranglethorn Vale", giver = "Caravaneer Ruzzgot", giverMap = 1434, giverX = 27.4, giverY = 74.1, ender = "Clerk Daltry", enderMap = 1431, enderX = 72.5, enderY = 46.9, objective = "Speak with Clerk Daltry in Darkshire.", summary = "Turns out I was wrong about you, and that isn't something that happens everyday.$b$bIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.$b$bWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.$b$bBe careful in the jungle, it is a deadly place even at the best of times." },
            { ids = { 1042 }, name = "The Carevin Family", level = 30, zone = "Duskwood", giver = "Clerk Daltry", giverMap = 1431, giverX = 72.5, giverY = 46.9, ender = "Jonathan Carevin", enderMap = 1431, enderX = 75.3, enderY = 49.0, objective = "Speak with Jonathan Carevin in Darkshire.", summary = "No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?$b$bThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household." },
            { ids = { 1043 }, name = "The Scythe of Elune", level = 30, zone = "Duskwood", giver = "Jonathan Carevin", giverMap = 1431, giverX = 75.3, giverY = 49.0, ender = "Jonathan Carevin", enderMap = 1431, enderX = 75.3, enderY = 49.0, objective = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.", summary = "Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.$b$bThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.$b$bGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil." },
            { ids = { 1044 }, name = "Answered Questions", level = 30, zone = "Duskwood", giver = "Jonathan Carevin", giverMap = 1431, giverX = 75.3, giverY = 49.0, ender = "Thyn'tel Bladeweaver", enderMap = 1457, enderX = 61.8, enderY = 39.2, objective = "Return to Thyn'tel Bladeweaver in Darnassus.", summary = "We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, $n, and the darkness knows no respite.$b$bI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood." },
        },
    },
    {
        id = "q1104",
        name = "Martek the Exiled",
        zone = "Thousand Needles",
        minLevel = 26,
        maxLevel = 41,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1104 }, name = "Salt Flat Venom", level = 30, zone = "Thousand Needles", giver = "Fizzle Brassbolts", giverMap = 1441, giverX = 78.1, giverY = 77.1, ender = "Fizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.", summary = "I have so many designs for our rocket car!  So many!  And I must try them all!!$B$BI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...$B$BThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!$B$BBring me venom and trust me -- our car will fly!!" },
            { ids = { 1105 }, name = "Hardened Shells", level = 30, zone = "Thousand Needles", giver = "Wizzle Brassbolts", giverMap = 1441, giverX = 78.1, giverY = 77.1, ender = "Wizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.", summary = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!$B$BI want to reinforce its fuel tanks before that happens.$B$BThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.$B$BYou look responsible enough.  Will you get me those shells?" },
            { ids = { 1106 }, name = "Martek the Exiled", level = 35, zone = "Thousand Needles", giver = "Fizzle Brassbolts", giverMap = 1441, giverX = 78.1, giverY = 77.1, ender = "Martek the Exiled", enderMap = 1418, enderX = 42.2, enderY = 52.7, objective = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.", summary = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!$B$BBut there is someone who might know how.$B$BHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!$B$BBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!$B$BFind him!" },
            { ids = { 1108 }, name = "Indurium", level = 39, zone = "Badlands", giver = "Martek the Exiled", giverMap = 1418, giverX = 42.2, giverY = 52.7, ender = "Martek the Exiled", enderMap = 1418, enderX = 42.2, enderY = 52.7, objective = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.", summary = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, $N, if you have the guts to get it.$B$BThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.$B$BBut let's make sure.  Get me samples of indurium and I'll test its properties.$B$BTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes." },
            { ids = { 1137 }, name = "News for Fizzle", level = 38, zone = "Badlands", giver = "Martek the Exiled", giverMap = 1418, giverX = 42.2, giverY = 52.7, ender = "Fizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Speak with Fizzle Brassbolts in the Shimmering Flats.", summary = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.$B$BTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.$B$BSend Fizzle Brassbolts my regards, and tell him what I told you.$B$BSafe travels, $N.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!" },
            { ids = { 1190 }, name = "Keeping Pace", level = 41, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Rizzle's Unguarded Plans", enderMap = 1441, enderX = 77.2, enderY = 77.4, objective = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.", summary = "The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.$b$bWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.$b$bZamek can create a diversion for you, so that you can steal those plans from them." },
            { ids = { 1194 }, name = "Rizzle's Schematics", level = 41, zone = "Thousand Needles", giver = "Rizzle's Unguarded Plans", giverMap = 1441, giverX = 77.2, giverY = 77.4, ender = "Pozzik", enderMap = 1441, enderX = 80.2, enderY = 75.9, objective = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.", summary = "Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.$b$bMuch of the other notes relate to the heat resistant properties.$b$bUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore." },
        },
    },
    {
        id = "q1274",
        name = "The Missing Diplomat",
        zone = "Stormwind City",
        minLevel = 28,
        maxLevel = 38,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 1274 }, name = "The Missing Diplomat", level = 28, zone = "Stormwind City", giver = "Thomas", giverMap = 1453, giverX = 49.6, giverY = 44.5, ender = "Bishop DeLavey", enderMap = 1453, enderX = 80.2, enderY = 44.1, objective = "Find Bishop DeLavey in Stormwind Keep.", summary = "Excuse me, $g sir : madam;. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.$B$BIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance." },
            { ids = { 1241 }, name = "The Missing Diplomat", level = 28, zone = "Stormwind City", giver = "Bishop DeLavey", giverMap = 1453, giverX = 80.2, giverY = 44.1, ender = "Jorgen", enderMap = 1453, enderX = 76.3, enderY = 85.1, objective = "Find Jorgen in Stormwind City.", summary = "Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.$B$BI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.$B$BAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.$B$BIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions." },
            { ids = { 1242 }, name = "The Missing Diplomat", level = 28, zone = "Stormwind City", giver = "Jorgen", giverMap = 1453, giverX = 76.3, giverY = 85.1, ender = "Elling Trias", enderMap = 1453, enderX = 66.0, enderY = 74.1, objective = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.", summary = "Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.$B$BI'm gonna only impress this on ya once more, $N: treat this matter seriously, and keep your yapper shut.$B$BYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck." },
            { ids = { 1243 }, name = "The Missing Diplomat", level = 28, zone = "Stormwind City", giver = "Elling Trias", giverMap = 1453, giverX = 66.0, giverY = 74.1, ender = "Watcher Backus", enderMap = 1431, enderX = 74.8, enderY = 44.2, objective = "Give the Sealed Note to Watcher Backus in Duskwood.", summary = "Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?$B$BAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!$B$BHere's what's gonna happen, $N. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.$B$BHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can." },
            { ids = { 1244 }, name = "The Missing Diplomat", level = 30, zone = "Duskwood", giver = "Watcher Backus", giverMap = 1431, giverX = 74.8, giverY = 44.2, ender = "Watcher Backus", enderMap = 1431, enderX = 74.8, enderY = 44.2, objective = "Find the Defias Docket and return it to Watcher Backus in Duskwood.", summary = "Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.$B$BBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.$B$BWhy don't you check there first and bring me back anything you find?$B$BThe farmstead is south of the road from Westfall just as you enter Duskwood." },
            { ids = { 1245 }, name = "The Missing Diplomat", level = 30, zone = "Duskwood", giver = "Watcher Backus", giverMap = 1431, giverX = 74.8, giverY = 44.2, ender = "Elling Trias", enderMap = 1453, enderX = 66.0, enderY = 74.1, objective = "Bring the Defias Docket to Elling Trias in Stormwind.", summary = "Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.$B$BAnd do me a favor, $N, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me." },
            { ids = { 1246 }, name = "The Missing Diplomat", level = 31, zone = "Stormwind City", giver = "Elling Trias", giverMap = 1453, giverX = 66.0, giverY = 74.1, ender = "Dashel Stonefist", enderMap = 1453, enderX = 74.3, enderY = 59.2, objective = "Speak to Dashel Stonefist in Stormwind.", summary = "Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.$B$BYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly." },
            { ids = { 1447 }, name = "The Missing Diplomat", level = 31, zone = "Stormwind City", giver = "Dashel Stonefist", giverMap = 1453, giverX = 74.3, giverY = 59.2, ender = "Dashel Stonefist", enderMap = 1453, enderX = 74.3, enderY = 59.2, objective = "Defeat Dashel Stonefist in Stormwind.", summary = " Yeah, you're obviously not the smartest $c to come into Stormwind, but you're about to be one of the dumbest to never leave.$B$BHave you met me friends?" },
            { ids = { 1247 }, name = "The Missing Diplomat", level = 31, zone = "Stormwind City", giver = "Dashel Stonefist", giverMap = 1453, giverX = 74.3, giverY = 59.2, ender = "Elling Trias", enderMap = 1453, enderX = 66.0, enderY = 74.1, objective = "Speak to Elling Trias in Stormwind.", summary = "So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.$B$BThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan." },
            { ids = { 1248 }, name = "The Missing Diplomat", level = 33, zone = "Stormwind City", giver = "Elling Trias", giverMap = 1453, giverX = 66.0, giverY = 74.1, ender = "Mikhail", enderMap = 1437, enderX = 10.6, enderY = 60.8, objective = "Speak to Mikhail in the Wetlands.", summary = "A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.$B$BSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured." },
            { ids = { 1249 }, name = "The Missing Diplomat", level = 33, zone = "Wetlands", giver = "Mikhail", giverMap = 1437, giverX = 10.6, giverY = 60.8, ender = "Mikhail", enderMap = 1437, enderX = 10.6, enderY = 60.8, objective = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.", summary = "You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.$B$BHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.$B$BDon't look now, $N, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door." },
            { ids = { 1250 }, name = "The Missing Diplomat", level = 33, zone = "Wetlands", giver = "Tapoke \"Slim\" Jahn", giverMap = 1437, giverX = 10.5, giverY = 60.3, ender = "Mikhail", enderMap = 1437, enderX = 10.6, enderY = 60.8, objective = "Speak to Mikhail in the Wetlands.", summary = "The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.$B$BMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!" },
            { ids = { 1264 }, name = "The Missing Diplomat", level = 33, zone = "Wetlands", giver = "Mikhail", giverMap = 1437, giverX = 10.6, giverY = 60.8, ender = "Commander Samaul", enderMap = 1445, enderX = 68.0, enderY = 48.7, objective = "Find Commander Samaul in Dustwallow Marsh.", summary = "The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.$B$BCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discretely." },
            { ids = { 1265 }, name = "The Missing Diplomat", level = 35, zone = "Dustwallow Marsh", giver = "Commander Samaul", giverMap = 1445, giverX = 68.0, giverY = 48.7, ender = "Archmage Tervosh", enderMap = 1445, enderX = 66.4, enderY = 49.3, objective = "Search Sentry Point for any sign of Private Hendel.", summary = "Hendel? Yes, I know the man. But why would you need one of my soldiers?$B$BElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.$B$BI believe Hendel was stationed at the first tower outside of Theramore. Be cautious." },
            { ids = { 1266 }, name = "The Missing Diplomat", level = 36, zone = "Dustwallow Marsh", giver = "Archmage Tervosh", giverMap = 1445, giverX = 66.4, giverY = 49.3, ender = "Private Hendel", enderMap = 1445, enderX = 45.2, enderY = 24.6, objective = "Find Private Hendel in Dustwallow Marsh.", summary = "Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.$B$BYou should have no problem finding him; just look for the tents along the road.$B$BI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems." },
            { ids = { 1324 }, name = "The Missing Diplomat", level = 38, zone = "Dustwallow Marsh", giver = "Private Hendel", giverMap = 1445, giverX = 45.2, giverY = 24.6, ender = "Archmage Tervosh", enderMap = 1445, enderX = 66.4, enderY = 49.3, objective = "Defeat Private Hendel in Dustwallow Marsh.", summary = "What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time." },
            { ids = { 1267 }, name = "The Missing Diplomat", level = 38, zone = "Dustwallow Marsh", giver = "Lady Jaina Proudmoore", giverMap = 1445, giverX = 66.3, giverY = 49.0, ender = "Lady Jaina Proudmoore", enderMap = 1445, enderX = 66.3, enderY = 49.0, objective = "Speak to Jaina Proudmore in Dustwallow Swamp." },
        },
    },
    {
        id = "q1178",
        name = "Goblin Sponsorship",
        zone = "Thousand Needles",
        minLevel = 29,
        maxLevel = 41,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1176 }, name = "Load Lightening", level = 30, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Pozzik", enderMap = 1441, enderX = 80.2, enderY = 75.9, objective = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.", summary = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.$b$bWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.$b$bBring me some and I'll give you a good price on them." },
            { ids = { 1178 }, name = "Goblin Sponsorship", level = 37, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Gazlowe", enderMap = 1413, enderX = 62.7, enderY = 36.2, objective = "Speak to Gazlowe in Ratchet.", summary = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.$b$bYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!$b$bA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!" },
            { ids = { 1180 }, name = "Goblin Sponsorship", level = 37, zone = "The Barrens", giver = "Gazlowe", giverMap = 1413, giverX = 62.7, giverY = 36.2, ender = "Wharfmaster Lozgil", enderMap = 1434, enderX = 26.4, enderY = 73.6, objective = "Speak with Wharfmaster Lozgil in Booty Bay.", summary = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.$b$bIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.$b$bCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records." },
            { ids = { 1181 }, name = "Goblin Sponsorship", level = 37, zone = "Stranglethorn Vale", giver = "Wharfmaster Lozgil", giverMap = 1434, giverX = 26.4, giverY = 73.6, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Speak with Baron Revilgaz in Booty Bay.", summary = "I'm afraid I can't be of much more help to you, $n. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.$b$bYou'll find him at the tavern across the harbor, top floor." },
            { ids = { 1182 }, name = "Goblin Sponsorship", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", summary = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.$b$bYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key." },
            { ids = { 1183 }, name = "Goblin Sponsorship", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Pozzik", enderMap = 1441, enderX = 80.2, enderY = 75.9, objective = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.", summary = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!" },
            { ids = { 1186 }, name = "The Eighteenth Pilot", level = 37, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Razzeric", enderMap = 1441, enderX = 80.3, enderY = 76.1, objective = "Speak with Razzeric on the Shimmering Flats.", summary = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.$b$bHe's a little off his rocker, though, so try not to act too surprised." },
            { ids = { 1187 }, name = "Razzeric's Tweaking", level = 41, zone = "Thousand Needles", giver = "Razzeric", giverMap = 1441, giverX = 80.3, giverY = 76.1, ender = "Razzeric", enderMap = 1441, enderX = 80.3, enderY = 76.1, objective = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.", summary = "Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.$b$bAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!$b$bI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, $n!" },
            { ids = { 1188 }, name = "Safety First", level = 41, zone = "Thousand Needles", giver = "Razzeric", giverMap = 1441, giverX = 80.3, giverY = 76.1, ender = "Shreev", enderMap = 1446, enderX = 51.0, enderY = 27.2, objective = "Bring the Seaforium Booster to Shreev in Gadgetzan.", summary = "But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.$b$bYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this." },
            { ids = { 1189 }, name = "Safety First", level = 41, zone = "Tanaris", giver = "Shreev", giverMap = 1446, giverX = 51.0, giverY = 27.2, ender = "Razzeric", enderMap = 1441, enderX = 80.3, enderY = 76.1, objective = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.", summary = "There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.$b$bWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?" },
        },
    },
    {
        id = "q1111",
        name = "The Rumormonger",
        zone = "Stranglethorn Vale",
        minLevel = 30,
        maxLevel = 44,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 621 }, name = "Zanzil's Secret", level = 44, zone = "Stranglethorn Vale", giver = "Crank Fizzlebub", giverMap = 1434, giverX = 27.1, giverY = 77.2, ender = "Crank Fizzlebub", enderMap = 1434, enderX = 27.1, enderY = 77.2, objective = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", summary = "Zanzil the Outcast dwells with his followers in the Jubuwai and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...$B$BZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.$B$BHis mixture would be worth much to those who wish to control others.$B$BBring me samples of his mixture, and I will find a use for them." },
            { ids = { 1111 }, name = "Wharfmaster Dizzywig", level = 36, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Wharfmaster Dizzywig", enderMap = 1413, enderX = 63.4, enderY = 38.5, objective = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.", summary = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.$B$BSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.$B$BDo this for me, and I'll have more jobs for you.$B$BJobs, my friend, with serious profit potential..." },
            { ids = { 1112 }, name = "Parts for Kravel", level = 36, zone = "The Barrens", giver = "Wharfmaster Dizzywig", giverMap = 1413, giverX = 63.4, giverY = 38.5, ender = "Kravel Koalbeard", enderMap = 1441, enderX = 77.8, enderY = 77.3, objective = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.", summary = "Here's Kravel's package, $N.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!" },
            { ids = { 1114 }, name = "Delivery to the Gnomes", level = 36, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Fizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.", summary = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...$B$BAnd I wouldn't bother mentioning it to him.  It was small and worthless.$B$BTrust me." },
            { ids = { 1115 }, name = "The Rumormonger", level = 36, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Krazek", enderMap = 1434, enderX = 26.9, enderY = 77.2, objective = "Talk to Krazek in Booty Bay.", summary = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  $B$BI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.$B$BIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.$B$BIf you can get useful information from him, then we might just turn a profit from it." },
            { ids = { 1116 }, name = "Dream Dust in the Swamp", level = 36, zone = "Stranglethorn Vale", giver = "Krazek", giverMap = 1434, giverX = 26.9, giverY = 77.2, ender = "Krazek", enderMap = 1434, enderX = 26.9, enderY = 77.2, objective = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", summary = "Getting the information on Nazz is quite a favor, $N.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?$B$BWhile I contact my sources, why don't you gather something for me, eh?$B$BHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!$B$BGet it for me, $N, and I'll give you the information you seek." },
            { ids = { 1117 }, name = "Rumors for Kravel", level = 36, zone = "Stranglethorn Vale", giver = "Krazek", giverMap = 1434, giverX = 26.9, giverY = 77.2, ender = "Kravel Koalbeard", enderMap = 1441, enderX = 77.8, enderY = 77.3, objective = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.", summary = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.$B$BHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.$B$BJust don't tell anyone where you got it!" },
            { ids = { 1118 }, name = "Back to Booty Bay", level = 43, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Crank Fizzlebub", enderMap = 1434, enderX = 27.1, enderY = 77.2, objective = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.", summary = "$N, you're a $c I can trust, both to get the job done and to keep your mouth shut while doing it.$B$BI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.$B$BTo start, you must go back to Booty Bay.  I apologize, good $N.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.$B$BGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort." },
            { ids = { 1119 }, name = "Zanzil's Mixture and a Fool's Stout", level = 44, zone = "Stranglethorn Vale", giver = "Crank Fizzlebub", giverMap = 1434, giverX = 27.1, giverY = 77.2, ender = "Kravel Koalbeard", enderMap = 1441, enderX = 77.8, enderY = 77.3, objective = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.", summary = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.$B$BAnd $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever." },
            { ids = { 1120 }, name = "Get the Gnomes Drunk", level = 44, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Gnome Pit Boss", enderMap = 1441, enderX = 77.6, enderY = 76.9, objective = "Bring the Fool's Stout to the Gnome Pit Boss.", summary = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.$B$BAnd don't wait too long.  This stout will go bad eventually." },
            { ids = { 1122 }, name = "Report Back to Fizzlebub", level = 44, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Crank Fizzlebub", enderMap = 1434, enderX = 27.1, enderY = 77.2, objective = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.", summary = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!$B$BThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.$B$BAnd hopefully we can get more of that Fool's Stout for future races!" },
        },
    },
    {
        id = "q511",
        name = "Further Mysteries",
        zone = "Alterac Mountains",
        minLevel = 30,
        maxLevel = 40,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 511 }, name = "Encrypted Letter", level = 34, zone = "Alterac Mountains", giver = "Syndicate Documents", ender = "Loremaster Dibbs", enderMap = 1424, enderX = 50.6, enderY = 57.1, objective = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.", summary = "One of the letters on this table is encrypted and inscrutable." },
            { ids = { 514 }, name = "Letter to Stormpike", level = 34, zone = "Hillsbrad Foothills", giver = "Loremaster Dibbs", giverMap = 1424, giverX = 50.6, giverY = 57.1, ender = "Prospector Stormpike", enderMap = 1455, enderX = 74.6, enderY = 11.7, objective = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.", summary = "I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he." },
            { ids = { 525 }, name = "Further Mysteries", level = 34, zone = "Ironforge", giver = "Prospector Stormpike", giverMap = 1455, giverX = 74.6, giverY = 11.7, ender = "Magistrate Henry Maleb", enderMap = 1424, enderX = 48.1, enderY = 59.1, objective = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.", summary = "I decrypted the letter, but I don't know what to make of it.  You found this among thieves in the Alterac foothills?  Very strange...$B$BYou should take this to the magistrate of Southshore.  Although this letter is cryptic, his is the closest town to Alterac; if a threat is brewing, then he should know." },
            { ids = { 537 }, name = "Dark Council", level = 40, zone = "Hillsbrad Foothills", giver = "Magistrate Henry Maleb", giverMap = 1424, giverX = 48.1, giverY = 59.1, ender = "Magistrate Henry Maleb", enderMap = 1424, enderX = 48.1, enderY = 59.1, objective = "Kill 4 Argus Shadow Mages.$B$BBring the Head of Nagaz to Magistrate Maleb in Southshore.", summary = "The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat.$B$BI want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them.$B$BSearch in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad.$B$BWith luck, you'll find these envoys of the Argus Wake there." },
        },
    },
    {
        id = "q1301",
        name = "Daelin's Men",
        zone = "Stormwind City",
        minLevel = 30,
        maxLevel = 40,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1301 }, name = "James Hyal", level = 35, zone = "Stormwind City", giver = "Connor Rivers", giverMap = 1453, giverX = 51.1, giverY = 95.5, ender = "Vincent Hyal", enderMap = 1437, enderX = 10.8, enderY = 60.4, objective = "Speak with Vincent Hyal in Menethil Harbor.", summary = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.$b$bI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.$b$bIf you ever happen to be headed in that direction, maybe you could say hello to him for me?" },
            { ids = { 1302 }, name = "James Hyal", level = 35, zone = "Wetlands", giver = "Vincent Hyal", giverMap = 1437, giverX = 10.8, giverY = 60.4, ender = "Clerk Lendry", enderMap = 1445, enderX = 67.9, enderY = 48.2, objective = "Speak with Clerk Lendry in Theramore.", summary = "My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.$b$bI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him." },
            { ids = { 1252 }, name = "Lieutenant Paval Reethe", level = 40, zone = "Dustwallow Marsh", giver = "Theramore Guard Badge", giverMap = 1445, giverX = 29.8, giverY = 48.2, ender = "Captain Garran Vimes", enderMap = 1445, enderX = 68.2, enderY = 48.6, objective = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", summary = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.$b$bUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\"." },
            { ids = { 1259 }, name = "Lieutenant Paval Reethe", level = 40, zone = "Dustwallow Marsh", giver = "Captain Garran Vimes", giverMap = 1445, giverX = 68.2, giverY = 48.6, ender = "Adjutant Tesoran", enderMap = 1445, enderX = 68.0, enderY = 48.1, objective = "Find out more about Reethe from Adjutant Tesoran in Theramore.", summary = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.$b$bHe should be able to tell you who this Reethe is with a quick check of his books." },
            { ids = { 1285 }, name = "Daelin's Men", level = 38, zone = "Dustwallow Marsh", giver = "Adjutant Tesoran", giverMap = 1445, giverX = 68.0, giverY = 48.1, ender = "Captain Garran Vimes", enderMap = 1445, enderX = 68.2, enderY = 48.6, objective = "Return the information about Reethe to Captain Garran Vimes in Theramore.", summary = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.$b$bJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...$b$bListed as missing." },
            { ids = { 1286 }, name = "The Deserters", level = 38, zone = "Dustwallow Marsh", giver = "Captain Garran Vimes", giverMap = 1445, giverX = 68.2, giverY = 48.6, ender = "Balos Jacken", enderMap = 1445, enderX = 36.1, enderY = 54.3, objective = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", summary = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.$b$bThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.$b$bThe deserters' leader is a man named Jacken. See if you can get some information out of him.$b$bBe warned, $n. He may be a tough nut to crack." },
            { ids = { 1287 }, name = "The Deserters", level = 38, zone = "Dustwallow Marsh", giver = "Balos Jacken", giverMap = 1445, giverX = 36.1, giverY = 54.3, ender = "Captain Garran Vimes", enderMap = 1445, enderX = 68.2, enderY = 48.6, objective = "Speak with Captain Garran Vimes in Theramore about Reethe.", summary = "Reethe? That coward?$b$bWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.$b$bHe crossed the line one too many times, so we left him to fend for himself.$b$bNow, I helped you out... So, why don't you help us out and forget you bumped into us?" },
        },
    },
    {
        id = "q1718",
        name = "Cyclonian",
        zone = "Ironforge",
        minLevel = 30,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 1718 }, name = "The Islander", level = 30, zone = "Ironforge", giver = "Kelv Sternhammer", giverMap = 1455, giverX = 70.3, giverY = 90.7, ender = "Klannoc Macleod", enderMap = 1413, enderX = 68.6, enderY = 49.2, objective = "Speak with Klannoc Macleod.", summary = "Your renown as a warrior grows, $N.  Now it is time to pit yourself against your peers and see where you stand.$B$BThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.$B$BMeet, and fight.$B$BSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.$B$BTo reach Fray Island, search for the sand bar shallows along the Merchant Coast." },
            { ids = { 1719 }, name = "The Affray", level = 30, zone = "The Barrens", giver = "Klannoc Macleod", giverMap = 1413, giverX = 68.6, giverY = 49.2, ender = "Klannoc Macleod", enderMap = 1413, enderX = 68.6, enderY = 49.2, objective = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.", summary = "If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.$B$BTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.$B$BBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow." },
            { ids = { 1791 }, name = "The Windwatcher", level = 30, zone = "The Barrens", giver = "Klannoc Macleod", giverMap = 1413, giverX = 68.6, giverY = 49.2, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Speak with Bath'rah the Windwatcher.", summary = "Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.$B$BTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.$B$BTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank." },
            { ids = { 1712 }, name = "Cyclonian", level = 40, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.", summary = "I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.$B$BPerhaps you are that champion.$B$BProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.$B$BIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.$B$BHere is a parchment with the items I need." },
            { ids = { 1713 }, name = "The Summoning", level = 40, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Bring the Whirlwind Heart to Bath'rah Windwatcher.", summary = "I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.$B$B$N, are you ready to face the wind lord?" },
            { ids = { 1792 }, name = "Whirlwind Weapon", level = 40, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9 },
        },
    },
    {
        id = "q1798",
        name = "Tome of the Cabal",
        zone = "Ironforge",
        minLevel = 30,
        maxLevel = 30,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 1798 }, name = "Seeking Strahad", level = 30, zone = "Ironforge", giver = "Lago Blackwrench", giverMap = 1455, giverX = 47.6, giverY = 9.3, ender = "Strahad Farsan", enderMap = 1413, enderX = 62.6, enderY = 35.5, objective = "Speak with Strahad Farsan in the Barrens.", summary = "It is time you learned the felhunter summoning, $n. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.$b$bHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming." },
            { ids = { 1758 }, name = "Tome of the Cabal", level = 30, zone = "The Barrens", giver = "Strahad Farsan", giverMap = 1413, giverX = 62.6, giverY = 35.5, ender = "Krom Stoutarm", enderMap = 1455, enderX = 74.2, enderY = 9.4, objective = "Speak with Krom Stoutarm in Ironforge.", summary = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.$b$bMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.$b$bPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge." },
            { ids = { 1802 }, name = "Tome of the Cabal", level = 30, zone = "Ironforge", giver = "Krom Stoutarm", giverMap = 1455, giverX = 74.2, giverY = 9.4, ender = "Krom Stoutarm", enderMap = 1455, enderX = 74.2, enderY = 9.4, objective = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.", summary = "It was lost, but there's some idea as to where it might be found.$b$bThere was only one copy ever made and it was vandalized at some point, a large portion of it ripped from the binding. Rumor has it that it somehow passed into the hands of the centaur of Thousand Needles.$b$bThe rest was lost off the coast west of Southshore, where it was to be transported to Menethil Harbor by boat. It never arrived.$b$bIn exchange for this knowledge, all I ask is that if you find it, bring it to me to see." },
            { ids = { 1804 }, name = "Tome of the Cabal", level = 30, zone = "Ironforge", giver = "Krom Stoutarm", giverMap = 1455, giverX = 74.2, giverY = 9.4, ender = "Strahad Farsan", enderMap = 1413, enderX = 62.6, enderY = 35.5, objective = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", summary = "Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.$b$bWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.$b$bHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcasters!" },
            { ids = { 1795 }, name = "The Binding", level = 30, zone = "The Barrens", giver = "Strahad Farsan", giverMap = 1413, giverX = 62.6, giverY = 35.5, ender = "Strahad Farsan", enderMap = 1413, enderX = 62.6, enderY = 35.5, objective = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.", summary = "If you're are sufficiently prepared, then we should begin. Let me explain the process to you.$b$bI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.$b$bOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, $n. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders." },
        },
    },
    {
        id = "q1947",
        name = "Rituals of Power",
        zone = "Ironforge",
        minLevel = 30,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 8 },
        quests = {
            { ids = { 1947 }, name = "Journey to the Marsh", level = 38, zone = "Ironforge", giver = "Bink", giverMap = 1455, giverX = 27.2, giverY = 8.3, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak with Tabetha.", summary = "Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.$B$BSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins." },
            { ids = { 1948 }, name = "Items of Power", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.", summary = "The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.$B$BI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly." },
            { ids = { 1949 }, name = "Hidden Secrets", level = 38, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Magus Tirth", enderMap = 1441, enderX = 78.3, enderY = 75.7, objective = "Speak with Magus Tirth in the Shimmering Flats.", summary = "To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.$B$BI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.$B$BGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling." },
            { ids = { 1950 }, name = "Get the Scoop", level = 30, zone = "Thousand Needles", giver = "Magus Tirth", giverMap = 1441, giverX = 78.3, giverY = 75.7, ender = "Magus Tirth", enderMap = 1441, enderX = 78.3, enderY = 75.7, objective = "Find the phrase to Tirth's strongbox, then return to Tirth.", summary = "I can help you with the book, but first you have to help me!$B$BThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.$B$BIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!" },
            { ids = { 1951 }, name = "Rituals of Power", level = 40, zone = "Thousand Needles", giver = "Magus Tirth", giverMap = 1441, giverX = 78.3, giverY = 75.7, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", summary = "Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....$B$BA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!$B$BIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days..." },
            { ids = { 1952 }, name = "Mage's Wand", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak with Tabetha after her ritual.", summary = "I'll go make the wands now." },
        },
    },
    {
        id = "q215",
        name = "The Hidden Key",
        zone = "Stranglethorn Vale",
        minLevel = 30,
        maxLevel = 37,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 215 }, name = "Jungle Secrets", level = 33, zone = "Stranglethorn Vale", giver = "Private Thorsen", giverMap = 1434, giverX = 40.3, giverY = 8.4, ender = "Lieutenant Doren", enderMap = 1434, enderX = 38.0, enderY = 3.0, objective = "Speak with Lieutenant Doren at the Rebel Camp.", summary = "Thank you for saving me, $N.  I know how this looks, but...allow me to explain.$B$BI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.$B$BThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain." },
            { ids = { 200 }, name = "Bookie Herod", level = 35, zone = "Stranglethorn Vale", giver = "Lieutenant Doren", giverMap = 1434, giverX = 38.0, giverY = 3.0, ender = "Bookie Herod's Records", enderMap = 1434, enderX = 43.7, enderY = 9.4, objective = "Find Bookie Herod's Records.", summary = "If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!$B$BThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.$B$BWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there." },
            { ids = { 328 }, name = "The Hidden Key", level = 37, zone = "Stranglethorn Vale", giver = "Bookie Herod's Records", giverMap = 1434, giverX = 43.7, giverY = 9.4, ender = "Bookie Herod's Strongbox", enderMap = 1434, enderX = 49.6, enderY = 7.6, objective = "Use the Small Brass Key to open Bookie Herod's Strongbox.", summary = "Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.$B$BAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.$B$BIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed." },
            { ids = { 329 }, name = "The Spy Revealed!", level = 37, zone = "Stranglethorn Vale", giver = "Bookie Herod's Strongbox", giverMap = 1434, giverX = 49.6, giverY = 7.6, ender = "Lieutenant Doren", enderMap = 1434, enderX = 38.0, enderY = 3.0, objective = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.", summary = "Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.$B$BBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp." },
            { ids = { 330 }, name = "Patrol Schedules", level = 37, zone = "Stranglethorn Vale", giver = "Lieutenant Doren", giverMap = 1434, giverX = 38.0, giverY = 3.0, ender = "Corporal Sethman", enderMap = 1434, enderX = 37.7, enderY = 3.4, objective = "Speak with Corporal Sethman.", summary = "The note you gave me is signed with an \"-M\"...I don't know what that could mean.$B$BBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!$B$BGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen." },
            { ids = { 331 }, name = "Report to Doren", level = 37, zone = "Stranglethorn Vale", giver = "Corporal Sethman", giverMap = 1434, giverX = 37.7, giverY = 3.4, ender = "Lieutenant Doren", enderMap = 1434, enderX = 38.0, enderY = 3.0, objective = "Speak with Lieutenant Doren.", summary = "Did Lieutenant Doren want you to report back to him with that patrol information?" },
        },
    },
    {
        id = "q709",
        name = "Solution to Doom",
        zone = "Badlands",
        minLevel = 30,
        maxLevel = 44,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 709 }, name = "Solution to Doom", level = 40, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", summary = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!$B$BNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!$B$BMaybe.$B$BGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!$B$BIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf." },
            { ids = { 727 }, name = "To Ironforge for Yagyin's Digest", level = 40, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Gerrig Bonegrip", enderMap = 1455, enderX = 50.8, enderY = 5.6, objective = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", summary = "The Tablet tells much.  But not enough!  Not nearly enough!$B$BThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!$B$BGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!" },
            { ids = { 735 }, name = "The Star, the Hand and the Heart", level = 44, zone = "Ironforge", giver = "Gerrig Bonegrip", giverMap = 1455, giverX = 50.8, giverY = 5.6, ender = "Gerrig Bonegrip", enderMap = 1455, enderX = 50.8, enderY = 5.6, objective = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.", summary = "Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask.$B$BI will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish.$B$BI require three items of power.  Bring them to me and I will give you the digest.$B$BI will not speak their names.  Ears may be on us.  But here, I will write them down." },
            { ids = { 737 }, name = "Forbidden Knowledge", level = 40, zone = "Ironforge", giver = "Gerrig Bonegrip", giverMap = 1455, giverX = 50.8, giverY = 5.6, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Bring Yagyin's Digest to Theldurin.", summary = "I have the digest for you, $N.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  $B$BThis book holds many truths...$B$B...And the truth can burn." },
        },
    },
    {
        id = "q1453",
        name = "The Karnitol Shipwreck",
        zone = "Ironforge",
        minLevel = 30,
        maxLevel = 39,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1453 }, name = "Reclaimers' Business in Desolace", level = 33, zone = "Ironforge", giver = "Roetten Stonehammer", giverMap = 1455, giverX = 70.0, giverY = 21.3, ender = "Kreldig Ungor", enderMap = 1443, enderX = 66.2, enderY = 9.6, objective = "Speak to Kreldig Ungor in Desolace.", summary = "There's work to be done in Desolace, $N. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.$B$BYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout." },
            { ids = { 1454 }, name = "The Karnitol Shipwreck", level = 39, zone = "Desolace", giver = "Kreldig Ungor", giverMap = 1443, giverX = 66.2, giverY = 9.6, ender = "Karnitol's Chest", enderMap = 1443, enderX = 36.1, enderY = 30.4, objective = "Find Karnitol's Chest in Desolace.", summary = "My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety.$B$BHe wants us to find the chest and its contents, and return it to him in Stormwind." },
            { ids = { 1455 }, name = "The Karnitol Shipwreck", level = 39, zone = "Desolace", giver = "Karnitol's Chest", giverMap = 1443, giverX = 36.1, giverY = 30.4, ender = "Kreldig Ungor", enderMap = 1443, enderX = 66.2, enderY = 9.6, objective = "Return to Kreldig Ungor in Desolace.", summary = "You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword.$B$BAfter going through the chest you find it to be completely empty.$B$BNot having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed." },
            { ids = { 1456 }, name = "The Karnitol Shipwreck", level = 39, zone = "Desolace", giver = "Kreldig Ungor", giverMap = 1443, giverX = 66.2, giverY = 9.6, ender = "Kreldig Ungor", enderMap = 1443, enderX = 66.2, enderY = 9.6, objective = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.", summary = "Intriguing.$B$BWell, we might not be without hope quite yet.$B$BAlong that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet.$B$BIf a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches." },
            { ids = { 1457 }, name = "The Karnitol Shipwreck", level = 39, zone = "Desolace", giver = "Kreldig Ungor", giverMap = 1443, giverX = 66.2, giverY = 9.6, ender = "Roetten Stonehammer", enderMap = 1455, enderX = 70.0, enderY = 21.3, objective = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.", summary = "Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done.$B$BHaha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time.$B$BAgain, great job, $N.$B$BBe careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless." },
        },
    },
    {
        id = "q1437",
        name = "Search for Tyranis",
        zone = "Desolace",
        minLevel = 30,
        maxLevel = 33,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1437 }, name = "Vahlarriel's Search", level = 33, zone = "Desolace", giver = "Vahlarriel Demonslayer", giverMap = 1443, giverX = 66.4, giverY = 11.8, ender = "Malem Chest", enderMap = 1443, enderX = 56.5, enderY = 17.8, objective = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.", summary = "I am Vahlarriel, $N. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.$B$BLast word tells of them passing through the Stonetalon Mountains a few weeks ago.$B$BIf you find their wagon, please, come find me immediately." },
            { ids = { 1465 }, name = "Vahlarriel's Search", level = 33, zone = "Desolace", giver = "Malem Chest", giverMap = 1443, giverX = 56.5, giverY = 17.8, ender = "Vahlarriel Demonslayer", enderMap = 1443, enderX = 66.4, enderY = 11.8, objective = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.", summary = "As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction.$B$BYou think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south." },
            { ids = { 1438 }, name = "Vahlarriel's Search", level = 33, zone = "Desolace", giver = "Vahlarriel Demonslayer", giverMap = 1443, giverX = 66.4, giverY = 11.8, ender = "Dalinda Malem", enderMap = 1443, enderX = 54.9, enderY = 26.1, objective = "Find Dalinda Malem in Desolace.", summary = "Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.$B$B$N, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home." },
            { ids = { 1439 }, name = "Search for Tyranis", level = 33, zone = "Desolace", giver = "Dalinda Malem", giverMap = 1443, giverX = 54.9, giverY = 26.1, ender = "Dalinda Malem", enderMap = 1443, enderX = 54.9, enderY = 26.1, objective = "Find Tyranis Malem in Desolace.", summary = "We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.$B$BTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.$B$BPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known." },
            { ids = { 1440 }, name = "Return to Vahlarriel", level = 33, zone = "Desolace", giver = "Dalinda Malem", giverMap = 1443, giverX = 54.9, giverY = 26.1, ender = "Vahlarriel Demonslayer", enderMap = 1443, enderX = 66.4, enderY = 11.8, objective = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.", summary = "So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right." },
        },
    },
    {
        id = "q707",
        name = "Ironband Wants You!",
        zone = "Ironforge",
        minLevel = 30,
        maxLevel = 42,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 707 }, name = "Ironband Wants You!", level = 37, zone = "Ironforge", giver = "Prospector Stormpike", giverMap = 1455, giverX = 74.6, giverY = 11.7, ender = "Prospector Ironband", enderMap = 1432, enderX = 65.9, enderY = 65.6, objective = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.", summary = "$N.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.$B$BI don't have more details than that, but if you want to stretch your legs then go speak with Ironband." },
            { ids = { 738 }, name = "Find Agmond", level = 38, zone = "Loch Modan", giver = "Prospector Ironband", giverMap = 1432, giverX = 65.9, giverY = 65.6, ender = "Battered Dwarven Skeleton", enderMap = 1418, enderX = 50.9, enderY = 62.4, objective = "Find Agmond.", summary = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say \"was\" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report.$B$BLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there." },
            { ids = { 739 }, name = "Murdaloc", level = 42, zone = "Badlands", giver = "Battered Dwarven Skeleton", giverMap = 1418, giverX = 50.9, giverY = 62.4, ender = "Prospector Ironband", enderMap = 1432, enderX = 65.9, enderY = 65.6, objective = "Slay Agmond's killer, Murdaloc.$B$BSlay 12 Stonevault Bonesnappers.$B$BReport to Prospector Ironband in Loch Modan.", summary = "Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.$B$BAnd here he died.$B$BUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.$B$BScrawled next to Agmond's dead hand." },
            { ids = { 704 }, name = "Agmond's Fate", level = 38, zone = "Loch Modan", giver = "Prospector Ironband", giverMap = 1432, giverX = 65.9, giverY = 65.6, ender = "Prospector Ironband", enderMap = 1432, enderX = 65.9, enderY = 65.6, objective = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.", summary = "The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.$B$BI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me." },
        },
    },
    {
        id = "q652",
        name = "Summoning the Princess",
        zone = "Arathi Highlands",
        minLevel = 30,
        maxLevel = 50,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 642 }, name = "The Princess Trapped", level = 37, zone = "Arathi Highlands", giver = "Shards of Myzrael", giverMap = 1417, giverX = 62.5, giverY = 33.7, ender = "Iridescent Shards", enderMap = 1417, enderX = 84.3, enderY = 30.9, objective = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.", summary = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.$B$BPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.$B$BI beg you, $N, aid me!" },
            { ids = { 651 }, name = "Stones of Binding", level = 38, zone = "Arathi Highlands", giver = "Iridescent Shards", giverMap = 1417, giverX = 84.3, giverY = 30.9, ender = "Stone of Inner Binding", enderMap = 1417, enderX = 36.2, enderY = 57.4, objective = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.$B$BBring them to the Stone of Inner Binding.", summary = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.$B$BTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.$B$BThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them." },
            { ids = { 652 }, name = "Breaking the Keystone", level = 42, zone = "Arathi Highlands", giver = "Stone of Inner Binding", giverMap = 1417, giverX = 36.2, giverY = 57.4, ender = "Keystone", enderMap = 1417, enderX = 36.1, enderY = 58.1, objective = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.", summary = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.$B$BYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.$B$B$N, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!" },
            { ids = { 653 }, name = "Myzrael's Allies", level = 40, zone = "Arathi Highlands", giver = "Keystone", giverMap = 1417, giverX = 36.1, giverY = 58.1, ender = "Gerrig Bonegrip", enderMap = 1455, enderX = 50.8, enderY = 5.6, objective = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", summary = "<Myzrael speaks.>$B$BFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.$B$BBut in time I will confront the giants, and they will regret their wardship of me!$B$BYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface.$B$BSpeak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned." },
            { ids = { 687 }, name = "Theldurin the Lost", level = 40, zone = "Ironforge", giver = "Gerrig Bonegrip", giverMap = 1455, giverX = 50.8, giverY = 5.6, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Find Theldurin the Lost.", summary = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.$B$BTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin." },
            { ids = { 692 }, name = "The Lost Fragments", level = 41, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", summary = "The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!$B$BOr...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll!$B$B...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments.$B$BBut if you can gather those fragments, maybe we can fix it..." },
            { ids = { 656 }, name = "Summoning the Princess", level = 50, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Shards of Myzrael", enderMap = 1417, enderX = 62.5, enderY = 33.7, objective = "Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.", summary = "You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place??$B$BCrazy logic, eh?$B$BTo defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael.$B$BDo that, and she will again be trapped." },
        },
    },
    {
        id = "q4738",
        name = "The Completed Robe",
        zone = "Stormwind City",
        minLevel = 31,
        maxLevel = 38,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 4738 }, name = "In Search of Menara Voidrender", level = 31, zone = "Stormwind City", giver = "Demisette Cloyce", giverMap = 1453, giverX = 39.2, giverY = 85.0, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Speak with Menara Voidrender in the Barrens.", summary = "Let us be clear about one thing, $N: I don't feel you are ready for such responsibilities. I don't think aiding in the creation of any item of power is something a novice should ever be involved in; especially one so untested.$B$BBut that's not my decision. The powers that be, or at least the ones that do wish to impart such gifts upon you get to decide that.$B$BIf you're interested in learning more, I suggest you seek out Menara Voidrender in Ratchet. She usually resides in the tower above the port town." },
            { ids = { 1796 }, name = "Components for the Enchanted Gold Bloodrobe", level = 31, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Bring Robes of the Arcana to Menara Voidrender in the Barrens.", summary = "The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.$B$BTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from there." },
            { ids = { 4781 }, name = "Components for the Enchanted Gold Bloodrobe", level = 34, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Xizk Goodstitch", enderMap = 1434, enderX = 28.7, enderY = 76.9, objective = "Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.", summary = "Your next task is as simple as your first, but will require you to seek out aid.$B$BI require gold thread for the embroidery of the cloak, but gold thread is not easy to come by, and very few know how to make it. Fortunately, one who is loyal to our cause knows its secrets and is willing to help those rising in our ranks.$B$BBring a gold bar to Xizk Goodstitch in Booty Bay. He is a master tailor and will be happy to spin the thread for you. Gold bars are smelted by skilled miners. Ask a miner for help." },
            { ids = { 4782 }, name = "Components for the Enchanted Gold Bloodrobe", level = 34, zone = "Stranglethorn Vale", giver = "Xizk Goodstitch", giverMap = 1434, giverX = 28.7, giverY = 76.9, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Return to Menara Voidrender in the Barrens.", summary = "Return to Menara, tell her it'll take some time, but I'll make sure to come through for her... and you. Tell her to have you finish gathering the rest of your components--I should have the thread done by then. You can return and pick it up then.$B$BGood luck, $N. Oh, and say hello to Strahad for me while you're there. That old coot... putting a tower right there next to Ratchet... crazy." },
            { ids = { 4783 }, name = "Components for the Enchanted Gold Bloodrobe", level = 37, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.", summary = "The next components are found in Desolace, far to the west of the Barrens and even the Stonetalon Mountains.$B$BThere, chaos still reigns after the Sundering. Both your strength and cunning will be tested there--you will face creatures of hatred and also of the Burning Legion.$B$BFrom the Hatefury satyr in the northeast, bring me their blood. From the lesser infernals in Mannoroc Coven, bring me a lesser infernal stone.$B$BWe will use both in the construction of your robe." },
            { ids = { 4784 }, name = "Components for the Enchanted Gold Bloodrobe", level = 37, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.", summary = "I need only three things now, $N, then we can finish your robe.$B$BFirst, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it.$B$BSecond, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin's Wall.$B$BFinally, a soul shard created by you.$B$BAfter you have all the components, return here to the tower and I will complete the robe for you." },
            { ids = { 4786 }, name = "The Completed Robe", level = 38, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Wait for Menara Voidrender to complete your robe and then speak to her again.", summary = "I will put the robe together for you now. It will take but a few moments. Do not go far." },
        },
    },
    {
        id = "q616",
        name = "Magical Analysis",
        zone = "Stranglethorn Vale",
        minLevel = 32,
        maxLevel = 40,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 616 }, name = "The Haunted Isle", level = 37, zone = "Stranglethorn Vale", giver = "Krazek", giverMap = 1434, giverX = 26.9, giverY = 77.2, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Speak with Baron Revilgaz in Booty Bay.", summary = "Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.$b$bIf you're going to go talk to Revilgaz, could you relay that story to him?" },
            { ids = { 578 }, name = "The Stone of the Tides", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Find the haunted island for Baron Revilgaz in Booty Bay.", summary = "If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!$b$bI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.$b$bCould it be that Gazban actually discovered the Stone...?" },
            { ids = { 601 }, name = "Water Elementals", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.", summary = "The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...$b$bPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens." },
            { ids = { 602 }, name = "Magical Analysis", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Archmage Ansirem Runeweaver", enderMap = 1416, enderX = 18.8, enderY = 78.5, objective = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.", summary = "From what I've heard, the mages of Dalaran are busy with the reconstruction of their destroyed city, I'm sure you can find one of them who will spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.$b$bTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver in particular.  I've dealt with him before, and his knowledge is vast." },
            { ids = { 603 }, name = "Ansirem's Key", level = 37, zone = "Alterac Mountains", giver = "Archmage Ansirem Runeweaver", giverMap = 1416, giverX = 18.8, giverY = 78.5, ender = "Catelyn the Blade", enderMap = 1434, enderX = 27.3, enderY = 77.5, objective = "Talk to Catelyn in Booty Bay.", summary = "The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.$b$bAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.$b$bYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate." },
            { ids = { 610 }, name = "\"Pretty Boy\" Duncan", level = 39, zone = "Stranglethorn Vale", giver = "Catelyn the Blade", giverMap = 1434, giverX = 27.3, giverY = 77.5, ender = "Catelyn the Blade", enderMap = 1434, enderX = 27.3, enderY = 77.5, objective = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.", summary = "My FATHER sent you? I'd have thought that old codger would have given up on me by now.$b$bIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!$b$bIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up." },
            { ids = { 611 }, name = "The Curse of the Tides", level = 40, zone = "Stranglethorn Vale", giver = "Catelyn the Blade", giverMap = 1434, giverX = 27.3, giverY = 77.5, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.", summary = "So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.$b$bYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!" },
        },
    },
    {
        id = "q6141",
        name = "In the Name of the Light",
        zone = "Stormwind City",
        minLevel = 34,
        maxLevel = 40,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 6141 }, name = "Brother Anton", level = 39, zone = "Stormwind City", giver = "Brother Crowley", giverMap = 1453, giverX = 52.6, giverY = 43.2, ender = "Brother Anton", enderMap = 1443, enderX = 66.5, enderY = 7.9, objective = "Speak with Brother Anton in Desolace.", summary = "My brother in arms, Brother Anton, heard rumors of an undead infestation in distant Kalimdor, in a land known as Desolace.  Anton immediately booked passage to that place, to seek and destroy the undead menace!$B$BHe is looking for those with the bravery and resolve to aid him.  If your heart is true, then speak with Anton.  He is in Desolace, in the Alliance town of Nijel's Point. " },
            { ids = { 261 }, name = "Down the Scarlet Path", level = 39, zone = "Desolace", giver = "Brother Anton", giverMap = 1443, giverX = 66.5, giverY = 7.9, ender = "Brother Anton", enderMap = 1443, enderX = 66.5, enderY = 7.9, objective = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.", summary = "I will be frank.  We are at war with the Scourge.  It is an evil that corrupts our people and infects our land.  It must be stopped before it overwhelms us and drags our world into shadow.  We of the Scarlet Crusade have sworn to fight the Scourge with body and soul.$B$BIf you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south.$B$BDo this, and the Crusade will embrace you." },
            { ids = { 1052 }, name = "Down the Scarlet Path", level = 40, zone = "Desolace", giver = "Brother Anton", giverMap = 1443, giverX = 66.5, giverY = 7.9, ender = "Raleigh the Devout", enderMap = 1424, enderX = 51.5, enderY = 58.4, objective = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.", summary = "We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.$b$bYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.$b$bTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery." },
            { ids = { 1053 }, name = "In the Name of the Light", level = 40, zone = "Hillsbrad Foothills", giver = "Raleigh the Devout", giverMap = 1424, giverX = 51.5, giverY = 58.4, ender = "Raleigh the Devout", enderMap = 1424, enderX = 51.5, enderY = 58.4, objective = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.", summary = "I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.$b$bBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued. $b$bThe Scarlet Crusade must be crushed in the name of the Light. You, $n, must destroy the deranged regime." },
        },
    },
    {
        id = "q720",
        name = "A Sign of Hope",
        zone = "Badlands",
        minLevel = 35,
        maxLevel = 45,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 720 }, name = "A Sign of Hope", level = 35, zone = "Badlands", giver = "Crumpled Map", giverMap = 1418, giverX = 53.0, giverY = 33.9, ender = "Prospector Ryedol", enderMap = 1418, enderX = 53.4, enderY = 43.4, objective = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.", summary = "<There is text roughly scribbled in chalk on the map.>$B$B\"Ryedol, $BThey're taking me to Uldaman. Send help.$B-Hammertoe\"" },
            { ids = { 721 }, name = "A Sign of Hope", level = 35, zone = "Badlands", giver = "Prospector Ryedol", giverMap = 1418, giverX = 53.4, giverY = 43.4, ender = "Hammertoe Grez", enderMap = 1418, enderX = 37.9, enderY = 10.6, objective = "Find Hammertoe Grez in Uldaman.", summary = "$N, can ye find him? Can you find Hammertoe in Uldaman?$B$BIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.$B$BFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.$B$BThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!" },
            { ids = { 722 }, name = "Amulet of Secrets", level = 40, zone = "Badlands", giver = "Hammertoe Grez", giverMap = 1418, giverX = 37.9, giverY = 10.6, ender = "Hammertoe Grez", enderMap = 1418, enderX = 37.9, enderY = 10.6, objective = "Find Hammertoe's Amulet and return it to him in Uldaman.", summary = "Ye're brave... <cough>... to come into Uldaman fer me, $c.$B$BIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.$B$BDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, $N. Please... get that amulet.$B$BThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones." },
            { ids = { 723 }, name = "Prospect of Faith", level = 40, zone = "Badlands", giver = "Hammertoe Grez", giverMap = 1418, giverX = 37.9, giverY = 10.6, ender = "Prospector Ryedol", enderMap = 1418, enderX = 53.4, enderY = 43.4, objective = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.", summary = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>$B$BFind Ryedol, $N. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>" },
            { ids = { 724 }, name = "Prospect of Faith", level = 40, zone = "Badlands", giver = "Prospector Ryedol", giverMap = 1418, giverX = 53.4, giverY = 43.4, ender = "Historian Karnik", enderMap = 1455, enderX = 77.5, enderY = 11.8, objective = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.", summary = "Okay, okay... who would know what to do?$B$BHistorian Karnik! That's it!$B$BHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.$B$BGuess the Shadowforge found out the two of them knew more than they were lettin' on.$B$BTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next." },
            { ids = { 725 }, name = "Passing Word of a Threat", level = 40, zone = "Ironforge", giver = "Historian Karnik", giverMap = 1455, giverX = 77.5, giverY = 11.8, ender = "Advisor Belgrum", enderMap = 1455, enderX = 77.3, enderY = 9.7, objective = "Find Advisor Belgrum and give him his note.", summary = "$N, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.$B$BIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray." },
            { ids = { 726 }, name = "Passing Word of a Threat", level = 40, zone = "Ironforge", giver = "Advisor Belgrum", giverMap = 1455, giverX = 77.3, giverY = 9.7, ender = "Historian Karnik", enderMap = 1455, enderX = 77.5, enderY = 11.8, objective = "Speak to Historian Karnik.", summary = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>$B$BOch, these are evil tidings.$B$B$N, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands." },
            { ids = { 762 }, name = "An Ambassador of Evil", level = 44, zone = "Ironforge", giver = "Historian Karnik", giverMap = 1455, giverX = 77.5, giverY = 11.8, ender = "Advisor Belgrum", enderMap = 1455, enderX = 77.3, enderY = 9.7, objective = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", summary = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.$B$BIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.$B$BOur goal is simple, $c. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.$B$BIt is in your hands now." },
            { ids = { 1139 }, name = "The Lost Tablets of Will", level = 45, zone = "Ironforge", giver = "Advisor Belgrum", giverMap = 1455, giverX = 77.3, giverY = 9.7, ender = "Advisor Belgrum", enderMap = 1455, enderX = 77.3, enderY = 9.7, objective = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", summary = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.$B$BWe must still recover the Tablet before the Shadowforge clan finds it.$B$BReturn to Uldaman, find the tablet, and return here immediately." },
        },
    },
    {
        id = "q1953",
        name = "Power in Uldaman",
        zone = "Ironforge",
        minLevel = 35,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 8 },
        quests = {
            { ids = { 1953 }, name = "Return to the Marsh", level = 40, zone = "Ironforge", giver = "Bink", giverMap = 1455, giverX = 27.2, giverY = 8.3, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak with Tabetha.", summary = "It is time, $N, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.$B$BTabetha's shack lies deep in Dustwallow Marsh, west of Theramore." },
            { ids = { 1954 }, name = "The Infernal Orb", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh.", summary = "The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.$B$BGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.$B$BWhen you have the orb, return to me." },
            { ids = { 1955 }, name = "The Exorcism", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Kill the Demon of the Orb, then speak with Tabetha.", summary = "Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.$B$BYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.$B$BAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!$B$BSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty." },
            { ids = { 1956 }, name = "Power in Uldaman", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", summary = "Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?$B$BSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!$B$BI wish you the best of luck, $N.  And if you don't get lucky then, well... it was nice knowing you." },
            { ids = { 1957 }, name = "Mana Surges", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Kill 12 Mana Surges in the allowed time limit.", summary = "We are almost finished, but this last step is the most perilous, $N.$B$BI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.$B$BKill enough mana surges before the rift closes and I will place all their collected energy in your orb." },
            { ids = { 1958 }, name = "Celestial Power", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1 },
        },
    },
    {
        id = "q4965",
        name = "Cleansing of the Orb of Orahil",
        zone = "The Barrens",
        minLevel = 35,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 4962 }, name = "Shard of a Felhound", level = 40, zone = "The Barrens", giver = "Acolyte Wytula", giverMap = 1413, giverX = 62.6, giverY = 35.3, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", summary = "So, you have chosen to capture the soul of a felhound, good.$B$BTake this ruby--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.$B$BI would suggest going to Desolace and trying your hand at any of the felhounds there. Those should do nicely.$B$BAfter you're successful, take both the captured spirit and your ruby to Menara." },
            { ids = { 4965 }, name = "Knowledge of the Orb of Orahil", level = 35, zone = "Ironforge", giver = "Briarthorn", giverMap = 1455, giverX = 50.4, giverY = 5.7, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Speak to Menara Voidrender in the Barrens.", summary = "Well, well, well... a pleasure to see you're growing in power, $N. I'd wager you'd be about ready to speak to Menara Voidrender in the Barrens. If you haven't spoken to her before, then let me tell you, I don't think I've ever met another expert in the creation of items--orbs specifically--that can inprison even a demon to serve our will so easily.$B$BIf you're interested, she's in Strahad's tower above Ratchet in the Barrens." },
            { ids = { 1799 }, name = "Fragments of the Orb of Orahil", level = 40, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.$B$BAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh.", summary = "Good, then we shall begin.$B$BThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.$B$BSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.$B$BAgain, do not come back until you have done both things I've asked." },
            { ids = { 4961 }, name = "Cleansing of the Orb of Orahil", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Kill the Demon of the Orb, then speak with Tabetha.", summary = "Ah, a summoner's orb--this is where the taint must be coming from. We must exorcise the demon within it if you're to use it. That I can do easily.$B$BYou're the one who has the hard job.  You must kill the demon once I release it.$B$BAnd you'll have to be quick.  If you take too long then he'll return to the orb and we'll have to start over!$B$BSo get yourself ready, $N.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty." },
            { ids = { 4976 }, name = "Returning the Cleansed Orb", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens.", summary = "Take the cleansed orb back to Menara in Ratchet, $N. Give her my regards and be safe. I truly hope you are able to withstand the temptation and corruption that is sure to come as you follow your path.$B$BGood luck." },
            { ids = { 4964 }, name = "The Completed Orb of Dar'Orahil", level = 40, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", summary = "I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice." },
        },
    },
    {
        id = "q2398",
        name = "The Lost Dwarves",
        zone = "Ironforge",
        minLevel = 35,
        maxLevel = 40,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 2398 }, name = "The Lost Dwarves", level = 40, zone = "Ironforge", giver = "Prospector Stormpike", giverMap = 1455, giverX = 74.6, giverY = 11.7, ender = "Baelog", enderMap = 1418, enderX = 44.6, enderY = 12.1, enderInside = "Uldaman", objective = "Find Baelog in Uldaman.", summary = "The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!$B$BIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.$B$BMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them." },
            { ids = { 2240 }, name = "The Hidden Chamber", level = 40, zone = "Uldaman", giver = "Baelog", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "Prospector Stormpike", enderMap = 1455, enderX = 74.6, enderY = 11.7, objective = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.", summary = "Now for the task at hand.$B$BThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.$B$BI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, $N, must find the chamber of Khaz'mul for us!$B$BRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge." },
        },
    },
    {
        id = "q663",
        name = "Land Ho!",
        zone = "Arathi Highlands",
        minLevel = 35,
        maxLevel = 44,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 663 }, name = "Land Ho!", level = 35, zone = "Arathi Highlands", giver = "Lolo the Lookout", giverMap = 1417, giverX = 31.8, giverY = 82.7, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Talk to Captain O'Breen in Faldir's Cove.", summary = "Lolo sees a tiny $r! Always on the lookout, Lolo is!$b$bWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.$b$bBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!$b$bLolo suggests you talk to Captain O'Breen if you plan on sticking around here." },
            { ids = { 665 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Professor Phizzlethorpe", giverMap = 1417, giverX = 33.9, giverY = 80.5, ender = "Doctor Draxlegauge", enderMap = 1417, enderX = 33.9, enderY = 80.5, objective = "Escort Professor Phizzlethorpe to the cave and back.", summary = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.$b$bIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.$b$bBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles." },
            { ids = { 666 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Doctor Draxlegauge", giverMap = 1417, giverX = 33.9, giverY = 80.5, ender = "Doctor Draxlegauge", enderMap = 1417, enderX = 33.9, enderY = 80.5, objective = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", summary = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.$b$bA little gnomish ingenuity goes a long way!$b$bSo borrow the Goggles of Gem Hunting, $n, and see if you can collect some of the lost treasure for Captain O'Breen.$b$bI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah." },
            { ids = { 668 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Doctor Draxlegauge", giverMap = 1417, giverX = 33.9, giverY = 80.5, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Take the Elven Gems to Captain O'Breen.", summary = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!$b$bAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.$b$bHere, $n, take these to O'Breen." },
            { ids = { 669 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Shakes O'Breen", giverMap = 1417, giverX = 32.3, giverY = 81.4, ender = "Fleet Master Seahorn", enderMap = 1434, enderX = 27.2, enderY = 77.0, objective = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.", summary = "Fleet Master Seahorn will want to hear about our find at once.$b$bBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.$b$bYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof." },
            { ids = { 670 }, name = "Sunken Treasure", level = 40, zone = "Stranglethorn Vale", giver = "Fleet Master Seahorn", giverMap = 1434, giverX = 27.2, giverY = 77.0, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.", summary = "Say, $n, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.$b$bThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.$b$bCan I trust you to deliver this message safely and in confidence?" },
            { ids = { 667 }, name = "Death From Below", level = 44, zone = "Arathi Highlands", giver = "Shakes O'Breen", giverMap = 1417, giverX = 32.3, giverY = 81.4, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Protect Shakes O'Breen during the attack.", summary = "This is bad. It seems the Daggerspines are amassing for an attack.$b$bNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.$b$bI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.$b$bThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.$b$bAre you ready, $n?" },
        },
    },
    {
        id = "q2198",
        name = "Restoring the Necklace",
        zone = "Uldaman",
        minLevel = 37,
        maxLevel = 44,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 2198 }, name = "The Shattered Necklace", level = 41, zone = "Uldaman", ender = "Talvash del Kissel", enderMap = 1455, enderX = 36.4, enderY = 3.6, objective = "Search for the original creator of the shattered necklace to learn of its potential value.", summary = "You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship.  The necklace has been shattered, as its setting appears to be missing three gems.  On the underside of the necklace is the faint imprint of the city seal for Ironforge.  Below the seal are three tiny, engraved letters: \"TdK\".$B$BIf there is anything to be gleaned from the necklace, you will need to learn about its origins.  Perhaps the seal and the initials are a start..." },
            { ids = { 2199 }, name = "Lore for a Price", level = 41, zone = "Ironforge", giver = "Talvash del Kissel", giverMap = 1455, giverX = 36.4, giverY = 3.6, ender = "Talvash del Kissel", enderMap = 1455, enderX = 36.4, enderY = 3.6, objective = "Bring five silver bars to Talvash del Kissel in Ironforge.", summary = "I am a jeweler of great renown here in Ironforge!  Well, former renown anyway... I have fallen onto hard times due to the chicanery of a competitor!  A bad reputation in this business spells financial disaster.  As a result, I find myself without a copper to my good-though-currently-sullied name.$B$BI want you to get me five silver bars to finish an order I received - the first in what seems like an eternity.$B$BYou get me those five silver bars, and I'll answer your questions on the necklace." },
            { ids = { 2200 }, name = "Back to Uldaman", level = 42, zone = "Ironforge", giver = "Talvash del Kissel", giverMap = 1455, giverX = 36.4, giverY = 3.6, ender = "Remains of a Paladin", enderMap = 1418, enderX = 44.6, enderY = 12.1, enderInside = "Uldaman", objective = "Search for clues as to the current disposition of Talvash's necklace within Uldaman.  The slain paladin he mentioned was the person who has it last.", summary = "A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.$B$B$N, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!$B$BTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge." },
            { ids = { 2201 }, name = "Find the Gems", level = 43, zone = "Uldaman", giver = "Remains of a Paladin", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "Talvash's Scrying Bowl", enderMap = 1418, enderX = 44.6, enderY = 12.1, enderInside = "Uldaman", objective = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman.  Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B$B* The sapphire has been claimed by Grimlok, the trogg leader.", summary = "The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.$B$BArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions." },
            { ids = { 2204 }, name = "Restoring the Necklace", level = 44, zone = "Uldaman", giver = "Talvash's Scrying Bowl", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "Talvash del Kissel", enderMap = 1455, enderX = 36.4, enderY = 3.6, objective = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.", summary = "You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.$B$BWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!" },
            { ids = { 2361 }, name = "Restoring the Necklace", level = 44, zone = "Ironforge", giver = "Talvash del Kissel", giverMap = 1455, giverX = 36.4, giverY = 3.6, ender = "Talvash del Kissel", enderMap = 1455, enderX = 36.4, enderY = 3.6 },
        },
    },
    {
        id = "q2969",
        name = "Doling Justice",
        zone = "Feralas",
        minLevel = 37,
        maxLevel = 48,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 2969 }, name = "Freedom for All Creatures", level = 47, zone = "Feralas", giver = "Kindal Moonweaver", giverMap = 1444, giverX = 65.9, giverY = 45.6, ender = "Kindal Moonweaver", enderMap = 1444, enderX = 65.9, enderY = 45.6, objective = "Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.$B$BYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest.", summary = "The filthy Grimtotem clan are capturing faerie dragons, $N. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.$B$BWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...$B$BIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here." },
            { ids = { 2970 }, name = "Doling Justice", level = 47, zone = "Feralas", giver = "Jer'kai Moonweaver", giverMap = 1444, giverX = 66.0, giverY = 45.6, ender = "Jer'kai Moonweaver", enderMap = 1444, enderX = 66.0, enderY = 45.6, objective = "Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas.", summary = "As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.$B$BYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons." },
            { ids = { 2972 }, name = "Doling Justice", level = 47, zone = "Feralas", giver = "Jer'kai Moonweaver", giverMap = 1444, giverX = 66.0, giverY = 45.6, ender = "Tyrande Whisperwind", enderMap = 1457, enderX = 39.1, enderY = 81.6, objective = "Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.", summary = "Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.$B$BWe both thank you, $N." },
            { ids = { 3841 }, name = "An Orphan Looking For a Home", level = 47, zone = "Feralas", giver = "Kindal Moonweaver", giverMap = 1444, giverX = 65.9, giverY = 45.6, ender = "Quentin", enderMap = 1441, enderX = 78.3, enderY = 74.7, objective = "Speak to Quentin in Thousand Needles.", summary = "Oh, hello, $N. I'm so glad to see you again. How was your trip to Darnassus?$B$BWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.$B$BSay, would you want one for a pet? They look to hatch soon, so they'll need a good $Gfather:mother;. What do you say?$B$BIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more." },
            { ids = { 3842 }, name = "A Short Incubation", level = 47, zone = "Thousand Needles", giver = "Quentin", giverMap = 1441, giverX = 78.3, giverY = 74.7, ender = "Quentin", enderMap = 1441, enderX = 78.3, enderY = 74.7, objective = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.", summary = "The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.$B$BSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.$B$BI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me." },
            { ids = { 3843 }, name = "The Newest Member of the Family", level = 47, zone = "Thousand Needles", giver = "Quentin", giverMap = 1441, giverX = 78.3, giverY = 74.7, ender = "Agnar Beastamer", enderMap = 1425, enderX = 14.2, enderY = 43.6, objective = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.", summary = "A magnificent specimen, $N. If this creature survives gestation, then it'll be a healthy pet indeed!$B$BThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.$B$BBut hurry, $N, this egg is fragile and will not last long without proper care." },
            { ids = { 4297 }, name = "Food for Baby", level = 47, zone = "The Hinterlands", giver = "Agnar Beastamer", giverMap = 1425, giverX = 14.2, giverY = 43.6, ender = "Agnar Beastamer", enderMap = 1425, enderX = 14.2, enderY = 43.6, objective = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.", summary = "Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.$B$BI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched." },
            { ids = { 4298 }, name = "Becoming a Parent", level = 48, zone = "The Hinterlands", giver = "Agnar Beastamer", giverMap = 1425, giverX = 14.2, giverY = 43.6, ender = "Agnar Beastamer", enderMap = 1425, enderX = 14.2, enderY = 43.6, objective = "Speak to Agnar Beastamer in the Hinterlands.", summary = "Whoa, it was a lot more ready than I thought..." },
        },
    },
    {
        id = "q992",
        name = "Pawn Captures Queen",
        zone = "Tanaris",
        minLevel = 38,
        maxLevel = 54,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 992 }, name = "Gadgetzan Water Survey", level = 46, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Senior Surveyor Fizzledowser", enderMap = 1446, enderX = 50.2, enderY = 27.5, objective = "Use the untapped dowsing widget near the pool of water by Sandsorrow Watch.  Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.", summary = "We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!$B$BWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.$B$BTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!" },
            { ids = { 82 }, name = "Noxious Lair Investigation", level = 47, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", summary = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.$B$BLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!" },
            { ids = { 10 }, name = "The Scrimshank Redemption", level = 48, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Senior Surveyor Fizzledowser", enderMap = 1446, enderX = 50.2, enderY = 27.5, objective = "Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", summary = "Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?$B$BI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod." },
            { ids = { 110 }, name = "Insect Part Analysis", level = 48, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.", summary = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.$B$BI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me." },
            { ids = { 113 }, name = "Insect Part Analysis", level = 48, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Senior Surveyor Fizzledowser", enderMap = 1446, enderX = 50.2, enderY = 27.5, objective = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan.  Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.", summary = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.$B$BHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!" },
            { ids = { 162 }, name = "Rise of the Silithid", level = 49, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Gracina Spiritmight", enderMap = 1457, enderX = 41.8, enderY = 85.6, objective = "Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.", summary = "I urge you to take this report to someone who has working knowledge in this kind of thing.$B$BI know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help.$B$BLast I heard, she was residing in the Temple of the Moon, located in Darnassus." },
            { ids = { 4493 }, name = "March of the Silithid", level = 53, zone = "Darnassus", giver = "Gracina Spiritmight", giverMap = 1457, giverX = 41.8, giverY = 85.6, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Speak to Alchemist Pestlezugg in Gadgetzan.", summary = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.$B$BWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid." },
            { ids = { 4496 }, name = "Bungle in the Jungle", level = 53, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", summary = "My research revealed to me that the silithid are like bees; destroy the queen of the hive, and the rest of should be thrown into disarray.  I'll brew a lure that we'll use to bring out the queen; once summoned, you'll take her down.$B$BFirst though, we need some reagents; we don't want you bungling into the jungle unprepared.  Go west to find the silithid hive in Un'Goro Crater and obtain a scent gland from one of the bugs.  I'll also need some samples of the native Un'Goro soil." },
            { ids = { 4507 }, name = "Pawn Captures Queen", level = 54, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Defeat the Gorishi Hive Queen once she is summoned.$B$BBring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.", summary = "Here's the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I'd say try the hatcheries inside the hive.$B$BUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, $N!" },
            { ids = { 4508 }, name = "Calm Before the Storm", level = 54, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Gracina Spiritmight", enderMap = 1457, enderX = 41.8, enderY = 85.6, objective = "Bring Pestlezugg's Un'Goro Report to Gracina Spiritmight in Darnassus.", summary = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.$B$BTake my latest report back to Gracina Spiritmight in Darnassus; she's still at the Temple of the Moon, is she not?  She's got friends who are Alliance bigwigs; if we can get them involved in this $N, then we just might make it out of this alive." },
            { ids = { 4510 }, name = "Calm Before the Storm", level = 54, zone = "Darnassus", giver = "Gracina Spiritmight", giverMap = 1457, giverX = 41.8, giverY = 85.6, ender = "Idriana", enderMap = 1457, enderX = 39.4, enderY = 42.4, objective = "Bring the Bank Voucher to Idriana in the bank of Darnassus.", summary = "$N, your help has been immeasurable.  The time will come, no doubt, when I'll ask for your assistance against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.$B$BTake this note to Idriana at the bank.  She'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, brave $c." },
        },
    },
    {
        id = "q1448",
        name = "Into The Temple of Atal'Hakkar",
        zone = "Stormwind City",
        minLevel = 38,
        maxLevel = 50,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 1448 }, name = "In Search of The Temple", level = 43, zone = "Stormwind City", giver = "Brohann Caskbelly", giverMap = 1453, giverX = 69.5, giverY = 40.4, ender = "Brohann Caskbelly", enderMap = 1453, enderX = 69.5, enderY = 40.4, objective = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.", summary = "There was a time when I was young and full of vigor like you, $c.$b$bBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!$b$bBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.$b$bBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.$b$bHelp an old dwarf out? Perhaps you will have better luck on foot." },
            { ids = { 1449 }, name = "To The Hinterlands", level = 43, zone = "Stormwind City", giver = "Brohann Caskbelly", giverMap = 1453, giverX = 69.5, giverY = 40.4, ender = "Falstad Wildhammer", enderMap = 1425, enderX = 11.8, enderY = 46.8, objective = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.", summary = "As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.$b$bI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...$b$bIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.$b$bJourney there and seek out Falstad Wildhammer.$b$bWe need to find out what happened to that pilot." },
            { ids = { 1450 }, name = "Gryphon Master Talonaxe", level = 43, zone = "The Hinterlands", giver = "Falstad Wildhammer", giverMap = 1425, giverX = 11.8, giverY = 46.8, ender = "Gryphon Master Talonaxe", enderMap = 1425, enderX = 9.8, enderY = 44.5, objective = "Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.", summary = "So you're a glorified errand $g boy:girl; for some old Explorers' League geezer, eh?$b$bWell you listen to me, $c. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?$b$bIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.$b$bNow get a move on." },
            { ids = { 1451 }, name = "Rhapsody Shindigger", level = 43, zone = "The Hinterlands", giver = "Gryphon Master Talonaxe", giverMap = 1425, giverX = 9.8, giverY = 44.5, ender = "Rhapsody Shindigger", enderMap = 1425, enderX = 26.9, enderY = 48.6, objective = "Seek out Rhapsody Shindigger in The Hinterlands.", summary = "Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.$b$bBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.$b$bFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.$b$bLast I heard, he's set up a brew camp to the east of here..." },
            { ids = { 1452 }, name = "Rhapsody's Kalimdor Kocktail", level = 43, zone = "The Hinterlands", giver = "Rhapsody Shindigger", giverMap = 1425, giverX = 26.9, giverY = 48.6, ender = "Rhapsody Shindigger", enderMap = 1425, enderX = 26.9, enderY = 48.6, objective = "Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.", summary = "Hiccup!$b$bSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!$b$bIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!$b$bTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.$b$bGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...$b$bA nice stiff Kalimdor Kocktail... that'll get me talking!" },
            { ids = { 1469 }, name = "Rhapsody's Tale", level = 43, zone = "The Hinterlands", giver = "Rhapsody Shindigger", giverMap = 1425, giverX = 26.9, giverY = 48.6, ender = "Brohann Caskbelly", enderMap = 1453, enderX = 69.5, enderY = 40.4, objective = "Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.", summary = "Before the flight, I drank me a whole keg of stout. Hiccup!$b$bAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!$b$bWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!" },
            { ids = { 1475 }, name = "Into The Temple of Atal'Hakkar", level = 50, zone = "Stormwind City", giver = "Brohann Caskbelly", giverMap = 1453, giverX = 69.5, giverY = 40.4, ender = "Brohann Caskbelly", enderMap = 1453, enderX = 69.5, enderY = 40.4, objective = "Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.", summary = "According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.$b$bNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, $n.$b$bAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory." },
        },
    },
    {
        id = "q3520",
        name = "The Prophecy of Mosh'aru",
        zone = "Tanaris",
        minLevel = 40,
        maxLevel = 58,
        importance = 3,
        kind = "raid",
        quests = {
            { ids = { 3520 }, name = "Screecher Spirits", level = 44, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", summary = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.$B$BTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.$B$BReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke." },
            { ids = { 3527 }, name = "The Prophecy of Mosh'aru", level = 47, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", summary = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.$B$BBring me the Mosh'aru tablets!$B$BThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.$B$BThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.$B$BWhen you have the tablets, bring them to me." },
            { ids = { 4787 }, name = "The Ancient Egg", level = 50, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Bring the Ancient Egg to Yeh'kinya in Tanaris.", summary = "The Prophecy of Mosh'aru speaks of an ancient egg.  It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar.  It may be the only way to keep our world safe from his evil.$B$BBring me the ancient egg, $N.  It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city." },
            { ids = { 3528 }, name = "The God Hakkar", level = 53, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", summary = "Now it is time to capture the essence of the avatar of Hakkar.$B$BTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.$B$BHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.$B$BDefeat him, and place his essence within the egg of Hakkar." },
            { ids = { 5065 }, name = "The Lost Tablets of Mosh'aru", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Prospector Ironboot", enderMap = 1446, enderX = 66.9, enderY = 24.0, objective = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", summary = "The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six!$B$BAnd I fear that we will not like what secrets the others hold..$B$BFind the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me." },
            { ids = { 4788 }, name = "The Final Tablets", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Prospector Ironboot", enderMap = 1446, enderX = 66.9, enderY = 24.0, objective = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", summary = "While I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth!  It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire.  The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge.$B$BGood luck, $N.  Blackrock Spire is no place for decent folk..." },
            { ids = { 8181 }, name = "Confront Yeh'kinya", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Speak with Yeh'kinya.", summary = "My delvings into the Mosh'aru Tablets bear grim news, $N.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray!$B$BGo to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!" },
            { ids = { 8182 }, name = "The Hand of Rastakhan", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Molthor", enderMap = 1434, enderX = 15.0, enderY = 15.1, objective = "Speak with Molthor in Stranglethorn.", summary = "$N, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth!$B$BThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar." },
        },
    },
    {
        id = "q4124",
        name = "Rise of the Silithid",
        zone = "Feralas",
        minLevel = 40,
        maxLevel = 46,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 4124 }, name = "The Missing Courier", level = 43, zone = "Feralas", giver = "Latronicus Moonspear", giverMap = 1444, giverX = 30.4, giverY = 46.2, ender = "Ginro Hearthkindle", enderMap = 1444, enderX = 31.9, enderY = 45.1, objective = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", summary = "An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.$B$BIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters." },
            { ids = { 4125 }, name = "The Missing Courier", level = 43, zone = "Feralas", giver = "Ginro Hearthkindle", giverMap = 1444, giverX = 31.9, giverY = 45.1, ender = "Wrecked Row Boat", enderMap = 1444, enderX = 45.4, enderY = 65.0, objective = "Locate the courier's boat somewhere along the coast of Feralas.", summary = "It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.$B$BI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know." },
            { ids = { 4127 }, name = "Boat Wreckage", level = 44, zone = "Feralas", giver = "Wrecked Row Boat", giverMap = 1444, giverX = 45.4, giverY = 65.0, ender = "Ginro Hearthkindle", enderMap = 1444, enderX = 31.9, enderY = 45.1, objective = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.", summary = "Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.$B$BYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water..." },
            { ids = { 4129 }, name = "The Knife Revealed", level = 44, zone = "Feralas", giver = "Ginro Hearthkindle", giverMap = 1444, giverX = 31.9, giverY = 45.1, ender = "Quintis Jonespyre", enderMap = 1444, enderX = 32.5, enderY = 43.8, objective = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.", summary = "The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.$B$BTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife." },
            { ids = { 4130 }, name = "Psychometric Reading", level = 44, zone = "Feralas", giver = "Quintis Jonespyre", giverMap = 1444, giverX = 32.5, giverY = 43.8, ender = "Ginro Hearthkindle", enderMap = 1444, enderX = 31.9, enderY = 45.1, objective = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", summary = "I'm a little wobbly still, sorry.  Anyway, I received some useful visions.$B$BRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.$B$BI need to rest, sorry $N.  Tell Gin what I've seen.  He needs to know." },
            { ids = { 4131 }, name = "The Woodpaw Gnolls", level = 44, zone = "Feralas", giver = "Ginro Hearthkindle", giverMap = 1444, giverX = 31.9, giverY = 45.1, ender = "Large Leather Backpacks", enderMap = 1444, enderX = 73.3, enderY = 56.3, objective = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.", summary = "Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.$B$BI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them." },
            { ids = { 4135 }, name = "The Writhing Deep", level = 46, zone = "Feralas", giver = "Large Leather Backpacks", giverMap = 1444, giverX = 73.3, giverY = 56.3, ender = "Zukk'ash Pod", enderMap = 1444, enderX = 72.1, enderY = 63.7, objective = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep.  According to the note, it is located to the south of the Woodpaw gnoll camps.", summary = "Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.$B$BThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".$B$BIt would seem that you have located where Raschal ultimately went." },
            { ids = { 4265 }, name = "Freed from the Hive", level = 46, zone = "Feralas", giver = "Zukk'ash Pod", giverMap = 1444, giverX = 72.1, giverY = 63.7, ender = "Ginro Hearthkindle", enderMap = 1444, enderX = 31.9, enderY = 45.1, objective = "Escort Raschal safely out of the Zukk'ash hive.$B$BReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.", summary = "The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.$B$B\"Thank Elune - you've saved me, friend! I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me. I could use a hand getting out of here; after that, would you let the Stronghold know that I am all right? I'll be fine - we just need to leave, and fast!\"" },
            { ids = { 4266 }, name = "A Hero's Welcome", level = 46, zone = "Feralas", giver = "Ginro Hearthkindle", giverMap = 1444, giverX = 31.9, giverY = 45.1, ender = "Shandris Feathermoon", enderMap = 1444, enderX = 30.3, enderY = 46.2, objective = "Speak with Shandris Feathermoon in Feathermoon Stronghold.", summary = "$N, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.$B$BGeneral Feathermoon is waiting for you in the main compound." },
            { ids = { 4267 }, name = "Rise of the Silithid", level = 46, zone = "Feralas", giver = "Shandris Feathermoon", giverMap = 1444, giverX = 30.3, giverY = 46.2, ender = "Gracina Spiritmight", enderMap = 1457, enderX = 41.8, enderY = 85.6, objective = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.", summary = "I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.$B$BYou're dismissed - good luck, $N; may Elune watch over us all." },
        },
    },
    {
        id = "q2278",
        name = "The Platinum Discs",
        zone = "Uldaman",
        minLevel = 40,
        maxLevel = 50,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 2278 }, name = "The Platinum Discs", level = 47, zone = "Uldaman", giver = "The Discs of Norgannon", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "The Discs of Norgannon", enderMap = 1418, enderX = 44.6, enderY = 12.1, enderInside = "Uldaman", objective = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.", summary = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.$B$B\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"$B$BYou have uncovered a wealth of previously undiscovered worldly lore!" },
            { ids = { 2279 }, name = "The Platinum Discs", level = 47, zone = "Uldaman", giver = "The Discs of Norgannon", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "High Explorer Magellas", enderMap = 1455, enderX = 69.9, enderY = 18.6, objective = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.", summary = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it." },
            { ids = { 2439 }, name = "The Platinum Discs", level = 47, zone = "Ironforge", giver = "High Explorer Magellas", giverMap = 1455, giverX = 69.9, giverY = 18.6, ender = "Dinita Stonemantle", enderMap = 1455, enderX = 33.9, enderY = 59.1, objective = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.", summary = "This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.$B$BAs for you, heroic $c, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!$B$BReturn to me directly when you are ready; there is much more to do for the Explorers' League!" },
            { ids = { 2963 }, name = "Portents of Uldum", level = 50, zone = "Ironforge", giver = "High Explorer Magellas", giverMap = 1455, giverX = 69.9, giverY = 18.6, ender = "Historian Karnik", enderMap = 1455, enderX = 77.5, enderY = 11.8, objective = "Speak with Historian Karnik in the Hall of Explorers within Ironforge.", summary = "Greetings once again, $n!  Your discovery inside Uldaman has set the Explorers' League abuzz with excitement.  The League has been working to unlock the secrets of the miniature platinum discs you found.  Your fortuitous arrival here in the Hall allows me to share with you that we are quite possibly on to something!$B$BHistorian Karnik has uncovered some important clues as to the true origins of the Valley of the Watchers in the Tanaris desert.  He would like to speak with you as soon as possible!" },
            { ids = { 2946 }, name = "Seeing What Happens", level = 50, zone = "Ironforge", giver = "Historian Karnik", giverMap = 1455, giverX = 77.5, giverY = 11.8, ender = "Uldum Pedestal", enderMap = 1446, enderX = 37.6, enderY = 81.4, objective = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", summary = "We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.$B$BThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.$B$BWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!" },
            { ids = { 2954 }, name = "The Stone Watcher", level = 50, zone = "Tanaris", giver = "Stone Watcher of Norgannon", giverMap = 1446, giverX = 37.6, giverY = 81.4, ender = "Uldum Pedestal", enderMap = 1446, enderX = 37.6, enderY = 81.4, objective = "Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.", summary = "\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"$B$BThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on." },
            { ids = { 2977 }, name = "Return to Ironforge", level = 50, zone = "Tanaris", giver = "Uldum Pedestal", giverMap = 1446, giverX = 37.6, giverY = 81.4, ender = "Historian Karnik", enderMap = 1455, enderX = 77.5, enderY = 11.8, objective = "Speak with Historian Karnik in Ironforge.", summary = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.$B$BWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery." },
            { ids = { 2964 }, name = "A Future Task", level = 50, zone = "Ironforge", giver = "Historian Karnik", giverMap = 1455, giverX = 77.5, giverY = 11.8, ender = "High Explorer Magellas", enderMap = 1455, enderX = 69.9, enderY = 18.6, objective = "Speak with High Explorer Magellas in Ironforge.", summary = "Well $n... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.$B$BThe High Explorer needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again aiding the League." },
        },
    },
    {
        id = "q3441",
        name = "A Taste of Flame",
        zone = "Searing Gorge",
        minLevel = 40,
        maxLevel = 58,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 3441 }, name = "Divine Retribution", level = 48, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Listen as Kalaran Windblade tells his story.", summary = "Hear my tale, adventurer." },
            { ids = { 3442 }, name = "The Flawless Flame", level = 48, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", summary = "You have made the right decision, $N.$B$BWe must strike where we will do the most damage: the four sentry towers.$B$BWith the four towers in flames, we can initiate an offensive before they have time to react.$B$BYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.$B$BBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.$B$BThe golems and elementals in these lands should be your first target." },
            { ids = { 3443 }, name = "Forging the Shaft", level = 48, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Bring 8 Thorium Plated Daggers to Kalaran Windblade.", summary = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.$B$BThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft." },
            { ids = { 3452 }, name = "The Flame's Casing", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Find and return a Symbol of Ragnaros to Kalaran Windblade.", summary = "We need one final piece to form the torch.$B$BIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing." },
            { ids = { 3453 }, name = "The Torch of Retribution", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Wait for Kalaran Windblade to complete the Torch of Retribution.", summary = "Give me a moment to combine the pieces and apply the necessary enchantments." },
            { ids = { 3454 }, name = "The Torch of Retribution", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Torch of Retribution", enderMap = 1427, enderX = 39.1, enderY = 39.1, objective = "Take the Torch of Retribution.", summary = "The torch must now be bound to its owner. Pick up the torch, $N. " },
            { ids = { 3462 }, name = "Squire Maltrake", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Squire Maltrake", enderMap = 1427, enderX = 39.2, enderY = 39, objective = "Speak with Squire Maltrake.", summary = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution." },
            { ids = { 3463 }, name = "Set Them Ablaze!", level = 52, zone = "Searing Gorge", giver = "Squire Maltrake", giverMap = 1427, giverX = 39.2, giverY = 39, ender = "Squire Maltrake", enderMap = 1427, enderX = 39.2, enderY = 39, objective = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings. ", summary = "Listen well, $N. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.$B$BWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.$B$BYou must enter each tower and use the Torch of Retribution within their fortifications. Beware the elite sentry units of the Dark Irons, $N." },
            { ids = { 3481 }, name = "Trinkets...", level = 50, zone = "Searing Gorge", giver = "Hoard of the Black Dragonflight", giverMap = 1427, giverX = 38.9, giverY = 39.0, ender = "Hoard of the Black Dragonflight", enderMap = 1427, enderX = 38.9, enderY = 39.0, objective = "Open the chest.", summary = "The chest appears locked." },
            { ids = { 4022 }, name = "A Taste of Flame", level = 54, zone = "Burning Steppes", giver = "Cyrus Therepentous", giverMap = 1428, giverX = 95.1, giverY = 31.6, ender = "Cyrus Therepentous", enderMap = 1428, enderX = 95.1, enderY = 31.6, objective = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.", summary = "The flight is aware of your work in the Searing Gorge.$B$BShow it to me, $r. The molt, imbecile." },
            { ids = { 4024 }, name = "A Taste of Flame", level = 58, zone = "Burning Steppes", giver = "Cyrus Therepentous", giverMap = 1428, giverX = 95.1, giverY = 31.6, ender = "Cyrus Therepentous", enderMap = 1428, enderX = 95.1, enderY = 31.6, objective = "Travel to Blackrock Depths and slay Bael'Gar.$B$BYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.$B$BReturn the Encased Fiery Essence to Cyrus Therepentous.", summary = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.$B$BBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.$B$BUse the molt on his remains to safely extract the inner flame.$B$BSucceed and be rewarded." },
        },
    },
    {
        id = "q2866",
        name = "The Ruins of Solarsal",
        zone = "Feralas",
        minLevel = 40,
        maxLevel = 45,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 2866 }, name = "The Ruins of Solarsal", level = 43, zone = "Feralas", giver = "Shandris Feathermoon", giverMap = 1444, giverX = 30.3, giverY = 46.2, ender = "Solarsal Gazebo", enderMap = 1444, enderX = 26.3, enderY = 52.3, objective = "Explore the Ruins of Solarsal and investigate the presence of the naga there.", summary = "To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.$B$BVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.$B$BGo there, explore the ruins, and look for anything that stands out to you. Good luck, $n." },
            { ids = { 2867 }, name = "Return to Feathermoon Stronghold", level = 43, zone = "Feralas", giver = "Solarsal Gazebo", giverMap = 1444, giverX = 26.3, giverY = 52.3, ender = "Shandris Feathermoon", enderMap = 1444, enderX = 30.3, enderY = 46.2, objective = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.", summary = "With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here." },
            { ids = { 3130 }, name = "Against the Hatecrest", level = 43, zone = "Feralas", giver = "Shandris Feathermoon", giverMap = 1444, giverX = 30.3, giverY = 46.2, ender = "Latronicus Moonspear", enderMap = 1444, enderX = 30.4, enderY = 46.2, objective = "Report to Latronicus Moonspear in Feathermoon Stronghold.", summary = "At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.$B$BAnyway, Latronicus awaits.  Good work thus far, $n.  Keep it up.$B$BYou're dismissed." },
            { ids = { 2869 }, name = "Against the Hatecrest", level = 43, zone = "Feralas", giver = "Latronicus Moonspear", giverMap = 1444, giverX = 30.4, giverY = 46.2, ender = "Latronicus Moonspear", enderMap = 1444, enderX = 30.4, enderY = 46.2, objective = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.", summary = "The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.$B$BBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage." },
            { ids = { 2870 }, name = "Against Lord Shalzaru", level = 45, zone = "Feralas", giver = "Latronicus Moonspear", giverMap = 1444, giverX = 30.4, giverY = 46.2, ender = "Latronicus Moonspear", enderMap = 1444, enderX = 30.4, enderY = 46.2, objective = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.", summary = "$n, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.$B$BSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.$B$BPut a stop to it by putting a stop to him, and bring me his relic so we can study it." },
            { ids = { 2871 }, name = "Delivering the Relic", level = 45, zone = "Feralas", giver = "Latronicus Moonspear", giverMap = 1444, giverX = 30.4, giverY = 46.2, ender = "Vestia Moonspear", enderMap = 1444, enderX = 30.1, enderY = 45.1, objective = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.", summary = "If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!$B$BShe's just around the bend, no doubt studying.  Thanks, $n." },
        },
    },
    {
        id = "q2988",
        name = "Nekrum's Medallion",
        zone = "The Hinterlands",
        minLevel = 40,
        maxLevel = 51,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 2988 }, name = "Witherbark Cages", level = 45, zone = "The Hinterlands", giver = "Gryphon Master Talonaxe", giverMap = 1425, giverX = 9.8, giverY = 44.5, ender = "Gryphon Master Talonaxe", enderMap = 1425, enderX = 9.8, enderY = 44.5, objective = "Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.", summary = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.$B$BYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there." },
            { ids = { 2989 }, name = "The Altar of Zul", level = 48, zone = "The Hinterlands", giver = "Gryphon Master Talonaxe", giverMap = 1425, giverX = 9.8, giverY = 44.5, ender = "Gryphon Master Talonaxe", enderMap = 1425, enderX = 9.8, enderY = 44.5, objective = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.", summary = "Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child. " },
            { ids = { 2990 }, name = "Thadius Grimshade", level = 47, zone = "The Hinterlands", giver = "Gryphon Master Talonaxe", giverMap = 1425, giverX = 9.8, giverY = 44.5, ender = "Thadius Grimshade", enderMap = 1419, enderX = 66.9, enderY = 19.5, objective = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.", summary = "Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!$B$BAnd perhaps his talents can help us find Sharpbeak.$B$BThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.$B$BGood luck, $N.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep." },
            { ids = { 2991 }, name = "Nekrum's Medallion", level = 47, zone = "Blasted Lands", giver = "Thadius Grimshade", giverMap = 1419, giverX = 66.9, giverY = 19.5, ender = "Thadius Grimshade", enderMap = 1419, enderX = 66.9, enderY = 19.5, objective = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", summary = "I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.$B$BZul'Farrak is across the ocean to the west, in the desert of Tanaris." },
            { ids = { 2992 }, name = "The Divination", level = 47, zone = "Blasted Lands", giver = "Thadius Grimshade", giverMap = 1419, giverX = 66.9, giverY = 19.5, ender = "Thadius Grimshade", enderMap = 1419, enderX = 66.9, enderY = 19.5, objective = "Wait until Grimshade performs the ritual of divination.", summary = "Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.$B$BThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes." },
            { ids = { 2993 }, name = "Return to the Hinterlands", level = 47, zone = "Blasted Lands", giver = "Thadius Grimshade", giverMap = 1419, giverX = 66.9, giverY = 19.5, ender = "Gryphon Master Talonaxe", enderMap = 1425, enderX = 9.8, enderY = 44.5, objective = "Speak with Gryphon Master Talonaxe.", summary = "Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.$B$BThere.  I have done my part.  I bid you fortune on your quest, $N." },
            { ids = { 2994 }, name = "Saving Sharpbeak", level = 51, zone = "The Hinterlands", giver = "Gryphon Master Talonaxe", giverMap = 1425, giverX = 9.8, giverY = 44.5, ender = "Gryphon Master Talonaxe", enderMap = 1425, enderX = 9.8, enderY = 44.5, objective = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.", summary = "We must save Sharpbeak!$B$BFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!" },
        },
    },
    {
        id = "q3367",
        name = "Rise, Obsidion!",
        zone = "Searing Gorge",
        minLevel = 40,
        maxLevel = 55,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 3367 }, name = "Suntara Stones", level = 48, zone = "Searing Gorge", giver = "Dorius Stonetender", giverMap = 1427, giverX = 63.9, giverY = 61.0, ender = "Singed Letter", enderMap = 1427, enderX = 74.5, enderY = 19.3, objective = "Help Dorius get back to Ironforge.", summary = "<Dorius groans.>$B$BI'm badly injured, $r. Feel... light headed... World spinning... Bleeding... internally.$B$BI must get back to Ironforge. Help me, $N." },
            { ids = { 3368 }, name = "Suntara Stones", level = 48, zone = "Searing Gorge", giver = "Singed Letter", giverMap = 1427, giverX = 74.5, giverY = 19.3, ender = "Curator Thorius", enderMap = 1455, enderX = 71.5, enderY = 15.7, objective = "Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers.", summary = "Brother,$B$BIf you are reading this letter, I am no more. How it got to you, I do not know, but thank and reward the ones responsible.$B$BAbout the stones: They exist and the Dark Irons have them in their possession. Their leader, Lathoric the Black, is using the power of the stones to enslave my excavation team. They were taken to the cauldron. Their minds are twisted, working night and day to complete something called Obsidion.$B$BHelp them, brother. It is the final wish of a dead man.$B$B-Dorius" },
            { ids = { 3371 }, name = "Dwarven Justice", level = 55, zone = "Ironforge", giver = "Curator Thorius", giverMap = 1455, giverX = 71.5, giverY = 15.7, ender = "Dying Archaeologist", enderMap = 1427, enderX = 41.1, enderY = 25.6, objective = "Return to the Searing Gorge and find Dorius's archaeology unit. ", summary = "There is an empty, vacuous hole, where my heart used to be, $N. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.$B$BReturn to the Searing Gorge and fulfill his last request: Free his men." },
            { ids = { 3372 }, name = "Release Them", level = 52, zone = "Searing Gorge", giver = "Dying Archaeologist", giverMap = 1427, giverX = 41.1, giverY = 25.6, ender = "Altar of Suntara", enderMap = 1427, enderX = 41.2, enderY = 25.4, objective = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge.", summary = "Release them, $r. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.$B$BThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.$B$B<The dying archaeologist collapses.>" },
            { ids = { 3566 }, name = "Rise, Obsidion!", level = 52, zone = "Searing Gorge", giver = "Dying Archaeologist", giverMap = 1427, giverX = 41.1, giverY = 25.6, ender = "Curator Thorius", enderMap = 1455, enderX = 71.5, enderY = 15.7, objective = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion. ", summary = "It... It... It was all a trap.$B$BForgive... me.$B$BKill the bastard... Kill him for us... for Thorius." },
        },
    },
    {
        id = "q7044",
        name = "Legends of Maraudon",
        zone = "Desolace",
        minLevel = 41,
        maxLevel = 49,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 7044 }, name = "Legends of Maraudon", level = 49, zone = "Desolace", giver = "Cavindra", giverMap = 1443, giverX = 31.9, giverY = 63.8, ender = "Celebras the Redeemed", enderMap = 1443, enderX = 29.1, enderY = 62.5, enderInside = "Maraudon", objective = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.$B$BFind a way to speak with Celebras.", summary = "A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.$B$BVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.$B$BYou must help him! Find the pieces, and speak to my brother... somehow." },
            { ids = { 7046 }, name = "The Scepter of Celebras", level = 49, zone = "Maraudon", giver = "Celebras the Redeemed", giverMap = 1443, giverX = 29.1, giverY = 62.5, giverInside = "Maraudon", ender = "Celebras the Redeemed", enderMap = 1443, enderX = 29.1, enderY = 62.5, enderInside = "Maraudon", objective = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.$B$BSpeak with him when the ritual is complete.", summary = "My scepter was once a source of hope for me. Its power allowed me the freedom to travel quickly through these caverns. I had hoped to bring peace to the spirit of my uncle... It is a task that I now pass to you.$B$BFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.$B$BTogether, we shall create the Scepter of Celebras once again!" },
        },
    },
    {
        id = "q2939",
        name = "In Search of Knowledge",
        zone = "Feralas",
        minLevel = 42,
        maxLevel = 50,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 2939 }, name = "In Search of Knowledge", level = 47, zone = "Feralas", giver = "Troyas Moonbreeze", giverMap = 1444, giverX = 31.8, giverY = 45.5, ender = "Daryn Lightwind", enderMap = 1438, enderX = 55.4, enderY = 92.2, objective = "Talk to Daryn Lightwind in Rut'theran Village.", summary = "While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.$B$BSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.$B$BI have a colleague in Darnassus that may be able to tell us what this is, $N. Why don't you go talk to her and see if she can help us?" },
            { ids = { 2940 }, name = "Feralas: A History", level = 47, zone = "Teldrassil", giver = "Feralas: A History", giverMap = 1438, giverX = 55.2, giverY = 91.5, ender = "Daryn Lightwind", enderMap = 1438, enderX = 55.4, enderY = 92.2, objective = "Ask Daryn Lightwind if you may borrow her book.", summary = "This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.$B$BYou pick it up, but realize you should probably ask before borrowing it." },
            { ids = { 2941 }, name = "The Borrower", level = 48, zone = "Teldrassil", giver = "Daryn Lightwind", giverMap = 1438, giverX = 55.4, giverY = 92.2, ender = "Curgle Cranklehop", enderMap = 1446, enderX = 52.4, enderY = 26.9, objective = "Take the letter to Curgle Cranklehop in Tanaris.", summary = "I have studied many subjects in my time, and my latest fascination is with the snapjaw that occupy the beach in the Hinterlands. There's one in particular I'd like to see, a giant snapjaw named Gammerita. I'd like to go myself, but my research keeps me here. I think a picture of her would be the next best thing.$B$BTake this letter to Curgle Cranklehop in Tanaris. She has created an invention for me that can capture a picture. She called it a \"snapshot,\" I think..." },
            { ids = { 2944 }, name = "The Super Snapper FX", level = 48, zone = "Tanaris", giver = "Curgle Cranklehop", giverMap = 1446, giverX = 52.4, giverY = 26.9, ender = "Daryn Lightwind", enderMap = 1438, enderX = 55.4, enderY = 92.2, objective = "Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village.", summary = "Have the first look at my new invention, $N. All you need to do is target whatever it is you'd like to take a picture of, and push the button.$B$BWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I'm sure Daryn will be quite pleased with the snapshot you return to her.$B$BIn any case, here's the Super Snapper. Have fun!" },
            { ids = { 2943 }, name = "Return to Troyas", level = 48, zone = "Teldrassil", giver = "Daryn Lightwind", giverMap = 1438, giverX = 55.4, giverY = 92.2, ender = "Troyas Moonbreeze", enderMap = 1444, enderX = 31.8, enderY = 45.5, objective = "Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold.", summary = "Here it is, $N. Please, take care of my book.$B$BNow, hurry along. I'm sure Troyas is eager for your return." },
            { ids = { 2879 }, name = "The Stave of Equinex", level = 50, zone = "Feralas", giver = "Troyas Moonbreeze", giverMap = 1444, giverX = 31.8, giverY = 45.5, ender = "Equinex Monolith", enderMap = 1444, enderX = 38.8, enderY = 13.2, objective = "Energize Troyas' Stave and find the Equinex Monolith.", summary = "This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.$B$BFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it." },
            { ids = { 2942 }, name = "The Morrow Stone", level = 50, zone = "Feralas", giver = "Equinex Monolith", giverMap = 1444, giverX = 38.8, giverY = 13.2, ender = "Troyas Moonbreeze", enderMap = 1444, enderX = 31.8, enderY = 45.5, objective = "Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold. ", summary = "The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade." },
        },
    },
    {
        id = "q2783",
        name = "The Demon Hunter",
        zone = "Blasted Lands",
        minLevel = 45,
        maxLevel = 60,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 2783 }, name = "Petty Squabbles", level = 57, zone = "Blasted Lands", giver = "Ambassador Ardalan", giverMap = 1419, giverX = 67.6, giverY = 19.3, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.", summary = "We fight the wrong enemy, $N.$B$BThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.$B$BDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.$B$BPut your differences aside, $N, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands." },
            { ids = { 2801 }, name = "A Tale of Sorrow", level = 57, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Listen to the Fallen Hero of the Horde tell his story.", summary = "Before we may continue, you must hear my story." },
            { ids = { 2681 }, name = "The Stones That Bind Us", level = 57, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.", summary = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.$B$BGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.$B$BFight hard and die with honor, $N." },
            { ids = { 2702 }, name = "Heroes of Old", level = 57, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Corporal Thund Splithoof", enderMap = 1435, enderX = 33.5, enderY = 66.0, objective = "Speak to Corporal Thund Splithoof.", summary = "You have honored me with your nobility and heroism, $N.$B$BYou have also honored them..." },
            { ids = { 2701 }, name = "Heroes of Old", level = 57, zone = "Swamp of Sorrows", giver = "Corporal Thund Splithoof", giverMap = 1435, giverX = 33.5, giverY = 66.0, ender = "Spectral Lockbox", enderMap = 1435, enderX = 33.3, enderY = 66.2, objective = "Open the chest and claim your reward.", summary = "Please, take from this a relic of old. We no longer have a use for the item.$B$BMay it serve you well in your fight against the legion." },
            { ids = { 2721 }, name = "Kirith", level = 58, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Spirit of Kirith", enderMap = 1419, enderX = 68.8, enderY = 31.1, objective = "Find out what became of Lieutenant Kirith.", summary = "As one chapter of your adventure closes, another one begins, $N.$B$BOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.$B$BAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith." },
            { ids = { 2743 }, name = "The Cover of Darkness", level = 60, zone = "Blasted Lands", giver = "Spirit of Kirith", giverMap = 1419, giverX = 68.8, giverY = 31.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Return to the Fallen Hero of the Horde with your findings.", summary = "Let us not mince words, $r; my time here is limited.$B$BYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.$B$B<Kirith grins.>$B$BYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.$B$BReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further." },
            { ids = { 2744 }, name = "The Demon Hunter", level = 60, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Speak with Loramus Thalipedes in Azshara.", summary = "The triad is protected by Razelikh.$B$BIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.$B$BThere is one who may be able to assist you further, $N. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands." },
            { ids = { 3141 }, name = "Loramus", level = 57, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Listen to Loramus Thalipedes tell his story.", summary = "So you wish to battle demons? You would do well to listen to my tale. " },
            { ids = { 3508 }, name = "Breaking the Ward", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Wait for Loramus to complete the enlightenment spell.", summary = "You are foolhardy, $N. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.$B$BTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.$B$BBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power." },
            { ids = { 3509 }, name = "The Name of the Beast", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Lord Arkkoroc", enderMap = 1447, enderX = 77.1, enderY = 42.8, objective = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.", summary = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.$B$BWhen such a weapon is forged, the demon and all under his command are vulnerable.$B$BA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.$B$BUndoubtedly, you will have to pay a price for such information. " },
            { ids = { 3510 }, name = "The Name of the Beast", level = 58, zone = "Azshara", giver = "Lord Arkkoroc", giverMap = 1447, giverX = 77.1, giverY = 42.8, ender = "Lord Arkkoroc", enderMap = 1447, enderX = 77.1, enderY = 42.8, objective = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.", summary = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.$B$BFor that, you will be given the name that you seek and something else of equal importance.$B$BShe roams the clutch... Hetaera she is called.$B$B<Lord Arkkoroc points to the southwest.>$B$BGo!" },
            { ids = { 3511 }, name = "The Name of the Beast", level = 58, zone = "Azshara", giver = "Lord Arkkoroc", giverMap = 1447, giverX = 77.1, giverY = 42.8, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Take the temper back to Loramus Thalipedes.", summary = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.$B$BThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.$B$B<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>$B$BTake the temper back to Loramus along with the name of the beast: Rakh'likh." },
            { ids = { 3602 }, name = "Azsharite", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.$B$BReturn to Loramus when the task is complete.", summary = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.$B$BThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.$B$BYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal." },
            { ids = { 3621 }, name = "The Formation of Felbane", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Galvan the Ancient", enderMap = 1434, enderX = 50.6, enderY = 20.5, objective = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.", summary = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.$B$BIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.$B$BMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal." },
            { ids = { 3625 }, name = "Enchanted Azsharite Fel Weaponry", level = 58, zone = "Stranglethorn Vale", giver = "Galvan the Ancient", giverMap = 1434, giverX = 50.6, giverY = 20.5, ender = "Galvan the Ancient", enderMap = 1434, enderX = 50.6, enderY = 20.5, objective = "Wait for Galvan to finish forging the weaponry.", summary = "$N, the creation of each weapon will take some time.$B$BAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!$B$BNow give me a moment to craft your weapon, $N." },
            { ids = { 3626 }, name = "Return to the Blasted Lands", level = 58, zone = "Stranglethorn Vale", giver = "Galvan the Ancient", giverMap = 1434, giverX = 50.6, giverY = 20.5, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Return to the Fallen Hero of the Horde.", summary = "The hour of redemption is near, $N. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective." },
            { ids = { 3627 }, name = "Uniting the Shattered Amulet", level = 60, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.$B$BRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...", summary = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.$B$BGo $N! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!" },
            { ids = { 3628 }, name = "You Are Rakh'likh, Demon", level = 60, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.", summary = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $N. Use it on the Altar of the Defiler.$B$BShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world." },
        },
    },
    {
        id = "q3844",
        name = "It's Dangerous to Go Alone",
        zone = "Un'Goro Crater",
        minLevel = 47,
        maxLevel = 56,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 3844 }, name = "It's a Secret to Everybody", level = 52, zone = "Un'Goro Crater", giver = "A Wrecked Raft", giverMap = 1449, giverX = 63.0, giverY = 68.6, ender = "A Small Pack", enderMap = 1449, enderX = 63.1, enderY = 69.1, objective = "Look around in the pond for a clue about who this wrecked raft may belong to.", summary = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.$B$BPerhaps a little exploration in the area might uncover more clues..." },
            { ids = { 3845 }, name = "It's a Secret to Everybody", level = 52, zone = "Un'Goro Crater", giver = "A Small Pack", giverMap = 1449, giverX = 63.1, giverY = 69.1, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Examine the items inside the pack and bring them to their owner.", summary = " Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.$B$BThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there." },
            { ids = { 3908 }, name = "It's a Secret to Everybody", level = 52, zone = "Un'Goro Crater", giver = "Linken", giverMap = 1449, giverX = 44.7, giverY = 8.1, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Take Linken's Sword to Donova Snowden in Winterspring.", summary = "You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...$B$BThese items you brought to me, though... I am remembering something.$B$BMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!$B$BAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there." },
            { ids = { 3909 }, name = "The Videre Elixir", level = 52, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", summary = "Now, what's this? Linken... FORGOT?$B$BOh, I see... Lost his memory...$B$BWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.$B$BListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas." },
            { ids = { 3912 }, name = "Meet at the Grave", level = 52, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Gaeriyan", enderMap = 1446, enderX = 53.9, enderY = 23.3, objective = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.", summary = "This elixir will allow you to speak with one that you would not normally even see...$B$BTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.$B$BIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.$B$BRemember, he will only speak to you in that form..." },
            { ids = { 3913 }, name = "A Grave Situation", level = 52, zone = "Tanaris", giver = "Gaeriyan", giverMap = 1446, giverX = 53.9, giverY = 23.3, ender = "A Conspicuous Gravestone", enderMap = 1446, enderX = 53.8, enderY = 29.1, objective = "Resurrect, then look for the gravestone that Gaeriyan told you to find.", summary = "If you return to the graveyard, $N, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.$B$BPush on the stone, and you will learn of these secrets..." },
            { ids = { 3914 }, name = "Linken's Sword", level = 52, zone = "Tanaris", giver = "A Conspicuous Gravestone", giverMap = 1446, giverX = 53.8, giverY = 29.1, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.", summary = "After a strong flash of light, you are able to pick up the sword again. It has been transformed!" },
            { ids = { 3941 }, name = "A Gnome's Assistance", level = 52, zone = "Un'Goro Crater", giver = "Linken", giverMap = 1449, giverX = 44.7, giverY = 8.1, ender = "J.D. Collie", enderMap = 1449, enderX = 41.9, enderY = 2.7, objective = "Find J.D. Collie in the cave at Marshal's Refuge.", summary = "Thinking... Thinking... I know I came here for something important...$B$BI have an idea, $N. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.$B$BWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!" },
            { ids = { 3942 }, name = "Linken's Memory", level = 54, zone = "Un'Goro Crater", giver = "J.D. Collie", giverMap = 1449, giverX = 41.9, giverY = 2.7, ender = "Eridan Bluewind", enderMap = 1448, enderX = 51.4, enderY = 81.5, objective = "Find Eridan Bluewind in southern Felwood.", summary = "Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.$B$BSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?$B$BI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?" },
            { ids = { 4084 }, name = "Silver Heart", level = 54, zone = "Felwood", giver = "Eridan Bluewind", giverMap = 1448, giverX = 51.4, giverY = 81.5, ender = "Eridan Bluewind", enderMap = 1448, enderX = 51.4, enderY = 81.5, objective = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", summary = "I do not know the one you speak of, $N.$B$BBut worry not; if your friend was on a journey to find me, I do know what it was he desired.$B$BIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...$B$BNone... except those with enough power to do so. I can teach you of this power, $N.$B$BFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return." },
            { ids = { 4005 }, name = "Aquementas", level = 54, zone = "Felwood", giver = "Eridan Bluewind", giverMap = 1448, giverX = 51.4, giverY = 81.5, ender = "J.D. Collie", enderMap = 1449, enderX = 41.9, enderY = 2.7, objective = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.$B$BUse the Book of Aquor to summon Aquementas.$B$BAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.", summary = "Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.$B$BThe eastmost peninsula is the secret...$B$BFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.$B$BAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items." },
            { ids = { 3961 }, name = "Linken's Adventure", level = 54, zone = "Un'Goro Crater", giver = "J.D. Collie", giverMap = 1449, giverX = 41.9, giverY = 2.7, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.", summary = "To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.$B$BBring the totem to him. See if that helps him remember why he came here." },
            { ids = { 3962 }, name = "It's Dangerous to Go Alone", level = 56, zone = "Un'Goro Crater", giver = "Linken", giverMap = 1449, giverX = 44.7, giverY = 8.1, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Travel to Fire Plume Ridge, south of Marshal's Refuge.$B$BFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.", summary = "$N, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.$B$BBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.$B$BBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.$B$BYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice." },
        },
    },
    {
        id = "q3763",
        name = "Morrowgrain Research",
        zone = "Darnassus",
        minLevel = 47,
        maxLevel = 50,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 3763 }, name = "Assisting Arch Druid Staghelm", level = 50, zone = "Darnassus", giver = "Innkeeper Saelienne", giverMap = 1457, giverX = 67.4, giverY = 15.7, ender = "Arch Druid Fandral Staghelm", enderMap = 1457, enderX = 34.8, enderY = 9.3, objective = "Speak with Arch Druid Fandral Staghelm in Darnassus.", summary = "Excuse me $c, but I'd like just a moment of your time if possible.$B$BThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.$B$BPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper." },
            { ids = { 3764 }, name = "Un'Goro Soil", level = 50, zone = "Darnassus", giver = "Arch Druid Fandral Staghelm", giverMap = 1457, giverX = 34.8, giverY = 9.3, ender = "Jenal", enderMap = 1457, enderX = 31.5, enderY = 8.2, objective = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.", summary = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.$B$BYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I." },
            { ids = { 3781 }, name = "Morrowgrain Research", level = 50, zone = "Darnassus", giver = "Arch Druid Fandral Staghelm", giverMap = 1457, giverX = 34.8, giverY = 9.3, ender = "Mathrengyl Bearwalker", enderMap = 1457, enderX = 35.4, enderY = 8.4, objective = "Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", summary = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery.$B$BTake this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him." },
            { ids = { 3787 }, name = "Jonespyre's Request", level = 50, zone = "Stormwind City", giver = "Tannysa", giverMap = 1453, giverX = 54.3, giverY = 84.1, ender = "Quintis Jonespyre", enderMap = 1444, enderX = 32.5, enderY = 43.8, objective = "Speak with Quintis Jonespyre in Feathermoon Stronghold.", summary = "Excuse me, friend...$B$BA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.$B$BIf you're interested, speak with him; no doubt, all will be revealed once you do." },
            { ids = { 3791 }, name = "The Mystery of Morrowgrain", level = 50, zone = "Feralas", giver = "Quintis Jonespyre", giverMap = 1444, giverX = 32.5, giverY = 43.8, ender = "Quintis Jonespyre", enderMap = 1444, enderX = 32.5, enderY = 43.8, objective = "Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.", summary = "Let me to be frank with you, $N.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.$B$BI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you." },
        },
    },
    {
        id = "q4182",
        name = "A Shred of Hope",
        zone = "Burning Steppes",
        minLevel = 48,
        maxLevel = 60,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 4182 }, name = "Dragonkin Menace", level = 54, zone = "Burning Steppes", giver = "Helendis Riverhorn", giverMap = 1428, giverX = 85.8, giverY = 69.0, ender = "Helendis Riverhorn", enderMap = 1428, enderX = 85.8, enderY = 69.0, objective = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", summary = "Life in the Burning Steppes is rife with conflict.$B$BJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.$B$BEnough lamenting! We have a problem, $N. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things." },
            { ids = { 4183 }, name = "The True Masters", level = 54, zone = "Burning Steppes", giver = "Helendis Riverhorn", giverMap = 1428, giverX = 85.8, giverY = 69.0, ender = "Magistrate Solomon", enderMap = 1433, enderX = 24.9, enderY = 44.5, objective = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon. ", summary = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.$B$BIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.$B$BTake this letter to Magistrate Solomon. He will know what must be done.$B$B<Helendis hands you a sealed letter.>" },
            { ids = { 4184 }, name = "The True Masters", level = 54, zone = "Redridge Mountains", giver = "Magistrate Solomon", giverMap = 1433, giverX = 24.9, giverY = 44.5, ender = "Highlord Bolvar Fordragon", enderMap = 1453, enderX = 80.2, enderY = 38.3, objective = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.$B$BBolvar resides in Stormwind Keep. ", summary = "This is grim news, $N. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?$B$BYou must take this information to Highlord Bolvar Fordragon in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost." },
            { ids = { 4185 }, name = "The True Masters", level = 54, zone = "Stormwind City", giver = "Highlord Bolvar Fordragon", giverMap = 1453, giverX = 80.2, giverY = 38.3, ender = "Highlord Bolvar Fordragon", enderMap = 1453, enderX = 80.2, enderY = 38.3, objective = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", summary = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.$B$BSpeak with Lady Prestor, $N. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation." },
            { ids = { 4186 }, name = "The True Masters", level = 54, zone = "Stormwind City", giver = "Highlord Bolvar Fordragon", giverMap = 1453, giverX = 80.2, giverY = 38.3, ender = "Magistrate Solomon", enderMap = 1433, enderX = 24.9, enderY = 44.5, objective = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.", summary = "I am going to empower you as an acting deputy of Stormwind, $N.$B$BReturn to Magistrate Solomon in Lakeshire and deliver this decree." },
            { ids = { 4223 }, name = "The True Masters", level = 54, zone = "Redridge Mountains", giver = "Magistrate Solomon", giverMap = 1433, giverX = 24.9, giverY = 44.5, ender = "Marshal Maxwell", enderMap = 1428, enderX = 84.7, enderY = 69.0, objective = "Speak with Marshal Maxwell in the Burning Steppes.", summary = "<Magistrate Solomon sighs.>$B$BYou must return to the Burning Steppes, $N. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck." },
            { ids = { 4224 }, name = "The True Masters", level = 54, zone = "Burning Steppes", giver = "Marshal Maxwell", giverMap = 1428, giverX = 84.7, giverY = 69.0, ender = "Marshal Maxwell", enderMap = 1428, enderX = 84.7, enderY = 69.0, objective = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.$B$BYou recall Marshal Maxwell telling you to search for him in a cave to the north.", summary = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?$B$BWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.$B$BWhat we need is that documentation. Speak with Ragged John, $N. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north." },
            { ids = { 4241 }, name = "Marshal Windsor", level = 54, zone = "Burning Steppes", giver = "Marshal Maxwell", giverMap = 1428, giverX = 84.7, giverY = 69.0, ender = "Marshal Windsor", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.$B$BYou recall Ragged John talking about Windsor being dragged off to a prison.", summary = "So that good for nothing coward says that Windsor is alive, eh?$B$BSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.$B$B<Maxwell laughs.>$B$BI bet you are getting tired of hearing that, aren't you?" },
            { ids = { 4242 }, name = "Abandoned Hope", level = 54, zone = "Blackrock Depths", giver = "Marshal Windsor", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Marshal Maxwell", enderMap = 1428, enderX = 84.7, enderY = 69.0, objective = "Give Marshal Maxwell the bad news.", summary = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.$B$BHe is a blind buffoon. Proof stands two feet away from him and he does not see.$B$BAs for my data, it's lost. Gone. Unrecoverable.$B$BShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.$B$BLeave me, $N." },
            { ids = { 4264 }, name = "A Crumpled Up Note", level = 58, zone = "Blackrock Depths", ender = "Marshal Windsor", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", summary = "The note has stains covering its surface. The text is barely legible, but you make out the following:$B$B...sweet irony...$B$B...the fall of the broken Alliance...$B$B...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...$B$B...Argelmach is almost done with the decryption of Windsor's notes.$B$BOur lord will rise from the depths and crush any that remain...$B$B-Emperor Dagran Thaurissan." },
            { ids = { 4282 }, name = "A Shred of Hope", level = 58, zone = "Blackrock Depths", giver = "Marshal Windsor", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Marshal Windsor", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Return Marshal Windsor's Lost Information.$B$BMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", summary = "<Marshal Windsor shakes the note excitedly.>$B$BDo you realize what this means, $N?$B$BPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.$B$BI hope you are ready to battle.$B$BVenture forth and find these two villains! Destroy them and return my lost information." },
            { ids = { 4322 }, name = "Jail Break!", level = 58, zone = "Blackrock Depths", giver = "Marshal Windsor", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Marshal Maxwell", enderMap = 1428, enderX = 84.7, enderY = 69.0, objective = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", summary = "We need to get out of here, $N. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction." },
            { ids = { 6402 }, name = "Stormwind Rendezvous", level = 60, zone = "Burning Steppes", giver = "Marshal Maxwell", giverMap = 1428, giverX = 84.7, giverY = 69.0, ender = "Reginald Windsor", enderMap = 1453, enderX = 73.6, enderY = 91.1, objective = "Travel to Stormwind City and venture to the city gates. Marshal Windsor will meet you just inside the city borders.", summary = "You are to meet with Windsor at the gates of Stormwind.$B$BWhat Windsor is about to unveil will shake the very foundation of the kingdom!$B$BDo not attempt to venture there alone, $N. You must amass an army! Gather your compatriots. To arms! " },
            { ids = { 6403 }, name = "The Great Masquerade", level = 60, zone = "Stormwind City", giver = "Reginald Windsor", giverMap = 1453, giverX = 73.6, giverY = 91.1, ender = "Highlord Bolvar Fordragon", enderMap = 1453, enderX = 80.2, enderY = 38.3, objective = "Follow Reginald Windsor through Stormwind. Protect him from harm!", summary = "It has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...$B$BAs you have no doubt ascertained by now, Lady Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.$B$BFor too long she has held our kingdom in her captivating gaze. Even the Highlord is controlled by her trickery - a puppet. It all ends today... The spell will be broken.$B$BWorry not, for together, we shall be victorious!$B$BAre you ready?" },
            { ids = { 6501 }, name = "The Dragon's Eye", level = 60, zone = "Stormwind City", giver = "Highlord Bolvar Fordragon", giverMap = 1453, giverX = 80.2, giverY = 38.3, ender = "Haleh", enderMap = 1452, enderX = 54.5, enderY = 51.2, objective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.", summary = "A fragment of the shattered medallion is all that I can offer.$B$BYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, $N.$B$BWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck." },
            { ids = { 6502 }, name = "Drakefire Amulet", level = 60, zone = "Winterspring", giver = "Haleh", giverMap = 1452, giverX = 54.5, giverY = 51.2, ender = "Haleh", enderMap = 1452, enderX = 54.5, enderY = 51.2, objective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", summary = "It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless.$B$BIt is possible to repair the item, but to do so would require the blood of a black dragon champion. There is one... He is known as General Drakkisath, ruler of the dragonspawn armies of Nefarian. Perhaps you have heard of him?$B$BReturn with his blood, $r, and I shall enchant the fragment into something that will grant you access to Onyxia's lair." },
            { ids = { 7495 }, name = "Victory for the Alliance", level = 60, zone = "Stormwind City", ender = "Highlord Bolvar Fordragon", enderMap = 1453, enderX = 80.2, enderY = 38.3, objective = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind.", summary = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Highlord." },
            { ids = { 7496 }, name = "Celebrating Good Times", level = 60, zone = "Stormwind City", giver = "Highlord Bolvar Fordragon", giverMap = 1453, giverX = 80.2, giverY = 38.3, ender = "Major Mattingly", enderMap = 1453, enderX = 67.2, enderY = 85.5, objective = "Seek out Major Mattingly in the Valley of Heroes.", summary = "Seek out Major Mattingly in the Valley of Heroes, $N. He will be expecting you..." },
        },
    },
    {
        id = "q5155",
        name = "A Final Blow",
        zone = "Felwood",
        minLevel = 48,
        maxLevel = 58,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 5155 }, name = "Forces of Jaedenar", level = 51, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.", summary = "If I am to trust you in this matter, you will first have to prove yourself.$B$BI must know that you are an enemy of the Shadow Council--the ones responsible for many evils here and abroad.$B$BTravel deeper into Felwood. To the west you will see a path leading to Jaedenar. It is there that the Council plots with the Burning Legion.$B$BEnter the depths of one of the corrupted Barrow Dens they inhabit and slay their kind. Return to me after you've done this. Then I will know you truly seek to help us." },
            { ids = { 5157 }, name = "Collection of the Corrupt Water", level = 52, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.", summary = "Deep within Jaedenar lies Shadow Hold--the main fortress of their corruption and evil.$B$BThe Shadow Council has protective spells surrounding their lair in the form of braziers. If I am to find out any more information about our enemy through scrying, then those braziers must be extinguished. By doing so, I should be able to spy on the Council and find out who leads them.$B$BIf you can, take this canteen and fill it at the Moon Well in the center of Jaedenar. Return to me afterwards." },
            { ids = { 5158 }, name = "Seeking Spiritual Aid", level = 52, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Islen Waterseer", enderMap = 1413, enderX = 65.8, enderY = 43.8, objective = "Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens.", summary = "Take the corrupt water to the Barrens, $N. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task.$B$BYou should find her at a small camp right along the water's edge. And, $N, ignore the pirates... they are but a nuisance and no threat to you." },
            { ids = { 5159 }, name = "Cleansed Water Returns to Felwood", level = 54, zone = "The Barrens", giver = "Islen Waterseer", giverMap = 1413, giverX = 65.8, giverY = 43.8, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Take the Purified Moon Well Water to Greta Mosshoof in Felwood.", summary = "Thank the spirits, $N. They are the ones that have come to your aid, not me.$B$BI give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out.$B$BThe Shadow Council is not a force to be trifled with, $N. Remember that.$B$BGo now. Take the water and return to Greta." },
            { ids = { 5165 }, name = "Dousing the Flames of Protection", level = 55, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.", summary = "Now, you must return to Jaedenar. The braziers are more than likely spread throughout Shadow Hold. Douse each of their flames and the protections the Council has set up will fall for at least a short period of time. I will be waiting for that to happen. When it does, I will look deep within the Hold and try to find out who the head of this beast is. Then, and only then, will we see about attacking them directly." },
            { ids = { 5242 }, name = "A Final Blow", level = 58, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.", summary = "Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside. The straight path down to the bottom is the only way... and I also know who you should seek out. His name is Fel'dan... Shadow Lord Fel'dan. He is the mortal in power down below... he is the head of the serpent. Kill him and his two succubus servants and return to me. Fel'dan is the one making pacts with the Legion. He must be stopped." },
        },
    },
    {
        id = "q4262",
        name = "Incendius!",
        zone = "Burning Steppes",
        minLevel = 48,
        maxLevel = 56,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 4262 }, name = "Overmaster Pyron", level = 52, zone = "Burning Steppes", giver = "Jalinda Sprig", giverMap = 1428, giverX = 85.4, giverY = 70.1, ender = "Jalinda Sprig", enderMap = 1428, enderX = 85.4, enderY = 70.1, objective = "Slay Overmaster Pyron and return to Jalinda Sprig.$B$BYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", summary = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.$B$B<Jalinda picks up some ashes from the ground and releases them into the air.>$B$BOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!$B$BHe guards the entrance at the Blackrock Quarry." },
            { ids = { 4263 }, name = "Incendius!", level = 56, zone = "Burning Steppes", giver = "Jalinda Sprig", giverMap = 1428, giverX = 85.4, giverY = 70.1, ender = "Jalinda Sprig", enderMap = 1428, enderX = 85.4, enderY = 70.1, objective = "Find Lord Incendius in Blackrock Depths and destroy him!", summary = "Are you sure Pyron said 'Incendius' when he died?$B$B<Jalinda swallows hard.>$B$BLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?$B$BDo you think you can handle another mission? I don't have anybody else to send, $N!$B$BWe will never get a team in if Incendius continues to raise Pyron from the ashes.$B$BYou'll have to find and destroy Lord Incendius!" },
        },
    },
    {
        id = "q3373",
        name = "The Essence of Eranikus",
        zone = "Sunken Temple",
        minLevel = 48,
        maxLevel = 55,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 3373 }, name = "The Essence of Eranikus", level = 55, zone = "Sunken Temple", ender = "Essence Font", enderMap = 1435, enderX = 69.9, enderY = 53.5, enderInside = "The Temple of Atal'Hakkar", objective = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", summary = "As you touch the gem, a deep voice resonates in your mind.$B$B\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"" },
            { ids = { 3374 }, name = "The Essence of Eranikus", level = 55, zone = "Swamp of Sorrows", ender = "Itharius", enderMap = 1435, enderX = 13.7, enderY = 71.7, objective = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows.  It is there that you will make your choice to aid Ysera's Dragonflight or not.", summary = "You engage the Oathstone, and Itharius speaks directly to your mind through the stone.$B$B\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"$B$B\"Do this $N, and we will work together to redeem a soul worthy of redemption.\"" },
            { ids = { 3512 }, name = "In Eranikus' Own Words", level = 55, zone = "Swamp of Sorrows", giver = "Itharius", giverMap = 1435, giverX = 13.7, giverY = 71.7, ender = "Umbranse the Spiritspeaker", enderMap = 1452, enderX = 67.8, enderY = 27.4, objective = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.", summary = "$N, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.$B$BTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still." },
        },
    },
    {
        id = "q5202",
        name = "Retribution of the Light",
        zone = "Felwood",
        minLevel = 49,
        maxLevel = 57,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 5202 }, name = "A Strange Red Key", level = 55, zone = "Felwood", ender = "Captured Arko'narin", enderMap = 1448, enderX = 36.2, enderY = 55.5, objective = "Search through Jaedenar to discover what the Blood Red Key is used for.", summary = "The small red key seems to be made of some kind of bone material. It is heavy in your hand, but appears very fragile. Why would a member of the Shadow Council have such a thing? Perhaps there is something within Jaedenar that this strange key unlocks." },
            { ids = { 5203 }, name = "Rescue From Jaedenar", level = 55, zone = "Felwood", giver = "Captured Arko'narin", giverMap = 1448, giverX = 36.2, giverY = 55.5, ender = "Jessir Moonbow", enderMap = 1448, enderX = 51.4, enderY = 82.0, objective = "Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends.", summary = "But, as much as it pains me, there is one thing that must be done first: I have to find Trey's sword Lightforge and escape Shadow Hold to tell my superiors what's happening here. Can you help me, $N?$B$BOur equipment isn't far from here, and you've already proven you can survive the path to the top.$B$BAfter we escape, I'll head to Darnassus if you can find my friend Jessir near the Ashenvale border. She was to meet us at the Emerald Circle's camp near there.$B$BWhat do you say, $N? Can you help me again?" },
            { ids = { 5204 }, name = "Retribution of the Light", level = 57, zone = "Felwood", giver = "Jessir Moonbow", giverMap = 1448, giverX = 51.4, giverY = 82.0, ender = "Remains of Trey Lightforge", enderMap = 1448, enderX = 38.5, enderY = 50.4, objective = "Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge.", summary = "She would like to pretend that she's fine. She'd love for me to think that she's strong enough to deal with all of this on her own, but I know better than that. Trey's death and hearing the torture he was put through is going to haunt her for a long time, and there's nothing we can do to stop that. But we can give her some peace!$B$B$N, return to Shadow Hold, kill Trey's torturer and find his remains. There is no reason we can't tie off all these loose ends while Arko'narin mourns in her own private way." },
            { ids = { 5385 }, name = "The Remains of Trey Lightforge", level = 57, zone = "Felwood", giver = "Remains of Trey Lightforge", giverMap = 1448, giverX = 38.5, giverY = 50.4, ender = "Jessir Moonbow", enderMap = 1448, enderX = 51.4, enderY = 82.0, objective = "Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood.", summary = "You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends." },
        },
    },
    {
        id = "q3702",
        name = "The Fate of the Kingdom",
        zone = "Ironforge",
        minLevel = 50,
        maxLevel = 59,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 3702 }, name = "The Smoldering Ruins of Thaurissan", level = 54, zone = "Ironforge", giver = "Royal Historian Archesonus", giverMap = 1455, giverX = 38.4, giverY = 55.3, ender = "Royal Historian Archesonus", enderMap = 1455, enderX = 38.4, enderY = 55.3, objective = "Listen to Royal Historian Archesonus recant the history of Thaurissan.", summary = "Would you like to hear a brief history of the Dark Iron dwarves?" },
            { ids = { 3701 }, name = "The Smoldering Ruins of Thaurissan", level = 54, zone = "Ironforge", giver = "Royal Historian Archesonus", giverMap = 1455, giverX = 38.4, giverY = 55.3, ender = "Royal Historian Archesonus", enderMap = 1455, enderX = 38.4, enderY = 55.3, objective = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", summary = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.$B$BIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, $N. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected." },
            { ids = { 4341 }, name = "Kharan Mighthammer", level = 59, zone = "Ironforge", giver = "King Magni Bronzebeard", giverMap = 1455, giverX = 39.1, giverY = 56.2, ender = "Kharan Mighthammer", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Travel to Blackrock Depths and find Kharan Mighthammer.$B$BThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", summary = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!$B$B<The King sobs.>$B$BAnd now she's gone, $N!$B$BI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!$B$BKharan is supposedly being held prisoner there... find him! I want answers!" },
            { ids = { 4342 }, name = "Kharan's Tale", level = 59, zone = "Blackrock Depths", giver = "Kharan Mighthammer", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Kharan Mighthammer", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Listen as Kharan Mighthammer tells his story.", summary = "Please, hear me out before passing judgement!" },
            { ids = { 4361 }, name = "The Bearer of Bad News", level = 59, zone = "Blackrock Depths", giver = "Kharan Mighthammer", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "King Magni Bronzebeard", enderMap = 1455, enderX = 39.1, enderY = 56.2, objective = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", summary = "You must take this information back to King Magni, $N. He will know what to do!" },
            { ids = { 4362 }, name = "The Fate of the Kingdom", level = 59, zone = "Ironforge", giver = "King Magni Bronzebeard", giverMap = 1455, giverX = 39.1, giverY = 56.2, ender = "Princess Moira Bronzebeard", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", summary = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.$B$BYou may be my last hope, $N. You must rescue my dear daughter, Moira!$B$BThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.$B$BAnd $N, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!" },
            { ids = { 4363 }, name = "The Princess's Surprise", level = 59, zone = "Blackrock Depths", giver = "Princess Moira Bronzebeard", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "King Magni Bronzebeard", enderMap = 1455, enderX = 39.1, enderY = 56.2, objective = "Return to Ironforge and speak with King Magni Bronzebeard.", summary = "Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!$B$B<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>$B$BReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.$B$BWhether he approves or not, it shall be." },
        },
    },
    {
        id = "q5066",
        name = "The Scourge Cauldrons",
        zone = "Stormwind City",
        minLevel = 50,
        maxLevel = 58,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 5066 }, name = "A Call to Arms: The Plaguelands!", level = 50, zone = "Stormwind City", giver = "Crier Goodman", giverMap = 1453, giverX = 56.4, giverY = 74.1, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0, objective = "Seek out Commander Ashlam Valorfist.  His base camp is located at Chillwind Camp, north of the Alterac Mountains.", summary = "Hear ye, hear ye!  All heroes are called upon to heed these words!$B$BA call to arms has been issued by the Kingdom of Stormwind!  All able bodied individuals are entreated to take up arms against the dark threat of the Scourge in the northern lands of the Eastern Kingdoms!  Rumors fly of new threats rising from the ruins of the Plaguelands!$B$BHeroes of the realm - seek out Commander Ashlam Valorfist who has set up his base camp in Chillwind Camp, north of the Alterac Mountains!" },
            { ids = { 5092 }, name = "Clear the Way", level = 52, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0, objective = "Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.$B$BReturn to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", summary = "With Andorhal's western and northern roads into the city well fortified, I'm looking to strike at it from the less defended eastern road.  The Scourge relies on the buffer of undead that infests Sorrow Hill as a first line of defense.  If we are to advance on Andorhal, we will need to do it through Sorrow Hill.$B$BYour first assignment will be to clear the way through Sorrow Hill.  Thin out the skeletons and ghouls that haunt the area; report back to me when this is done!" },
            { ids = { 5215 }, name = "The Scourge Cauldrons", level = 53, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "High Priestess MacDonnell", enderMap = 1422, enderX = 43.0, enderY = 84.5, objective = "Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands.", summary = "Within the lands of former Lordaeron are eight cauldrons - four here in the west, and four more ensconced in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.$B$BThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, High Priestess MacDonnell, will be your point on this assignment; she'll continue the briefing from here." },
            { ids = { 5216 }, name = "Target: Felstone Field", level = 53, zone = "Western Plaguelands", giver = "High Priestess MacDonnell", giverMap = 1422, giverX = 43.0, giverY = 84.5, ender = "Scourge Cauldron", enderMap = 1422, enderX = 37.2, enderY = 56.8, objective = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "Of the four cauldrons here in the west, the one located at Felstone Field may be the easiest one in obtaining access to.  The Scourge have greener troops positioned here, though they should not be underestimated.$B$BGo to Felstone Field, northwest of Andorhal, and engage the cauldron lord there.  We think it has a key that will unlock access to the cauldron.  When unlocked, use this bottle to obtain a sample of the poisons inside the cauldron; we'll need it for study in developing a counter agent." },
            { ids = { 5217, 5220, 5223, 5226 }, name = "Return to Chillwind Camp", level = 53, zone = "Western Plaguelands", giver = "Scourge Cauldron", giverMap = 1422, giverX = 37.2, giverY = 56.8, ender = "High Priestess MacDonnell", enderMap = 1422, enderX = 43.0, enderY = 84.5, objective = "Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands.", summary = "You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.$B$BWith the poison in hand, it is time to return to High Priestess MacDonnell at Chillwind Camp to complete the mission." },
            { ids = { 5219 }, name = "Target: Dalson's Tears", level = 55, zone = "Western Plaguelands", giver = "High Priestess MacDonnell", giverMap = 1422, giverX = 43.0, giverY = 84.5, ender = "Scourge Cauldron", enderMap = 1422, enderX = 46.2, enderY = 51.9, objective = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  Well, we shall shed no tears this day as we thwart the Scourge and have them choke on their own fumes!$B$BGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you into the cauldron.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses." },
            { ids = { 5222 }, name = "Target: Writhing Haunt", level = 55, zone = "Western Plaguelands", giver = "High Priestess MacDonnell", giverMap = 1422, giverX = 43.0, giverY = 84.5, ender = "Scourge Cauldron", enderMap = 1422, enderX = 53.0, enderY = 65.6, objective = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "Two cauldrons have been successfully opened; while you will be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!$B$BThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.$B$BGood hunting, $N!" },
            { ids = { 5225 }, name = "Target: Gahrron's Withering", level = 58, zone = "Western Plaguelands", giver = "High Priestess MacDonnell", giverMap = 1422, giverX = 43.0, giverY = 84.5, ender = "Scourge Cauldron", enderMap = 1422, enderX = 62.5, enderY = 58.5, objective = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N.$B$BGahrron's Withering is due northeast of our position here, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the Light protect you in this dangerous mission, $c." },
            { ids = { 5237 }, name = "Mission Accomplished!", level = 58, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0 },
        },
    },
    {
        id = "q8415",
        name = "Forging the Mightstone",
        zone = "Stormwind City",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        races = { 1, 3 },
        classes = { 2 },
        quests = {
            { ids = { 8415 }, name = "Chillwind Point", level = 52, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0, objective = "Speak to Commander Ashlam Valorfist at Chillwind Point.", summary = "Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, $n.  You can find him at Chillwind Point in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!" },
            { ids = { 8414 }, name = "Dispelling Evil", level = 52, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "High Priest Thel'danis", enderMap = 1422, enderX = 52.0, enderY = 83.3, objective = "Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.", summary = "Greetings, $c.  Crusaders like you are a welcome sight in these desolate reaches.$b$bYour holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here.$b$bOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already." },
            { ids = { 8416 }, name = "Inert Scourgestones", level = 52, zone = "Western Plaguelands", giver = "High Priest Thel'danis", giverMap = 1422, giverX = 52.0, giverY = 83.3, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0, objective = "Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point.", summary = "The evil has been purged from the stones, $n.$b$bI am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire." },
            { ids = { 8418 }, name = "Forging the Mightstone", level = 52, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0, objective = "Bring the voodoo feathers to Ashlam Valorfist.", summary = "Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, $n.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.$b$bIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil." },
        },
    },
    {
        id = "q5601",
        name = "The Battle of Darrowshire",
        zone = "Winterspring",
        minLevel = 50,
        maxLevel = 60,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 5601 }, name = "Sister Pamela", level = 55, zone = "Winterspring", giver = "Jessica Redpath", giverMap = 1452, giverX = 61.3, giverY = 39.0, ender = "Pamela Redpath", enderMap = 1423, enderX = 31.1, enderY = 78.0, objective = "Find Pamela Redpath in Darrowshire.", summary = "I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.$B$BDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.$B$BPlease, find her for me!" },
            { ids = { 5149 }, name = "Pamela's Doll", level = 55, zone = "Eastern Plaguelands", giver = "Pamela Redpath", giverMap = 1423, giverX = 31.1, giverY = 78.0, ender = "Pamela Redpath", enderMap = 1423, enderX = 31.1, enderY = 78.0, objective = "Find Pamela's doll.", summary = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!$B$BBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!$B$BAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.$B$BWill you find my doll for me?" },
            { ids = { 5152 }, name = "Auntie Marlene", level = 56, zone = "Eastern Plaguelands", giver = "Pamela Redpath", giverMap = 1423, giverX = 31.1, giverY = 78.0, ender = "Marlene Redpath", enderMap = 1422, enderX = 49.2, enderY = 78.6, objective = "Speak with Marlene, south of the Ruins of Andorhal.", summary = "Oh, I'm so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him?$B$BMaybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill.$B$BPlease, $N.  You're my new friend!  Will you talk to my Auntie for me?" },
            { ids = { 5153 }, name = "A Strange Historian", level = 56, zone = "Western Plaguelands", giver = "Marlene Redpath", giverMap = 1422, giverX = 49.2, giverY = 78.6, ender = "Chromie", enderMap = 1422, enderX = 39.5, enderY = 66.8, objective = "Bring Joseph's Wedding Ring to Chromie.", summary = "I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.  Oh, he is doomed!$B$BBut perhaps we can change his fate.$B$BSearch the graves outside for Joseph's monument.  His body's not there, for it was trampled and destroyed years ago, but under the monument is his wedding ring.  Take that ring to Chromie... a strange gnome with very strange powers.$B$BChromie is staying in the ruined inn at the northwest corner of Andorhal." },
            { ids = { 5154 }, name = "The Annals of Darrowshire", level = 56, zone = "Western Plaguelands", giver = "Chromie", giverMap = 1422, giverX = 39.5, giverY = 66.8, ender = "Chromie", enderMap = 1422, enderX = 39.5, enderY = 66.8, objective = "Bring the Annals of Darrowshire to Chromie in Andorhal.", summary = "To save Joseph Redpath, we must first discover his past.  We can learn this in the Annals of Darrowshire, a book held in the city hall of Andorhal.$B$BBring me that book.  We can then learn Joseph's fate, and with luck... change it!" },
            { ids = { 5210 }, name = "Brother Carlin", level = 56, zone = "Western Plaguelands", giver = "Chromie", giverMap = 1422, giverX = 39.5, giverY = 66.8, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands.", summary = "The Annals of Darrowshire, through my magic, has gained pages at its end, and now it extends its history beyond the battle.  One of the extra passages tells of another Redpath, Carlin, who survived Joseph's betrayal.  Carlin's now in the Plaguelands to the east, at the Light's Hope Chapel.$B$BTake the book and speak with him." },
            { ids = { 5168 }, name = "Heroes of Darrowshire", level = 56, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring Davil's Libram and Redpath's Shield to Carlin Redpath.", summary = "The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales.$B$BIt tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen.$B$BIts passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron's Withering.$B$BGather these relics, $N.  For fate and tragedy surrounds them." },
            { ids = { 5181 }, name = "Villains of Darrowshire", level = 57, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", summary = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin's Crossing, and his skull remains there.$B$BMarduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin's Crossing.$B$BRetrieve these items, $N.  I know not why, but I am certain their fate lies with you." },
            { ids = { 5206 }, name = "Marauders of Darrowshire", level = 60, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands.", summary = "Chromie said the relics you gathered are reagents to a powerful spell, and one more is required: skulls from the scourge who took part in the battle of Darrowshire.$B$BTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.$B$BGo, $N.  You'll find scourge champions in the Noxious Glade to the north and the Fungal Vale to the west." },
            { ids = { 5941 }, name = "Return to Chromie", level = 60, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Chromie", enderMap = 1422, enderX = 39.5, enderY = 66.8, objective = "Take the Bundle of Relics to Chromie in Andorhal.", summary = "You have gathered many relics of the battle of Darrowshire.  Each time you returned with more, my heart yearned for my village... yearned to protect it from its fate.$B$BI know that cannot be, but Chromie, that strange gnome in Andorhal, tells me it is possible.  She says you can save Darrowshire!$B$BShe asked me to gather together the relics, and to have you bring them to her.  She said that she awaits you in the ruined inn of Andorhal." },
            { ids = { 5721 }, name = "The Battle of Darrowshire", level = 60, zone = "Western Plaguelands", giver = "Chromie", giverMap = 1422, giverX = 39.5, giverY = 66.8, ender = "Pamela Redpath", enderMap = 1423, enderX = 31.1, enderY = 78.0, objective = "Place the Relic Bundle at the Darrowshire town square.$B$BPrevent Davil Lightfire's death until the death of Horgus.$B$BPrevent Captain Redpath's death until Redpath the Corrupted appears.$B$BDefeat Redpath the Corrupted.$B$BSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.", summary = "Now, $N, you will take part in battle of Darrowshire, and you will save Joseph Redpath.$B$BPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.$B$BAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela." },
            { ids = { 5942 }, name = "Hidden Treasures", level = 60, zone = "Eastern Plaguelands", giver = "Pamela Redpath", giverMap = 1423, giverX = 31.1, giverY = 78.0, ender = "Joseph's Chest", enderMap = 1423, enderX = 30.9, enderY = 77.8, objective = "Bring Joseph's Key to Joseph's Chest.", summary = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.$B$BHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?$B$BWell here's the key.  And thank you $N.  Thank you!  You're a very nice $gman:lady;!" },
        },
    },
    {
        id = "q4808",
        name = "Dawn's Gambit",
        zone = "Burning Steppes",
        minLevel = 50,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 4726 }, name = "Broodling Essence", level = 52, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", summary = "I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough!  I created a device--I call it the Draco Incarcinatrix 900.  It can capture the essence of dragon whelp broodlings!$B$BOr, at least I think it can.$B$BHere, take the device and zap a broodling in the Burning Steppes with it.  While it's under the device's effects, defeat the broodling and its essence should be released.$B$BIf it is, then splendid!  Bring me back samples so I can study them!" },
            { ids = { 4808 }, name = "Felnok Steelspring", level = 54, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Felnok Steelspring", enderMap = 1452, enderX = 61.6, enderY = 38.6, objective = "Give Tinkee's Letter to Felnok Steelspring.", summary = "I have another favor to ask of you.$B$BMy initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them!  I want to test this theory, but first I need specially made engineering components.  My colleague, Felnok Steelspring, can make them.$B$BHere, take this letter to Felnok.  It tells him what I need.  You'll find Felnok in Winterspring, in the town of Everlook." },
            { ids = { 4809 }, name = "Chillwind Horns", level = 54, zone = "Winterspring", giver = "Felnok Steelspring", giverMap = 1452, giverX = 61.6, giverY = 38.6, ender = "Felnok Steelspring", enderMap = 1452, enderX = 61.6, enderY = 38.6, objective = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", summary = "I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns.  The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do!  I'll need a supply of those to complete Tinkee's order.$B$BBring me the uncracked chillwind horns, and I'll prepare a package for Tinkee." },
            { ids = { 4810 }, name = "Return to Tinkee", level = 54, zone = "Winterspring", giver = "Felnok Steelspring", giverMap = 1452, giverX = 61.6, giverY = 38.6, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes.", summary = "Ok, everything is prepared and packed and ready for transport!  Good luck in your journey, and make sure you tell Tinkee that she owes me!" },
            { ids = { 4907 }, name = "Tinkee Steamboil", level = 60, zone = "Winterspring", giver = "Felnok Steelspring", giverMap = 1452, giverX = 61.6, giverY = 38.6, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Speak with Tinkee Steamboil.", summary = "Hi, $N.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons.$B$BYou should speak to her in the Burning Steppes, at the Flame Crest." },
            { ids = { 4734 }, name = "Egg Freezing", level = 60, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Use the Eggscilloscope Prototype on an egg in the Rookery.", summary = "$N, I've been working hard on a new device, the eggscilloscope!  It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid!  Can you test it for me?$B$BI heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs.  That's where you'll have to go to test the eggscilloscope, and then let me know how it worked!$B$BAnd don't worry.  Frozen dragon eggs should be harmless.  It's the unfrozen ones you have to worry about!" },
            { ids = { 4735 }, name = "Egg Collection", level = 60, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", summary = "$N, I'm finally ready for real samples of dragon eggs!  Here, take this collectronic module.  It's designed to extract a dragon egg and prepare it for transport.  Go back to the Rookery and use the module to collect eggs.$B$BAnd don't forget to freeze them first, or they might hatch before you can collect them!$B$BWhen you have enough eggs, bring them to me! " },
            { ids = { 5522 }, name = "Leonid Barthalomew", level = 60, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Leonid Barthalomew the Revered", enderMap = 1423, enderX = 71.9, enderY = 48.3, objective = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.", summary = "I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.$B$BLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.$B$BThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded." },
            { ids = { 5531 }, name = "Betina Bigglezink", level = 60, zone = "Eastern Plaguelands", giver = "Leonid Barthalomew the Revered", giverMap = 1423, giverX = 71.9, giverY = 48.3, ender = "Betina Bigglezink", enderMap = 1423, enderX = 71.7, enderY = 49.9, objective = "Bring the Frozen Eggs to Betina Bigglezink.", summary = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.$B$BNow, it is time we ended their research.$B$BTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow." },
            { ids = { 4771 }, name = "Dawn's Gambit", level = 60, zone = "Eastern Plaguelands", giver = "Betina Bigglezink", giverMap = 1423, giverX = 71.7, giverY = 49.9, ender = "Betina Bigglezink", enderMap = 1423, enderX = 71.7, enderY = 49.9, objective = "Place Dawn's Gambit in the Viewing Room of the Scholomance.  Defeat Vectus, then return to Betina Bigglezink.", summary = "I've placed Dawn's Gambit in the container you brought to us, the one that held the dragon eggs.  Your job is to bring it deep within the Scholomance.$B$BThe undead mage Vectus leads a team of scourge scholars... place Dawn's Gambit in their chamber, called the \"viewing room.\"  It will then react with the undead found there and, with a little luck, destroy them!$B$BAfter that, defeating Vectus shouldn't be a problem.  Right?" },
        },
    },
    {
        id = "q5097",
        name = "The Key to Scholomance",
        zone = "Western Plaguelands",
        minLevel = 50,
        maxLevel = 60,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 5097 }, name = "All Along the Watchtowers", level = 56, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "Commander Ashlam Valorfist", enderMap = 1422, enderX = 42.7, enderY = 84.0, after = { 5092 }, objective = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.$B$BOnce all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands.", summary = "Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.$B$BYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!" },
            { ids = { 5533 }, name = "Scholomance", level = 55, zone = "Western Plaguelands", giver = "Commander Ashlam Valorfist", giverMap = 1422, giverX = 42.7, giverY = 84.0, ender = "Alchemist Arbington", enderMap = 1422, enderX = 42.7, enderY = 83.8, objective = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands.", summary = "On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key.$B$BAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter." },
            { ids = { 5537 }, name = "Skeletal Fragments", level = 57, zone = "Western Plaguelands", giver = "Alchemist Arbington", giverMap = 1422, giverX = 42.7, giverY = 83.8, ender = "Alchemist Arbington", enderMap = 1422, enderX = 42.7, enderY = 83.8, objective = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.", summary = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.$B$BFirst thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too." },
            { ids = { 5538 }, name = "Mold Rhymes With...", level = 57, zone = "Western Plaguelands", giver = "Alchemist Arbington", giverMap = 1422, giverX = 42.7, giverY = 83.8, ender = "Krinkle Goodsteel", enderMap = 1446, enderX = 51.5, enderY = 28.8, objective = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", summary = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.$B$BI'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here.$B$BI guess I said the quiet part out loud again.  Oops.$B$BGadgetzan awaits you!  Good luck!" },
            { ids = { 5801 }, name = "Fire Plume Forged", level = 57, zone = "Tanaris", giver = "Krinkle Goodsteel", giverMap = 1446, giverX = 51.5, giverY = 28.8, ender = "Alchemist Arbington", enderMap = 1422, enderX = 42.7, enderY = 83.8, objective = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.$B$BBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.", summary = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.$B$BTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.$B$BThat's it on my end.  To finish your key, you'll need to talk to Arbington again." },
            { ids = { 5803 }, name = "Araj's Scarab", level = 60, zone = "Western Plaguelands", giver = "Alchemist Arbington", giverMap = 1422, giverX = 42.7, giverY = 83.8, ender = "Alchemist Arbington", enderMap = 1422, enderX = 42.7, enderY = 83.8, objective = "Destroy the four Scourge Summoning Crystals inside Andorhal to call forth Araj the Summoner.  Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.", summary = "Araj the Summoner lords over Andorhal from an obfuscated vantage.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.$B$BIn the city are four summoning crystals, one in each tower you marked for us previously.  Destroy all four crystals and break his hold on the city, drawing him into the open.  Once destroyed, seize his scarab from his fallen phylactery!" },
            { ids = { 5505 }, name = "The Key to Scholomance", level = 60, zone = "Western Plaguelands", giver = "Alchemist Arbington", giverMap = 1422, giverX = 42.7, giverY = 83.8, ender = "Alchemist Arbington", enderMap = 1422, enderX = 42.7, enderY = 83.8 },
        },
    },
    {
        id = "q8233",
        name = "The Azure Key",
        zone = "Stormwind City",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 4 },
        quests = {
            { ids = { 8233 }, name = "A Simple Request", level = 52, zone = "Stormwind City", giver = "Osborne the Night Man", giverMap = 1453, giverX = 77.4, giverY = 65.3, ender = "Lord Jorach Ravenholdt", enderMap = 1416, enderX = 86.0, enderY = 78.9, objective = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.", summary = "Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more.$b$bRavenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep." },
            { ids = { 8234 }, name = "Sealed Azure Bag", level = 52, zone = "Alterac Mountains", giver = "Lord Jorach Ravenholdt", giverMap = 1416, giverX = 86.0, giverY = 78.9, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara.", summary = "First things first.  What I've lost is a small blue bag, the contents of which are a private matter.$b$bDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.$b$bI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem." },
            { ids = { 8235 }, name = "Encoded Fragments", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara.", summary = "Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.$b$bUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.$b$bIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill forest oozes, since they have a tendency to pick up just about anything.  You'll find them in northeast Azshara." },
            { ids = { 8236 }, name = "The Azure Key", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Lord Jorach Ravenholdt", enderMap = 1416, enderX = 86.0, enderY = 78.9, objective = "Return the Azure Key to Lord Jorach Ravenholdt.", summary = "It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.$b$bThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.$b$bGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key." },
        },
    },
    {
        id = "q8251",
        name = "Destroy Morphaz",
        zone = "Azshara",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 8 },
        quests = {
            { ids = { 8251 }, name = "Magic Dust", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Bring 10 Glittering Dust to Archmage Xylem.", summary = "The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell.$b$bWhen I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay.$b$bThe time for talk is over, $N.  Find the blood elves along the cliffs of Azshara and use more \"persuasive\" methods to acquire their glittering dust." },
            { ids = { 8252 }, name = "The Siren's Coral", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Collect 6 Enchanted Coral and return them to Archmage Xylem.", summary = "Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara.$b$bSpecifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me." },
            { ids = { 8253 }, name = "Destroy Morphaz", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", summary = "There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.$b$bYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.$b$bYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach." },
        },
    },
    {
        id = "q8254",
        name = "Blood of Morphaz",
        zone = "Stormwind City",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 5 },
        quests = {
            { ids = { 8254 }, name = "Cenarion Aid", level = 52, zone = "Stormwind City", giver = "Brother Joshua", giverMap = 1453, giverX = 49.5, giverY = 45.2, ender = "Ogtinc", enderMap = 1447, enderX = 42.4, enderY = 42.6, objective = "Seek out Ogtinc in Azshara.", summary = "It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.$b$bThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara." },
            { ids = { 8255 }, name = "Of Coursers We Know", level = 52, zone = "Azshara", giver = "Ogtinc", giverMap = 1447, giverX = 42.4, giverY = 42.6, ender = "Ogtinc", enderMap = 1447, enderX = 42.4, enderY = 42.6, objective = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", summary = "The mosshoof coursers of Azshara are magnificent animals who once lived in Felwood.  They naturally resist disease and poison, and were unaffected by the corruption there.  In their ancestral wisdom, they simply chose to leave that sickened place.$b$bIt saddens my heart, but I must ask you to hunt these mighty beasts for me.  Gather four courser glands as the first ingredient for a restorative salve -- a salve we will use to heal Felwood." },
            { ids = { 8256 }, name = "The Ichor of Undeath", level = 52, zone = "Azshara", giver = "Ogtinc", giverMap = 1447, giverX = 42.4, giverY = 42.6, ender = "Ogtinc", enderMap = 1447, enderX = 42.4, enderY = 42.6, objective = "Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", summary = "For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.$b$bPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.$b$bDue to the potency of this vile element, I require only a single ichor." },
            { ids = { 8257 }, name = "Blood of Morphaz", level = 52, zone = "Azshara", giver = "Ogtinc", giverMap = 1447, giverX = 42.4, giverY = 42.6, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows.", summary = "Now the last part, the second cure.$b$bThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.$b$bA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood." },
        },
    },
    {
        id = "q5021",
        name = "Good Luck Charm",
        zone = "Western Plaguelands",
        minLevel = 50,
        maxLevel = 54,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 5021 }, name = "Better Late Than Never", level = 52, zone = "Western Plaguelands", giver = "Janice Felstone", giverMap = 1422, giverX = 38.4, giverY = 54.0, ender = "Janice's Parcel", enderMap = 1422, enderX = 38.7, enderY = 55.2, objective = "The ramblings of the ghostly woman indicated that she needed a package delivered.  She claimed that it was where her horse was.  As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible.", summary = "\"The package must be delivered... delivered before I'm trapped here!\"$B$BThe cries of a panicked woman feel almost like a whisper floating through the house.  Cowered in the upstairs corner is the apparition of a woman.  She does not seem to be fully cognizant of her surroundings, and she is only vaguely aware of you.$B$B\"Are you here to deliver my package?  Please, before it gets much worse!  I was going to ride out of here.  It should still be by my horse... or am I too late?\"" },
            { ids = { 5022 }, name = "Better Late Than Never", level = 52, zone = "Western Plaguelands", giver = "Janice's Parcel", giverMap = 1422, giverX = 38.7, giverY = 55.2, ender = "Royal Factor Bathrilor", enderMap = 1453, enderX = 57.2, enderY = 48.1, objective = "Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone.  There is usually a census officer located in City Hall.", summary = "You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to an Emma Felstone of Stormwind; the delivery of the package is dated for well over four years ago.$B$BThough it is unclear if Emma Felstone is even alive, it is widely known that the Stormwind City Hall keep records on the populace of the city.  This is handled through the Royal Factors of the Stormwind Census." },
            { ids = { 5048 }, name = "Good Natured Emma", level = 52, zone = "Stormwind City", giver = "Royal Factor Bathrilor", giverMap = 1453, giverX = 57.2, giverY = 48.1, ender = "Ol' Emma", enderMap = 1453, enderX = 60.2, enderY = 57.0, objective = "Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone.  If she is, then perhaps she'd like the package Janice Felstone made for her.", summary = "She's a tad ornery, and quite possibly out of her gourd... but the records indicate that Ol' Emma does fit the framework of who Emma Felstone might be.$B$BPerhaps you've seen Ol' Emma wander the city - she talks to herself, most often in nonsensical jibber-jabber.  Still, she doesn't hurt anything or anyone, so folks pretty much leave her be.$B$BAll things considered, I would say that Ol' Emma is in fact Emma Felstone.  You might try asking if her last name is indeed Felstone." },
            { ids = { 5050 }, name = "Good Luck Charm", level = 52, zone = "Stormwind City", giver = "Ol' Emma", giverMap = 1453, giverX = 60.2, giverY = 57.0, ender = "Janice Felstone", enderMap = 1422, enderX = 38.4, enderY = 54.0, objective = "Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm.", summary = "It would seem that I was wrong about you $N, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now.$B$BIf my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half.$B$BMaybe her knowing I have these things will now put her soul to rest." },
            { ids = { 5051 }, name = "Two Halves Become One", level = 54, zone = "Western Plaguelands", giver = "Janice Felstone", giverMap = 1422, giverX = 38.4, giverY = 54.0, ender = "Janice Felstone", enderMap = 1422, enderX = 38.4, enderY = 54.0, objective = "Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.$B$BGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.", summary = "The ramblings of the poor ghost continue:$B$B\"I'm so cold, John.  Bring me your charm, and we'll be together!  Quickly John, before the plague comes to change us into hideous beasts!  I can't see you John... but I know you're near.  I feel you near me.\"$B$BPerhaps if the second half of the charm was found and reassembled, this would constitute what the spirit of Janice Felstone is seeking." },
        },
    },
    {
        id = "q5543",
        name = "In Dreams",
        zone = "Eastern Plaguelands",
        minLevel = 52,
        maxLevel = 60,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 5542 }, name = "Demon Dogs", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", summary = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'$B$BYou can start with the Plaguehounds and their runts.$B$BI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed." },
            { ids = { 5543 }, name = "Blood Tinged Skies", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Slay 30 Plaguebats and return to Tirion Fordring.", summary = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.$B$BEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats." },
            { ids = { 5544 }, name = "Carrion Grubbage", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", summary = "My food supplies are running low, $r. I am ashamed to admit that I might not have enough food to share with you.$B$BCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!" },
            { ids = { 5742 }, name = "Redemption", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Listen to what Tirion Fordring has to say.", summary = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself." },
            { ids = { 5781 }, name = "Of Forgotten Memories", level = 57, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", summary = "To help Taelan regain what he has lost, you must gather items from his past.$B$BThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.$B$BAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.$B$BYou must venture to the Undercroft and recover Taelan's hammer." },
            { ids = { 5845 }, name = "Of Lost Honor", level = 58, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", summary = "The Order of the Silver Hand was utterly decimated when Uther was slain.$B$BThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.$B$BWere any of the Order left alive, he thought - and did it matter?$B$BIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.$B$BYou must travel to Northdale and recover that symbol of lost honor." },
            { ids = { 5846 }, name = "Of Love and Family", level = 58, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Artist Renfray", enderMap = 1422, enderX = 65.8, enderY = 75.4, objective = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.", summary = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.$B$BIf this painting still exists, you must find it.$B$BTravel to the ruined island of Caer Darrow and see if the painting or the artist remain." },
            { ids = { 5848 }, name = "Of Love and Family", level = 60, zone = "Western Plaguelands", giver = "Artist Renfray", giverMap = 1422, giverX = 65.8, giverY = 75.4, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.$B$BReturn the painting to Tirion Fordring.", summary = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.$B$BAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.$B$BTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'$B$BMay the Light guide your actions." },
            { ids = { 5861 }, name = "Find Myranda", level = 60, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Myranda the Hag", enderMap = 1422, enderX = 50.8, enderY = 77.8, objective = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.", summary = "$N, you have done all that I have asked thus far. Only one step remains in your quest of redemption.$B$BYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.$B$BThere is only one way in which to deliver my message and that is through a guise of deception.$B$BTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you." },
            { ids = { 5862 }, name = "Scarlet Subterfuge", level = 60, zone = "Western Plaguelands", giver = "Myranda the Hag", giverMap = 1422, giverX = 50.8, giverY = 77.8, ender = "Highlord Taelan Fordring", enderMap = 1422, enderX = 42.0, enderY = 14.8, objective = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.$B$BHearthglen is to the north, Taelan should be inside of Mardenholde Keep.", summary = "I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.$B$BShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.$B$BSpeak to me again when you are ready." },
            { ids = { 5944 }, name = "In Dreams", level = 60, zone = "Western Plaguelands", giver = "Highlord Taelan Fordring", giverMap = 1422, giverX = 42.0, giverY = 14.8, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Escort Taelan Fordring out of Hearthglen.", summary = "For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become? It has been decades, yet the memories of my father; those precious memories, they are what have kept me alive.$B$BI have dreams, stranger. In these dreams my father is with me. He stands proudly at my side as I am inducted into the Order. We battle legion of Scourge, side by side. We bring honor to the Alliance, to Lordaeron.$B$BI want not to dream anymore.$B$BTake me to him." },
        },
    },
    {
        id = "q5250",
        name = "The Crystal of Zin-Malor",
        zone = "Teldrassil",
        minLevel = 53,
        maxLevel = 58,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 5250 }, name = "Starfall", level = 56, zone = "Teldrassil", giver = "Daryn Lightwind", giverMap = 1438, giverX = 55.4, giverY = 92.2, ender = "Wynd Nightchaser", enderMap = 1452, enderX = 52.0, enderY = 30.4, objective = "Find Starfall in Winterspring and speak with Wynd Nightchaser.", summary = "In Winterspring, to the north of Felwood, there are many ancient elven ruins. It's a harsh land, but it holds many secrets and places to explore.$B$BMy studies here keep me so busy that I have not had the opportunity to travel to Winterspring for some time. But there's no reason why you shouldn't travel there and study the ruins.$B$BWhile you're there, look for Wynd Nightchaser. He spends most of his time in Starfall and he knows a lot about the area.$B$BTell him that you are a student of mine..." },
            { ids = { 5244 }, name = "The Ruins of Kel'Theril", level = 56, zone = "Winterspring", giver = "Wynd Nightchaser", giverMap = 1452, giverX = 52.0, giverY = 30.4, ender = "Jaron Stoneshaper", enderMap = 1452, enderX = 52.1, enderY = 30.4, objective = "Speak with Jaron Stoneshaper in Starfall Village.", summary = "The story behind Kel'Theril is one of a cursed race, bound to the place where they attempted an unfortunate ritual...$B$BThe highborne that you will find there once stole a sacred artifact, believing that they could siphon its power for themselves, becoming even more powerful. In their efforts, the relic shattered in a huge explosion, driving the pieces below the ice of the lake...$B$BSpeak with Jaron Stoneshaper if you'd like to learn more; he has recently visited the area and can tell you more." },
            { ids = { 5245 }, name = "Troubled Spirits of Kel'Theril", level = 56, zone = "Winterspring", giver = "Jaron Stoneshaper", giverMap = 1452, giverX = 52.1, giverY = 30.4, ender = "Aurora Skycaller", enderMap = 1423, enderX = 46.5, enderY = 16.0, objective = "Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands.", summary = "The highborne spirits are miserable creatures, that's for sure. They are still searching for pieces of the very thing that has cursed them to Kel'Theril forever -- the stolen relic.$B$BIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.$B$BNow, I can't tell you a thing about what you find, but I do know of someone who might... Aurora Skycaller; she dwells near the Northpass Tower in the northern part of Eastern Plaguelands." },
            { ids = { 5246 }, name = "Fragments of the Past", level = 56, zone = "Eastern Plaguelands", giver = "Aurora Skycaller", giverMap = 1423, giverX = 46.5, giverY = 16.0, ender = "Aurora Skycaller", enderMap = 1423, enderX = 46.5, enderY = 16.0, objective = "Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.", summary = "I did not realize... Forgive my callous words, $c.$B$BThe mistakes of my ancestors are not what I wish to dwell on, but if your request is truly genuine, then I will help you.$B$B<Aurora examines the fragments.>$B$BI believe this is the Crystal of Zin-Malor, an artifact that can contain and control strong arcane forces. It could have been used for good, but the evil intentions of those that stole it caused it to shatter.$B$BGo to the Temple of Zin-Malor in Azshara - I can only hope the book is still there." },
            { ids = { 5247 }, name = "Fragments of the Past", level = 57, zone = "Eastern Plaguelands", giver = "Aurora Skycaller", giverMap = 1423, giverX = 46.5, giverY = 16.0, ender = "Aurora Skycaller", enderMap = 1423, enderX = 46.5, enderY = 16.0, objective = "Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands.", summary = "I will be able to help you, if recreating the artifact is truly what you wish to do.$B$BTo seal the pieces back together, I will need items with strong magical qualities. An enchanted thorium bar and five crystal restore... You'll also need to collect some water from what might seem an unlikely place... Find the dire pool along Eldreth Row at Dire Maul in Feralas, and fill this vial.$B$BWhile you are gone, I will attempt to glean from these pages the knowledge I need to repair the damage done to the relic." },
            { ids = { 5248 }, name = "Tormented By the Past", level = 58, zone = "Eastern Plaguelands", giver = "Aurora Skycaller", giverMap = 1423, giverX = 46.5, giverY = 16.0, ender = "Remorseful Highborne", enderMap = 1452, enderX = 56.1, enderY = 44.4, objective = "Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you.", summary = "$N, I weep for what has happened in the past. Like this crystal, the elves, as a race, have been shattered. I do not know if the pieces will ever again be reunited into one, but my sorrow has been eased by being able to help you with this one small task. $B$BWe must not forget the past, $N...$B$BPlease take the Crystal of Zin-Malor back to Lake Kel'Theril. You must find a highborne spirit that realizes the error of what was done so long ago. Show the spirit that we have made things right again." },
            { ids = { 5252 }, name = "Remorseful Highborne", level = 58, zone = "Winterspring", giver = "Remorseful Highborne", giverMap = 1452, giverX = 56.1, giverY = 44.4, ender = "Wynd Nightchaser", enderMap = 1452, enderX = 52.0, enderY = 30.4, objective = "Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor.", summary = "The... the crystal...$B$BThe highborne here are clouded by their own misssery...$B$BI am sorrrrrowful, but I realize the errorrrr of what happened so long ago. Even though there is no waaaay to change the past, I am now at peacccce knowing that you have recovered the crystal of Zin-Malor...$B$BYouuu must return it...$B$BIt muuuussst be returrrned." },
            { ids = { 5253 }, name = "The Crystal of Zin-Malor", level = 58, zone = "Winterspring", giver = "Wynd Nightchaser", giverMap = 1452, giverX = 52.0, giverY = 30.4, ender = "Arch Druid Fandral Staghelm", enderMap = 1457, enderX = 34.8, enderY = 9.3, objective = "Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus.", summary = "Quite impressive, $N.$B$BThe crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded.$B$BSeek out Arch Druid Fandral Staghelm in Darnassus, and bring the crystal to him, $N. It should be in the hands of those that will not abuse its power. From the looks of it, only a handful of the strongest magic users would be able to control such a power. " },
        },
    },
    {
        id = "q1015",
        name = "The New Frontier",
        zone = "Stormwind City",
        minLevel = 54,
        maxLevel = 57,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1015 }, name = "The New Frontier", level = 55, zone = "Stormwind City", giver = "Crier Goodman", giverMap = 1453, giverX = 56.4, giverY = 74.1, ender = "Arch Druid Fandral Staghelm", enderMap = 1457, enderX = 34.8, enderY = 9.3, objective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", summary = "Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!" },
            { ids = { 6761 }, name = "The New Frontier", level = 55, zone = "Darnassus", giver = "Arch Druid Fandral Staghelm", giverMap = 1457, giverX = 34.8, giverY = 9.3, ender = "Mathrengyl Bearwalker", enderMap = 1457, enderX = 35.4, enderY = 8.4, objective = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.", summary = "I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.$B$BLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.$B$BI'll leave it to you to decide whether or not you're a fool." },
            { ids = { 6762 }, name = "Rabine Saturna", level = 55, zone = "Darnassus", giver = "Mathrengyl Bearwalker", giverMap = 1457, giverX = 35.4, giverY = 8.4, ender = "Rabine Saturna", enderMap = 1450, enderX = 51.7, enderY = 45.1, objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", summary = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.$B$BWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time." },
            { ids = { 1124 }, name = "Wasteland", level = 55, zone = "Moonglade", giver = "Rabine Saturna", giverMap = 1450, giverX = 51.7, giverY = 45.1, ender = "Layo Starstrike", enderMap = 1451, enderX = 81.9, enderY = 18.9, objective = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.", summary = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.$B$BSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly." },
            { ids = { 1125 }, name = "The Spirits of Southwind", level = 55, zone = "Silithus", giver = "Layo Starstrike", giverMap = 1451, giverX = 81.9, giverY = 18.9, ender = "Layo Starstrike", enderMap = 1451, enderX = 81.9, enderY = 18.9, objective = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", summary = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, $N.$B$BFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...$B$BThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed." },
            { ids = { 1126 }, name = "Hive in the Tower", level = 57, zone = "Silithus", giver = "Layo Starstrike", giverMap = 1451, giverX = 81.9, giverY = 18.9, ender = "Layo Starstrike", enderMap = 1451, enderX = 81.9, enderY = 18.9, objective = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity.  Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", summary = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.$B$BThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me." },
            { ids = { 6844 }, name = "Umber, Archivist", level = 57, zone = "Silithus", giver = "Layo Starstrike", giverMap = 1451, giverX = 81.9, giverY = 18.9, ender = "Umber", enderMap = 1450, enderX = 44.9, enderY = 35.6, objective = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.", summary = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!$B$BTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it." },
            { ids = { 6845 }, name = "Uncovering Past Secrets", level = 57, zone = "Moonglade", giver = "Umber", giverMap = 1450, giverX = 44.9, giverY = 35.6, ender = "Rabine Saturna", enderMap = 1450, enderX = 51.7, enderY = 45.1, objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.", summary = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.$B$BIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, $N... that is, unless you want to be doused in honey.$B$BIt's happened, trust me." },
            { ids = { 1185 }, name = "Under the Chitin Was...", level = 57, zone = "Moonglade", giver = "Umber", giverMap = 1450, giverX = 44.9, giverY = 35.6, ender = "Umber", enderMap = 1450, enderX = 44.9, enderY = 35.6 },
        },
    },
    {
        id = "q6804",
        name = "The Molten Core",
        zone = "Azshara",
        minLevel = 55,
        maxLevel = 60,
        importance = 3,
        kind = "raid",
        quests = {
            { ids = { 6804 }, name = "Poisoned Water", level = 56, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.", summary = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!$B$BTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.$B$BDefeat the discordant surges and bring me their bracers of binding." },
            { ids = { 6805 }, name = "Stormers and Rumblers", level = 57, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Kill 15 Dust Stormers and 15 Desert Rumbers and then return to Duke Hydraxis in Azshara.", summary = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!$B$BFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.$B$BGo to the Crystal Vale in Silithus and defeat our enemies, then return to me." },
            { ids = { 6821 }, name = "Eye of the Emberseer", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.", summary = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?$B$BThat is your new task.$B$BHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth." },
            { ids = { 6822 }, name = "The Molten Core", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.", summary = "$n, perhaps it is time to give you a real test.  Are you ready?$B$BAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.$B$BGo to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there.$B$BAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live." },
            { ids = { 6823 }, name = "Agent of Hydraxis", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.", summary = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.$B$BThe campaign will be long, but if you persevere then your glory and honor will be great." },
            { ids = { 6824 }, name = "Hands of the Enemy", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.", summary = "$N, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.$B$BBut its success would further our war efforts tremendously and... it was deemed worth risking you.$B$BWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!$B$BThis task will take every resource you possess, $N, but if can do it then the Firelords will be dealt a terrible blow." },
            { ids = { 7486 }, name = "A Hero's Reward", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Hydraxis' Coffer", enderMap = 1447, enderX = 79.2, enderY = 74.9, objective = "Claim your reward from Hydraxis' Coffer.", summary = "$N, your services to the Warlords surpassed all we could expect from the denizens of this world.$B$BWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.$B$BUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.$B$BGo, $N.  Claim your reward." },
        },
    },
    {
        id = "q5382",
        name = "The Lich, Ras Frostwhisper",
        zone = "Western Plaguelands",
        minLevel = 55,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 5382 }, name = "Doctor Theolen Krastinov, the Butcher", level = 60, zone = "Western Plaguelands", giver = "Eva Sarkhoff", giverMap = 1422, giverX = 70.2, giverY = 73.7, ender = "Eva Sarkhoff", enderMap = 1422, enderX = 70.2, enderY = 73.7, objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", summary = "Krastinov is responsible for the deaths of thousands. He must be punished, justice must be meted out.$B$BFind him and exact upon him the agony he has inflicted upon countless innocents. Once he is destroyed, burn our remains. Turn them to ashes, $N." },
            { ids = { 5515 }, name = "Krastinov's Bag of Horrors", level = 60, zone = "Western Plaguelands", giver = "Eva Sarkhoff", giverMap = 1422, giverX = 70.2, giverY = 73.7, ender = "Eva Sarkhoff", enderMap = 1422, enderX = 70.2, enderY = 73.7, objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", summary = "A great weight has been lifted from our hearts, $N, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.$B$BBefore you may face Kirtonos, however, you must first secure a method in which to summon him.$B$BIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.$B$BFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find." },
            { ids = { 5384 }, name = "Kirtonos the Herald", level = 60, zone = "Western Plaguelands", giver = "Eva Sarkhoff", giverMap = 1422, giverX = 70.2, giverY = 73.7, ender = "Eva Sarkhoff", enderMap = 1422, enderX = 70.2, enderY = 73.7, objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.$B$BFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.", summary = "This is it, $N.$B$B<Eva points to the vial inside the bag.>$B$BThe blood of innocents. The purest blood, used to appease Krastinov's master.$B$BIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.$B$BTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.$B$BShould you succeed, you will earn more than just our gratitude." },
            { ids = { 5461 }, name = "The Human, Ras Frostwhisper", level = 60, zone = "Western Plaguelands", giver = "Magistrate Marduke", giverMap = 1422, giverX = 70.6, giverY = 74.1, ender = "Magistrate Marduke", enderMap = 1422, enderX = 70.6, enderY = 74.1, objective = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.", summary = "The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.$B$BUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.$B$BYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, $N." },
            { ids = { 5462 }, name = "The Dying, Ras Frostwhisper", level = 60, zone = "Western Plaguelands", giver = "Magistrate Marduke", giverMap = 1422, giverX = 70.6, giverY = 74.1, ender = "Leonid Barthalomew the Revered", enderMap = 1423, enderX = 71.9, enderY = 48.3, objective = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.", summary = "Upon tainted soil, the keepsake must be attuned.$B$BIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.$B$BIt is those grounds that must be found.$B$BThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, $N. " },
            { ids = { 5463 }, name = "Menethil's Gift", level = 60, zone = "Eastern Plaguelands", giver = "Leonid Barthalomew the Revered", giverMap = 1423, giverX = 71.9, giverY = 48.3, ender = "Menethil's Gift", enderMap = 1423, enderX = 26.5, enderY = 10.4, enderInside = "Stratholme", objective = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground. ", summary = "I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.$B$B<Leonid gazes at the ground and then looks up at you.>$B$BYes, $r, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scourge." },
            { ids = { 5464 }, name = "Menethil's Gift", level = 60, zone = "Stratholme", giver = "Menethil's Gift", giverMap = 1423, giverX = 26.5, giverY = 10.4, giverInside = "Stratholme", ender = "Leonid Barthalomew the Revered", enderMap = 1423, enderX = 71.9, enderY = 48.3, objective = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", summary = "The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack." },
            { ids = { 5465 }, name = "Soulbound Keepsake", level = 60, zone = "Eastern Plaguelands", giver = "Leonid Barthalomew the Revered", giverMap = 1423, giverX = 71.9, giverY = 48.3, ender = "Magistrate Marduke", enderMap = 1422, enderX = 70.6, enderY = 74.1, objective = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.", summary = "Return to Marduke with the keepsake, $N. He will instruct you in its use." },
            { ids = { 5466 }, name = "The Lich, Ras Frostwhisper", level = 60, zone = "Western Plaguelands", giver = "Magistrate Marduke", giverMap = 1422, giverX = 70.6, giverY = 74.1, ender = "Magistrate Marduke", enderMap = 1422, enderX = 70.6, enderY = 74.1, objective = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", summary = "There is but one task remaining, $N. Confront the lich, Ras Frostwhisper, in his lair.$B$BUse the power of the keepsake against the beast -  be unrelenting in your actions!  Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!$B$BWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head." },
        },
    },
    {
        id = "q5251",
        name = "The Archivist",
        zone = "Eastern Plaguelands",
        minLevel = 55,
        maxLevel = 60,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 5251 }, name = "The Archivist", level = 60, zone = "Eastern Plaguelands", giver = "Duke Nicholas Zverenhoff", giverMap = 1423, giverX = 71.6, giverY = 50.1, ender = "Duke Nicholas Zverenhoff", enderMap = 1423, enderX = 71.6, enderY = 50.1, objective = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", summary = "Anything taken to an extreme is hazardous to our world, $N. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?$B$BBlasphemers, one and all!$B$BOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded." },
            { ids = { 5262 }, name = "The Truth Comes Crashing Down", level = 60, zone = "Stratholme", ender = "Duke Nicholas Zverenhoff", enderMap = 1423, enderX = 71.6, enderY = 50.1, objective = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.", summary = "You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.$B$BThe Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity?$B$BYou carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof.$B$BDuke Nicholas Zverenhoff must be told at once!" },
            { ids = { 5263 }, name = "Above and Beyond", level = 60, zone = "Eastern Plaguelands", giver = "Duke Nicholas Zverenhoff", giverMap = 1423, giverX = 71.6, giverY = 50.1, ender = "Duke Nicholas Zverenhoff", enderMap = 1423, enderX = 71.6, enderY = 50.1, objective = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", summary = "You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice.$B$B<Zverenhoff clasps his hands together in front of his face.>$B$BKel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head. " },
            { ids = { 5264 }, name = "Lord Maxwell Tyrosus", level = 60, zone = "Eastern Plaguelands", giver = "Duke Nicholas Zverenhoff", giverMap = 1423, giverX = 71.6, giverY = 50.1, ender = "Lord Maxwell Tyrosus", enderMap = 1423, enderX = 71.9, enderY = 48.4, objective = "Speak with Lord Maxwell Tyrosus. He is inside the church.", summary = "I am about to bestow a great honor upon you, $N.$B$BLord Maxwell wishes to reward you for your service to the Argent Dawn!$B$BIt has been years since Maxwell has granted audience to outsiders." },
            { ids = { 5265 }, name = "The Argent Hold", level = 60, zone = "Eastern Plaguelands", giver = "Lord Maxwell Tyrosus", giverMap = 1423, giverX = 71.9, giverY = 48.4, ender = "The Argent Hold", enderMap = 1423, enderX = 72.0, enderY = 48.4, objective = "Open the Argent Hold and claim your reward.", summary = "Through the years the Argent Hold has remained locked. None have been worthy to reach inside and take from it the power of the Argent Dawn - until today.$B$BThe Argent Hold is now open to you, $N." },
        },
    },
    {
        id = "q5001",
        name = "Maxwell's Mission",
        zone = "Blackrock Spire",
        minLevel = 55,
        maxLevel = 60,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 5001 }, name = "Bijou's Belongings", level = 59, zone = "Blackrock Spire", giver = "Bijou", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Spire", ender = "Bijou", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Spire", objective = "Find Bijou's Belongings and return them to her. Good luck!", summary = "Ordinarily I don't deal with $rs but it seems that I'm stuck between a troll and a hard place. You see, my mission here is one of utmost importance to the Horde. The information I've discovered, however, applies to the well being of the Alliance as well. Now believe me, I'm no Alliance sympathizer, but the Blackrock threat is bigger than just a bunch of orcs.$B$BYou help me out by finding my belongings and I'll help you out with some information that could prove useful to your kind.$B$BDeal?" },
            { ids = { 5002 }, name = "Message to Maxwell", level = 59, zone = "Blackrock Spire", giver = "Bijou", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Spire", ender = "Marshal Maxwell", enderMap = 1428, enderX = 84.7, enderY = 69.0, objective = "Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell.", summary = "I'm a goblin of my word, $r. Now listen closely:$B$BThese orcs are used primarily as beasts of burden and cannon fodder for the black dragonflight!$B$BTheir true leader is none other than Nefarian, brood of Deathwing. I've also discovered the location of Nefarian's subordinates in this part of the citadel.$B$BTake this map to Marshal Maxwell in the Burning Steppes. It has the location of these fiends marked for easy identification." },
            { ids = { 5081 }, name = "Maxwell's Mission", level = 60, zone = "Burning Steppes", giver = "Marshal Maxwell", giverMap = 1428, giverX = 84.7, giverY = 69.0, ender = "Marshal Maxwell", enderMap = 1428, enderX = 84.7, enderY = 69.0, objective = "Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done.", summary = "This information fills in the gaps to our otherwise impeccable intelligence of Blackrock Spire.$B$BThe attack must be decisive, $N.$B$BFirst their war master, the troll Voone, must be destroyed. Without his battle plans, the Blackrock orcs will be thrown into chaos.$B$BYou must then take out the ogre Highlord, Omokk. The cowardly ogres of Blackrock are powerless without his leadership.$B$BLastly, the overlord of the citadel: Wyrmthalak. With Wyrmthalak dead, their central command unit is without a conduit." },
        },
    },
    {
        id = "q6182",
        name = "Order Must Be Restored",
        zone = "Stormwind City",
        minLevel = 56,
        maxLevel = 60,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 6182 }, name = "The First and the Last", level = 60, zone = "Stormwind City", giver = "Highlord Bolvar Fordragon", giverMap = 1453, giverX = 80.2, giverY = 38.3, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.", summary = "Nathanos Marris was the first and last of the human ranger lords. A disciple of Sylvanas Windrunner, now the Banshee Queen of the Forsaken.$B$BWe had thought that Nathanos had been killed in action in the defense of Lordaeron five years ago. Although his corpse was never recovered, it was assumed that he did not make it out of the Eastern Plaguelands.$B$BMathias Shaw has been investigating the disappearance and may have some new information. Report to him at once. He resides in Old Town, at the Barracks." },
            { ids = { 6183 }, name = "Honor the Dead", level = 60, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Master Mathias Shaw", enderMap = 1453, enderX = 78.3, enderY = 70.7, objective = "Speak with Mathias Shaw again if you wish to accept his task.", summary = "Five of my best field agents were assigned the Marris case. One returned, only to end up dead in his sleep three days later.$B$BWhat little information we did manage to get out of him was incoherent gibberish. We made out two words: \"Nathanos,\" and \"Blightcaller.\"$B$BI do not have the available manpower to continue this investigation and Ravenholdt will not assist us. We must get to the bottom of this; if only to provide closure to the families of the deceased. Will you help?" },
            { ids = { 6184 }, name = "Flint Shadowmore", level = 60, zone = "Stormwind City", giver = "Master Mathias Shaw", giverMap = 1453, giverX = 78.3, giverY = 70.7, ender = "Flint Shadowmore", enderMap = 1422, enderX = 43.6, enderY = 84.5, objective = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore.", summary = "The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.$B$BFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.$B$BGood luck, $N." },
            { ids = { 6185 }, name = "The Eastern Plagues", level = 60, zone = "Western Plaguelands", giver = "Flint Shadowmore", giverMap = 1422, giverX = 43.6, giverY = 84.5, ender = "Flint Shadowmore", enderMap = 1422, enderX = 43.6, enderY = 84.5, objective = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", summary = "As I said, your first mission is one of reconnaissance. Nothing fancy, $N. You must travel to the Eastern Plaguelands and look for any clues as to this Blightcaller.$B$BBe on the lookout for information about our missing operatives. We have to assume that they are dead and if they are dead, they must have a corpse... somewhere.$B$B<Flint swallows hard.>$B$BAll SI:7 agents carry this insignia.$B$B<Flint shows you his SI:7 insignia.>$B$BBring any of those that you may find back to me." },
            { ids = { 6186 }, name = "The Blightcaller Cometh", level = 60, zone = "Western Plaguelands", giver = "Flint Shadowmore", giverMap = 1422, giverX = 43.6, giverY = 84.5, ender = "Highlord Bolvar Fordragon", enderMap = 1453, enderX = 80.2, enderY = 38.3, objective = "Return to Stormwind and inform Highlord Bolvar Fordragon of the fate of Nathanos Marris.", summary = "<The blood appears to have completely drained from Flint's face.>$B$BNa... Nathanos did this? Nathanos is the Blightcaller?$B$BWhy? He was... was so noble - a ranger lord respected by all. The only human ever allowed to train under the high elves. Now a ruthless agent of the Forsaken?$B$BI... I am sorry to ask this of you, $N, but Highlord Fordragon must be informed of this turn of events at once. Please, return to Stormwind and deliver the news." },
            { ids = { 6187 }, name = "Order Must Be Restored", level = 60, zone = "Stormwind City", giver = "Highlord Bolvar Fordragon", giverMap = 1453, giverX = 80.2, giverY = 38.3, ender = "Highlord Bolvar Fordragon", enderMap = 1453, enderX = 80.2, enderY = 38.3, objective = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.$B$BKeep your wits about you, $N. The Horde will defend the ranger lord with their very lives.", summary = "Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?$B$BNathanos' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.$B$BAnd now... the champion of the Forsaken.$B$BNo. This cannot be. Order must be restored.$B$BGather an army, $N. Return to the Plagues with your army and destroy the Blightcaller.$B$BI wish you luck, $N. Truly, you will need it for this battle." },
        },
    },
    {
        id = "q5160",
        name = "The Matron Protectorate",
        zone = "Blackrock Spire",
        minLevel = 57,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 5160 }, name = "The Matron Protectorate", level = 60, zone = "Blackrock Spire", giver = "Awbee", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Spire", ender = "Haleh", enderMap = 1452, enderX = 54.5, enderY = 51.2, objective = "Travel to Winterspring and find Haleh. Give her Awbee's scale.", summary = "Travel to Kalimdor, $r. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril.$B$BUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate.$B$BGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place." },
            { ids = { 5161 }, name = "Wrath of the Blue Flight", level = 60, zone = "Winterspring", giver = "Haleh", giverMap = 1452, giverX = 54.5, giverY = 51.2, ender = "Haleh", enderMap = 1452, enderX = 54.5, enderY = 51.2, objective = "Speak with Haleh if you wish to continue.", summary = "We understand what the cursed brood of Deathwing attempts to do and we know that it cannot be allowed.$B$BBecause of the protection Blackrock mountain affords Nefarian, it has become increasingly difficult for us to intercede.$B$BWe can, however, empower you, mortal - should you so choose.$B$BThe path before you is one full of peril. You must decide whether to accept our help. Ponder this and speak with me again when a decision has been made." },
            { ids = { 5162 }, name = "Wrath of the Blue Flight", level = 60, zone = "Winterspring", giver = "Haleh", giverMap = 1452, giverX = 54.5, giverY = 51.2, ender = "Jeziba", enderMap = 1422, enderX = 39.4, enderY = 66.8, objective = "Speak with Jeziba in the Plaguelands. He resides in Andorhal.", summary = "It is the arcane that I control and the arcane which will send you to your next destination.$B$BWhen you are ready, the journey will begin. To the Plaguelands you will go and to Jeziba you will speak.$B$BHe is a mortal as wise as the ancients and as patient as the immovable earth. Find him in Andorhal." },
            { ids = { 5164 }, name = "Catalogue of the Wayward", level = 60, zone = "Western Plaguelands", giver = "Jeziba", giverMap = 1422, giverX = 39.4, giverY = 66.8, ender = "Catalogue of the Wayward", enderMap = 1422, enderX = 39.4, enderY = 66.6, objective = "Read from the Catalogue of the Wayward.", summary = "A finer instrument of justice, Haleh could not have chosen. Read from the catalogue of the wayward and be enlightened.$B$BShould you persist... should you do what is asked of you... should you survive... a hero you will make." },
            { ids = { 5166 }, name = "Breastplate of the Chromatic Flight", level = 60, zone = "Western Plaguelands", giver = "Catalogue of the Wayward", giverMap = 1422, giverX = 39.4, giverY = 66.6, ender = "Jeziba", enderMap = 1422, enderX = 39.4, enderY = 66.8, objective = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':$B$B1 Chromatic Carapace.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B10 Frayed Abomination Stitchings.", summary = "The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony.$B$BThe scales of the very beasts we battle must be sewn to the pristine carapace of an elder chromatic drake or dragon. None are known to exist at this time and we should hope that none will ever exist.$B$BLastly, perhaps the most difficult of all components: the blood of heroes.$B$BThe Sculptor must ultimately forge this creation." },
        },
    },
    {
        id = "q4766",
        name = "Doomrigger's Clasp",
        zone = "Stormwind City",
        minLevel = 57,
        maxLevel = 60,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 4766 }, name = "Mayara Brightwing", level = 60, zone = "Stormwind City", giver = "Count Remington Ridgewell", giverMap = 1453, giverX = 76.9, giverY = 47.8, ender = "Mayara Brightwing", enderMap = 1428, enderX = 84.8, enderY = 69.1, objective = "Speak with Mayara Brightwing in the Burning Steppes.", summary = "An agent of mine, Mayara Brightwing, was sent to the Burning Steppes to scout the ruined city of Thaurissan.  That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum.$B$BMayara says she found something and will need aid in retrieving it, but it is not in Thaurissan.  Instead, a foray into Blackrock Spire will be required.$B$BI do not know the details, but if interested then speak with Mayara in the Burning Steppes." },
            { ids = { 4764 }, name = "Doomrigger's Clasp", level = 60, zone = "Burning Steppes", giver = "Mayara Brightwing", giverMap = 1428, giverX = 84.8, giverY = 69.1, ender = "Mayara Brightwing", enderMap = 1428, enderX = 84.8, enderY = 69.1, objective = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", summary = "There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art.$B$BThat was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there.$B$BOne such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.$B$BThat clasp, $N, is your goal." },
            { ids = { 4765 }, name = "Delivery to Ridgewell", level = 60, zone = "Burning Steppes", giver = "Mayara Brightwing", giverMap = 1428, giverX = 84.8, giverY = 69.1, ender = "Count Remington Ridgewell", enderMap = 1453, enderX = 76.9, enderY = 47.8, objective = "Bring Ridgewell's Crate to Remington Ridgewell in Stormwind.", summary = "I have packaged Doomriggers Clasp into a crate, suitable for shipment to Stormwind.  $N, you have been extremely helpful -- can I ask you for one last favor?$B$BDeliver the crate to Count Remington Ridgewell.  You will find him in the Keep of Stormwind.  I am sure he'll be very pleased to see what you have for him." },
        },
    },
    {
        id = "q8960",
        name = "Lord Valthalak's Amulet",
        zone = "Eastern Plaguelands",
        minLevel = 58,
        maxLevel = 60,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 8951, 8952, 8953, 8954, 8955, 8956, 8958, 8959 }, name = "Anthion's Parting Words", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Deliana", enderMap = 1455, enderX = 43.5, enderY = 52.6, after = { 9015 }, objective = "Return to Deliana in Ironforge with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.", summary = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!" },
            { ids = { 8960 }, name = "Bodley's Unfortunate Fate", level = 60, zone = "Ironforge", giver = "Deliana", giverMap = 1455, giverX = 43.5, giverY = 52.6, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.", summary = "So we need to recover the rest of the medallion?  Finding Bodley's going to be a bit of a headache.  He went back to Blackrock Mountain to attempt to re-enter Blackrock Spire and never came back.$B$BI'd suggest taking the goblin's ghost revealing device with you, as I fear the worst might have happened." },
            { ids = { 8961 }, name = "Three Kings of Flame", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.", summary = "In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.$B$BThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by them." },
            { ids = { 8962 }, name = "Components of Importance", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", summary = "$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus." },
            { ids = { 8967 }, name = "The Left Piece of Lord Valthalak's Amulet", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", summary = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.$B$BShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces." },
            { ids = { 8970 }, name = "I See Alcaz Island In Your Future...", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain.", summary = "As I was saying, $c, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.$B$BThis is where you come in, $N. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live there." },
            { ids = { 8986 }, name = "More Components of Importance", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", summary = "$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus." },
            { ids = { 8990 }, name = "The Right Piece of Lord Valthalak's Amulet", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", summary = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.$B$BShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces." },
            { ids = { 8994 }, name = "Final Preparations", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.", summary = "We're nearly there, $c. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.$B$BTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.$B$BGood luck, $N!" },
            { ids = { 8995 }, name = "Mea Culpa, Lord Valthalak", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Spirit of Lord Valthalak", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Spire", objective = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.", summary = "All is now ready, $N.$B$BWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.$B$BOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.$B$BGood luck!" },
            { ids = { 8996 }, name = "Return to Bodley", level = 60, zone = "Blackrock Spire", giver = "Spirit of Lord Valthalak", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Spire", ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.", summary = "I will ignore your impertinence this time, $c, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, $r, you have shown courage where those that stole from me did not, and probably never could!$B$BReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now." },
            { ids = { 8997 }, name = "Back to the Beginning", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Deliana", enderMap = 1455, enderX = 43.5, enderY = 52.6, objective = "Speak with Deliana at The High Seat in Ironforge.", summary = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.$B$BGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened." },
        },
    },
    {
        id = "q8929",
        name = "The Challenge",
        zone = "Ironforge",
        minLevel = 58,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 8905, 8906, 8907, 8908, 8909, 8910, 8911, 8912 }, name = "An Earnest Proposition", level = 60, zone = "Ironforge", giver = "Deliana", giverMap = 1455, giverX = 43.5, giverY = 52.6, ender = "Deliana", enderMap = 1455, enderX = 43.5, enderY = 52.6, objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.", summary = "Well met, $c.  I've something that might interest you.$B$BI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.$B$BThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while." },
            { ids = { 8922 }, name = "A Supernatural Device", level = 60, zone = "Ironforge", giver = "Deliana", giverMap = 1455, giverX = 43.5, giverY = 52.6, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris.", summary = "I must find a way to speak with Anthion Harmon... or more specifically, his ghost!$B$BI know of an engineer with a queer interest in the supernatural.  He claims he can build a machine that allows him to speak with the dead!$B$BThe blood you collected was intended for him; travel to Gadgetzan and bring it to him as payment for his services! " },
            { ids = { 8926, 8931, 8932, 8933, 8934, 8935, 8936, 8937 }, name = "Just Compensation", level = 60, zone = "Ironforge", giver = "Deliana", giverMap = 1455, giverX = 43.5, giverY = 52.6, ender = "Deliana", enderMap = 1455, enderX = 43.5, enderY = 52.6, objective = "Bring a Wildheart Belt and a set of Wildheart Gloves Deliana in Ironforge.", summary = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior." },
            { ids = { 8929 }, name = "In Search of Anthion", level = 60, zone = "Ironforge", giver = "Deliana", giverMap = 1455, giverX = 43.5, giverY = 52.6, ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.", summary = "Well, nothing left for us to do but try out the goblin's invention.  Word has it that Anthion was mowed down by the undead legions of Stratholme as he tried to enter its gates.$B$BTry using the device there and find out whatever Anthion knew." },
            { ids = { 8921 }, name = "The Ectoplasmic Distiller", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.", summary = "Ah, you're in need of my latest project... the extra-dimensional ghost revealer!  Unfortunately I've run out of funds and manpower.$B$BYou're willing to help?  Excellent!  Our first task is to build a device to harvest the very fabric of death!  Building an ectoplasmic distiller won't be an easy task, $N.$B$BI'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter." },
            { ids = { 8945 }, name = "Dead Man's Plea", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Ysida Harmon", enderMap = 1423, enderX = 26.5, enderY = 10.4, enderInside = "Stratholme", objective = "Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.", summary = "I'll provide you the information you ask for, $N.  But more pressing matters are at hand.$B$BMy beloved wife has been taken prisoner by Rivendare's undead scum.$B$BI strongly objected to her joining the Argent Dawn's foolish crusade, yet that's not of importance anymore.  You must finish what I attempted to do, you must rescue Ysida from the clutches of the Baron!" },
            { ids = { 8924 }, name = "Hunting for Ectoplasm", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands.  Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan.", summary = "A fine piece of engineering, if I do say so myself!  You will need to travel a bit, I'm afraid, in order to find the incorporeal undead we require.$B$BYou see, different climates lend different consistencies to the spectral fabric of the dead.  The tortured night elves of Silithus, the spirits of the highborne from Winterspring and the ghosts and banshees of the Eastern Plaguelands should give us the different types of ectoplasm we need.  Be sure to place the distiller nearby before you harvest them!" },
            { ids = { 8946 }, name = "Proof of Life", level = 60, zone = "Stratholme", giver = "Ysida Harmon", giverMap = 1423, giverX = 26.5, giverY = 10.4, giverInside = "Stratholme", ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Bring Ysida's Locket to Anthion Harmon in Eastern Plaguelands.", summary = "It is the cruelest of fates that my beloved has perished while trying to rescue me.  Yet, you claim to possess the ability to converse with him.$B$BBring him this locket as proof that I am well.  He must not linger in this world; my heart would not be able to bear it.$B$BFarewell, $N.  I shall be in your debt always." },
            { ids = { 8925 }, name = "A Portable Power Source", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan.", summary = "Next we shall need to find a stable and portable source of energy to keep the ectoplasm active.  I've heard rumors of a mighty elemental called Magma Lord Bokk, whose heart is a powerful magma core - an endless supply of heat!$B$BIt's said he can be found in the Burning Steppes, south of Blackrock Mountain.  Bring the magma core to me and we shall have enough juice to power the extra-dimensional ghost revealer!" },
            { ids = { 8947 }, name = "Anthion's Strange Request", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Bring 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth and 4 Cured Rugged Hides to Anthion Harmon in the Eastern Plaguelands.", summary = "We didn't realize the importance of Valthalak's medallion, so it was divided along with the rest of the spoils.  The first piece was taken by a dwarf named Theldren.  I tried to retrieve it from him and he beat me within an inch of my life.  You shall have to take the fragment by force.$B$BLast I heard of him, he'd become a gladiator for the Dark Iron dwarves.  Getting him to fight you is going to present a bit of a challenge, though.$B$BGather the following materials for me.  You're going to need them." },
            { ids = { 8928 }, name = "A Shifty Merchant", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan.", summary = "The core will provide us with enough juice to power our device; now we just have to build a rod that can channel that energy without melting.$B$BI met an imp in Winterspring that sold all manner of exotic goods.  He had an elemental rod that would do perfectly.  I'm kicking myself in the head right now for not having bought it.$B$BHe lives inside a cave in the entrance to Darkwhisper Gorge.  Sneak in there and try to find him.$B$BMake sure he only charges you forty gold; that's the price he quoted me!" },
            { ids = { 8948 }, name = "Anthion's Old Friend", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Falrin Treeshaper", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul.", summary = "Theldren is not one to willingly participate in a fair fight.  I've shaped this banner to display his family colors.$B$BWith some additional sorcery, this banner shall provoke him in a way he won't be able to resist.$B$BAn old acquaintance of mine named Falrin knows the exact procedure required.  He has a particular way of... aggravating people.  You shall find him at the library in Dire Maul." },
            { ids = { 8977 }, name = "Return to Deliana", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Deliana", enderMap = 1455, enderX = 43.5, enderY = 52.6, objective = "Bring the Extra-Dimensional Ghost Revealer  to Deliana in Ironforge.", summary = "It's been great working with you, $N.  Here is the finished product.$B$BI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!" },
            { ids = { 8949 }, name = "Falrin's Vendetta", level = 60, zone = "Dire Maul", giver = "Falrin Treeshaper", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Falrin Treeshaper", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.", summary = "Yes, it is true that I am familiar with this enchantment you require, $c.  Yet I'm not one to give out favors freely, even if you were sent here by an old friend.$B$BI hold nothing but hatred and contempt for our brutish ogre neighbors.  And not only them, I hate the followers of Omokk just as much as I hate those that follow King Gordok.$B$BI want you to kill them.  Kill lots of them!  Bring me the beads they carry around their neck as proof of your work.  Do this and we shall talk about your request." },
            { ids = { 8950 }, name = "The Instigator's Enchantment", level = 60, zone = "Dire Maul", giver = "Falrin Treeshaper", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Falrin Treeshaper", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards.", summary = "I can place the enchantment you require on the banner quite easily, $N.  Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.$B$BI will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards.  Bring me these reagents and I shall perform this task for you." },
            { ids = { 9015 }, name = "The Challenge", level = 60, zone = "Dire Maul", giver = "Falrin Treeshaper", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone.  Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet.", summary = "Heed me well, $N.  For the banner to work in the desired way, you will need to step into the Ring of the Law in Blackrock Depths.  Allow yourself to be sentenced by High Justice Grimstone and place the banner firmly on the ground in a sign of defiance.$B$BYour victim will not be able to restrain himself and shall enter the fray filled with a desire to fight you.  Once you obtain that which you seek, go back to Anthion." },
        },
    },
    {
        id = "q8304",
        name = "Dearest Natalia",
        zone = "Silithus",
        minLevel = 58,
        maxLevel = 60,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 8304 }, name = "Dearest Natalia", level = 60, zone = "Silithus", giver = "Commander Mar'alith", giverMap = 1451, giverX = 49.2, giverY = 34.2, ender = "Commander Mar'alith", enderMap = 1451, enderX = 49.2, enderY = 34.2, objective = "Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.$B$BOnce you have gathered the requested information, return to Commander Mar'alith.", summary = "My dear Natalia has gone missing.$B$BTruth be told, she had been acting strangely for weeks leading up to her disappearance. I had caught her talking to herself when no one was around on more than one occasion. She was adamant that everything was ok and that she must be allowed to continue her research.$B$BShe was last seen heading to Bronzebeard's camp to the south.$B$BMy soldiers are spread too thin, $N. I need you to go to Bronzebeard's camp and question those dwarves. " },
            { ids = { 8309 }, name = "Glyph Chasing", level = 60, zone = "Silithus", giver = "Rutgar Glyphshaper", giverMap = 1451, giverX = 41.3, giverY = 88.5, ender = "Rutgar Glyphshaper", enderMap = 1451, enderX = 41.3, enderY = 88.5, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment in Silithus wants you to venture to Hive'Ashi, Hive'Zora, and Hive'Regal and recover Glyphed Rubbings from the Glyphed Crystals of each hive.$B$BUse the Geologist's Transcription Kit to make a reasonable facsimile of the ancient glyphs. Return to Rutgar Glyphshaper when you complete this task.", summary = "After our initial foray into the hives and Mistress Mar'alith's subsequent madness the three hives have been spewing out bugs! The increased activity might be tied into the glyphs covering those strange crystals.$B$BWe must get a rubbing from crystals in all three hives. If we can get those rubbings, we might be able to make sense of this madness.$B$BTake this transcription set and some buddies and hit those hives, $N. Don't come back until you've gotten copies from each hive." },
            { ids = { 8310 }, name = "Breaking the Code", level = 60, zone = "Silithus", giver = "Frankal Stonebridge", giverMap = 1451, giverX = 40.8, giverY = 88.9, ender = "Frankal Stonebridge", enderMap = 1451, enderX = 40.8, enderY = 88.9, objective = "Frankal Stonebridge at Bronzebeard's Encampment in Silithus wants you to recover a Hive'Zora Silithid Brain, Hive'Ashi Silithid Brain, and a Hive'Regal Silithid Brain. Return to Frankal when you have completed this task.", summary = "I think I can formulate an elixir that will allow us to more readily decipher the glyphs and language of the silithid and Qiraji! What do I need? Glad you asked! I need brains! More specifically, a brain from each silithid type that inhabit the hives. Bring me brains and Rutgar's work might not be for naught." },
            { ids = { 8314 }, name = "Unraveling the Mystery", level = 60, zone = "Silithus", giver = "Rutgar Glyphshaper", giverMap = 1451, giverX = 41.3, giverY = 88.5, ender = "Geologist Larksbane", enderMap = 1451, enderX = 49.7, enderY = 37.5, objective = "Rutgar Glyphshaper at Bronzebeard's Encampment wants you to deliver the Glyphed Crystal Prism to Geologist Larksbane at the Cenarion Hold in Silithus.", summary = "We're on the verge of a breakthrough, $N! The rubbings you recovered have allowed us to recreate the glyphs on this crystalline prism. They are apparently a means for the Qiraji and other unknown entities to communicate various messages to the silithid.$B$BUnfortunately, that is all we could get out of the glyphs. We need to find a way to unlock the messages hidden within the crystals.$B$BTake the glyphed crystal prism to Geologist Larksbane at Cenarion Hold.  She might be able to help." },
            { ids = { 8315 }, name = "The Calling", level = 60, zone = "Silithus", giver = "Geologist Larksbane", giverMap = 1451, giverX = 49.7, giverY = 37.5, ender = "Geologist Larksbane", enderMap = 1451, enderX = 49.7, enderY = 37.5, objective = "Geologist Larksbane at Cenarion Hold in Silithus wants you to recover the Crystal Unlocking Mechanism from the Qiraji Emissary.$B$BYou have been instructed to take the Glyphs of Calling to the Bones of Grakkarond, south of Cenarion Hold, and draw them in the sand. Should the Qiraji Emissary appear, slay it and recover the Crystal Unlocking Mechanism. Return to Geologist Larksbane if you succeed.$B$BAssemble an army for this task, $N!", summary = "The glyphs illustrate an emissary of the Qiraji meeting with three silithid at the bones of a large dragon. Above the glyphs is what I can only assume to be a code of some sort. This code might very well be the key to summoning the emissary.$B$BI will create a copy of the glyph code that you must use in the sand at the Bones of Grakkarond. If I am right, the Overlords will come thinking that new data is ready for transmission. Strike them down and confront the emissary. He holds the key to the crystals..." },
        },
    },
    {
        id = "q8286",
        name = "Only One May Rise",
        zone = "Silithus",
        minLevel = 60,
        maxLevel = 60,
        importance = 3,
        kind = "raid",
        quests = {
            { ids = { 8286 }, name = "What Tomorrow Brings", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Baristolth of the Shifting Sands", enderMap = 1451, enderX = 49.5, enderY = 36.5, objective = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.", summary = "The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds.$B$B\"Forever you will remain if you must,\" he said, and with those words I was bound as a Watcher.$B$BLook now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed." },
            { ids = { 8288 }, name = "Only One May Rise", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Baristolth of the Shifting Sands", enderMap = 1451, enderX = 49.5, enderY = 36.5, objective = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.", summary = "There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood.$B$BWithin the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey." },
            { ids = { 8301 }, name = "The Path of the Righteous", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Baristolth of the Shifting Sands", enderMap = 1451, enderX = 49.5, enderY = 36.5, objective = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", summary = "The Brood of Nozdormu are naturally distrusting of the lesser races. While it is true that you have proven to me that you have the potential makings of a hero, the time has come to prove this to my master.$B$BHive'Ashi, Hive'Zora, Hive'Regal: All swarming with activity and all a threat to our existence. Slay silithid at these hives and take from them a fragment of their carapace. When you can carry no more, return to me and I shall strengthen your resolve." },
            { ids = { 8303 }, name = "Anachronos", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Seek out Anachronos at the Caverns of Time in Tanaris.", summary = "It is time, $N.$B$BI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master." },
            { ids = { 8305 }, name = "Long Forgotten Memories", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Crystalline Tear", enderMap = 1451, enderX = 28.7, enderY = 89.1, objective = "Locate the Crystalline Tear in Silithus and gaze into its depths.", summary = "In the southern desert of Silithus, near the sacred barrier, exists a single crystalline tear. This tear serves as a symbol of the great losses beset upon us during the War of the Shifting Sands. Locate this tear and gaze into its depths to gain enlightenment." },
            { ids = { 8519 }, name = "A Pawn on the Eternal Board", level = 60, zone = "Silithus", giver = "Crystalline Tear", giverMap = 1451, giverX = 28.7, giverY = 89.1, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Learn all that you can of the past, then speak with Anachronos at the Caverns of Time in Tanaris.", summary = "As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten." },
            { ids = { 8555 }, name = "The Charge of the Dragonflights", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0 },
            { ids = { 8730 }, name = "Nefarius's Corruption", level = 60, zone = "Blackwing Lair", giver = "Vaelastrasz the Corrupt", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackwing Lair", ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", summary = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?$B$B<Vaelastrasz coughs weakly.>$B$BNe... Nefarius now holds the scepter shard.$B$BTime is of the essence. Nefarius plans to destroy the shard. You must hurry!" },
            { ids = { 8733 }, name = "Eranikus, Tyrant of the Dream", level = 60, zone = "The Temple of Atal'Hakkar", giver = "Malfurion Stormrage", giverMap = 1435, giverX = 69.9, giverY = 53.5, giverInside = "The Temple of Atal'Hakkar", ender = "Forest Wisp", enderMap = 1438, enderX = 37.5, enderY = 47.9, objective = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.", summary = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.$B$BTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.$B$B<Malfurion sighs.>$B$BA fall from grace a thousand years in the making..." },
            { ids = { 8734 }, name = "Tyrande and Remulos", level = 60, zone = "Teldrassil", giver = "Forest Wisp", giverMap = 1438, giverX = 37.5, giverY = 47.9, ender = "Keeper Remulos", enderMap = 1450, enderX = 36.2, enderY = 41.8, objective = "Travel to the Moonglade and speak to Keeper Remulos. ", summary = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.$B$BNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.$B$BWe all wish you great luck." },
            { ids = { 8735 }, name = "The Nightmare's Corruption", level = 60, zone = "Moonglade", giver = "Keeper Remulos", giverMap = 1450, giverX = 36.2, giverY = 41.8, ender = "Keeper Remulos", enderMap = 1450, enderX = 36.2, enderY = 41.8, objective = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task.", summary = "You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments." },
            { ids = { 8736 }, name = "The Nightmare Manifests", level = 60, zone = "Moonglade", giver = "Keeper Remulos", giverMap = 1450, giverX = 36.2, giverY = 41.8, ender = "Keeper Remulos", enderMap = 1450, enderX = 36.2, enderY = 41.8, objective = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.", summary = "We must use restraint against Eranikus. We are to redeem him not destroy him.$B$BTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.$B$BBe on guard! You and your allies are our only hope." },
            { ids = { 8741 }, name = "The Champion Returns", level = 60, zone = "Moonglade", giver = "Keeper Remulos", giverMap = 1450, giverX = 36.2, giverY = 41.8, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.", summary = "The keeper awaits your return, $N. Take the green scepter shard to Anachronos at the Caverns of Time." },
            { ids = { 8742 }, name = "The Might of Kalimdor", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, after = { 8729 } },
            { ids = { 8745 }, name = "Treasure of the Timeless One", level = 60, zone = "Silithus", giver = "Jonathan the Revelator", giverMap = 1451, giverX = 25.9, giverY = 91.0, ender = "Jonathan the Revelator", enderMap = 1451, enderX = 25.9, enderY = 91.0 },
        },
    },
    {
        id = "q8575",
        name = "The Wrath of Neptulon",
        zone = "Azshara",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "raid",
        quests = {
            { ids = { 8575 }, name = "Azuregos's Magical Ledger", level = 60, zone = "Azshara", giver = "Spirit of Azuregos", giverMap = 1447, giverX = 53.0, giverY = 81.7, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, after = { 8555 }, objective = "Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris.", summary = "You cannot understand a single word on this ledger. You don't even know what language it is written in!" },
            { ids = { 8576 }, name = "Translating the Ledger", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6 },
            { ids = { 8577 }, name = "Stewvul, Ex-B.F.F.", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Inconspicuous Crate", enderMap = 1421, enderX = 46.2, enderY = 86.7, objective = "Narain Soothfancy wants you to find his ex-best friend forever (BFF), Stewvul, and take back the scrying goggles that Stewvul stole from him.", summary = "If I am to translate anything, I will need my scrying goggles. Unfortunately, those were stolen quite some time ago by my ex-best friend forever, Stewvul. He broke my heart in five places and then left me here to rot.$B$BWith the help of my trusty crystal ball, I've isolated his whereabouts to either the Greymane Wall in Silverpine or what appears to be a portal world in the Outland that is currently being overrun by the Burning Legion. You're going to have to track him down and get my goggles back, $N!" },
            { ids = { 8584 }, name = "Never Ask Me About My Business", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Dirge Quikcleave", enderMap = 1446, enderX = 52.6, enderY = 28.1, objective = "Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan.", summary = "If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you.$B$BAs I said earlier, if this is going to work, we're going to need a 500 pound chicken.$B$BHead to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen." },
            { ids = { 8597 }, name = "Draconic for Dummies", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Freshly Dug Dirt", enderMap = 947, enderX = 30.0, enderY = 89.2, objective = "Find Narain Soothfancy's book, buried on an island in the South Seas.", summary = "I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe.$B$BDon't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers!$B$BLook for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it!" },
            { ids = { 8578 }, name = "Scrying Goggles? No Problem!", level = 60, zone = "Silverpine Forest", giver = "Inconspicuous Crate", giverMap = 1421, giverX = 46.2, giverY = 86.7, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.", summary = "<You hear a sigh of relief escape the crate.>$B$BYou just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit!$B$BWell, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!" },
            { ids = { 8585 }, name = "The Isle of Dread!", level = 60, zone = "Tanaris", giver = "Dirge Quikcleave", giverMap = 1446, giverX = 52.6, giverY = 28.1, ender = "Dirge Quikcleave", enderMap = 1446, enderX = 52.6, enderY = 28.1, objective = "Recover Lakmaeran's Carcass and 20 Chimaerok Tenderloins for Dirge Quickcleave in Tanaris.", summary = "Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.$B$BHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin.$B$BDo this and you'll have your 500 pound chicken and a little something extra." },
            { ids = { 8598 }, name = "rAnS0m", level = 60, zone = "Azeroth", giver = "Freshly Dug Dirt", giverMap = 947, giverX = 30.0, giverY = 89.2, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Return the Ransom Letter to Narain Soothfancy in Tanaris.", summary = "<The text on this note is made up of various typefaces glued onto the parchment's surface.>$B$BWe've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask.$B$B<A detailed set of instructions is listed, spanning 3 pages.>$B$BBring the money and come alone!" },
            { ids = { 8586 }, name = "Dirge's Kickin' Chimaerok Chops", level = 60, zone = "Tanaris", giver = "Dirge Quikcleave", giverMap = 1446, giverX = 52.6, giverY = 28.1, ender = "Dirge Quikcleave", enderMap = 1446, enderX = 52.6, enderY = 28.1, objective = "Dirge Quikcleave in Gadgetzan wants you to bring him 20 Goblin Rocket Fuel and 20 Deeprock Salt.", summary = "My recipe is complete! What I need from you now is some rocket fuel and deeprock salt. I'll handle the spices and the meat you brought me will cover the rest.$B$BAfter you bring me what I asked for, the chicken will be ready to take back to Narain." },
            { ids = { 8606 }, name = "Decoy!", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Narain Soothfancy in Tanaris wants you to travel to Winterspring and place the Bag of Gold at the drop off point documented by the booknappers.", summary = "I've got it! Here's what we're going to do. I'm going to fill a sack up with rocks and you're going to make the drop. I know it said that I should make the delivery and I'm going to - sort of.$B$B<Narain looks you up and down.>$B$BYes, you will do just fine. Take this turban, robe, and sack of rocks and head to the drop off point in Winterspring.$B$BI've included everything you need in this special kit. When they show up to pick up the goods, snuff them out! That will teach them to mess with Narain!" },
            { ids = { 8587 }, name = "Return to Narain", level = 60, zone = "Tanaris", giver = "Dirge Quikcleave", giverMap = 1446, giverX = 52.6, giverY = 28.1, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Deliver the 500 Pound Chicken to Narain Soothfancy in Tanaris.", summary = "I'm a goblin of my word, kid. Here's your 500 pound chicken.$B$BWhat a gnome wants with a 500 pound chicken, I'll never know...$B$B<Dirge grumbles something unintelligible.>$B$BProbably to sleep in it... Dirty gnomes..." },
            { ids = { 8620 }, name = "The Only Prescription", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.", summary = "I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?$B$BThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me." },
            { ids = { 8728 }, name = "The Good News and The Bad News", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.", summary = "Well that took a little longer than expected. Now let me see what this ledger says.$B$B<Narain silently reads the ledger, periodically mumbling under his breath.>$B$B The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.$B$BThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.$B$BBring me what I need and I will craft the buoy." },
            { ids = { 8729 }, name = "The Wrath of Neptulon", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", summary = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.$B$BAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.$B$BLook for a swirling maelstrom, most likely cluttered with wreckage.$B$BBy the by, I hope you have friends.$B$BNow if you somehow miraculously succeed, take the scepter shard to Anachronos." },
        },
    },
    {
        id = "q7507",
        name = "The Forging of Quel'Serrar",
        zone = "Dire Maul",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        classes = { 1, 2 },
        quests = {
            { ids = { 7507 }, name = "Nostro's Compendium", level = 60, zone = "Dire Maul", ender = "Lorekeeper Lydros", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.", summary = "You have uncovered something of great importance. This book is unlike any that you have seen.$B$BIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible." },
            { ids = { 7508 }, name = "The Forging of Quel'Serrar", level = 60, zone = "Dire Maul", ender = "Lorekeeper Lydros", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", summary = "If you wish to take on this task, present Lydros with the dull blade." },
            { ids = { 7509 }, name = "The Forging of Quel'Serrar", level = 60, zone = "Dire Maul", giver = "Lorekeeper Lydros", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Lorekeeper Lydros", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.$B$BThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.$B$BDo this and Quel'Serrar will be yours.", summary = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.$B$BSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.$B$BPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade." },
        },
    },
    {
        id = "q7638",
        name = "Judgment and Redemption",
        zone = "Stormwind City",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        races = { 1, 3 },
        classes = { 2 },
        quests = {
            { ids = { 7638 }, name = "Lord Grayson Shadowbreaker", level = 60, zone = "Stormwind City", giver = "Duthorian Rall", giverMap = 1453, giverX = 50.5, giverY = 47.5, ender = "Lord Grayson Shadowbreaker", enderMap = 1453, enderX = 48.4, enderY = 50.2, objective = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", summary = "The time has come, $N, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.$B$BSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.$B$BI wish you the best in this trial.  For the Light, noble $G brother : sister;!" },
            { ids = { 7637 }, name = "Emphasis on Sacrifice", level = 60, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "High Priest Rohan", enderMap = 1455, enderX = 24.7, enderY = 8.2, objective = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer.  You will need to make a donation of 150 gold in order to secure it.", summary = "In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.$B$BYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.$B$BProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.$B$BGo now $N, time is of the essence." },
            { ids = { 7639 }, name = "To Show Due Judgment", level = 60, zone = "Ironforge", giver = "High Priest Rohan", giverMap = 1455, giverX = 24.7, giverY = 8.2, ender = "Lord Grayson Shadowbreaker", enderMap = 1453, enderX = 48.4, enderY = 50.2, objective = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", summary = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.$B$BReturn now to Lord Grayson Shadowbreaker in Stormwind, $N.  Your quest continues with him." },
            { ids = { 7640 }, name = "Exorcising Terrordale", level = 60, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "Lord Grayson Shadowbreaker", enderMap = 1453, enderX = 48.4, enderY = 50.2, objective = "Use the Exorcism Censer to drive out the spirits that torment Terrordale.  When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", summary = "I have added a pinch of dirt from the tainted ground of Terrordale in the Eastern Plaguelands to the censer.  You will now use this censer to find areas there that show signs of spiritual turmoil and disturbance.  Look for green auras that permeate the ground as the physical world buckles under the torment of the spirit realm and use the censer to drive out the evil spirits.$B$BWhen you have passed sufficient judgment on the spirits there, you will be ready to proceed." },
            { ids = { 7641 }, name = "The Work of Grimand Elmore", level = 60, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "Grimand Elmore", enderMap = 1453, enderX = 59.7, enderY = 33.8, objective = "Speak with Grimand Elmore in Stormwind's Dwarven District.", summary = "A paladin's charger is nothing more than a pack animal without proper barding for it.  The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.$B$BFirst things first, $N - let's get your barding made.  In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore.  His work will not be cheap, but his quality is what we seek.  Speak with him." },
            { ids = { 7642 }, name = "Collection of Goods", level = 60, zone = "Stormwind City", giver = "Grimand Elmore", giverMap = 1453, giverX = 59.7, giverY = 33.8, ender = "Grimand Elmore", enderMap = 1453, enderX = 59.7, enderY = 33.8, objective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.", summary = "You'll need four things for the barding - runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement.  Actually, you need five things... gold for my fee.  That fee includes all labor as well as a handcrafted saddle and stirrups.$B$BOnce you've got all that, I'll be able to finish your barding.  Until then, there are some things I can get started on for you while you assemble your collection of goods." },
            { ids = { 7643 }, name = "Ancient Equine Spirit", level = 60, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "Ancient Equine Spirit", enderMap = 1444, enderX = 60.3, enderY = 30.2, enderInside = "Dire Maul", objective = "Acquire special horse feed used for feeding a spirit horse.  Merideth Carlson in Southshore apparently is the source for such food.$B$BTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood.  Doing so will free the Ancient Equine Spirit.  Feed it the special horse feed, thereby soothing the spirit.  Finally, give it the Arcanite Barding so it may bless it.", summary = "Your barding needs a special form of blessing, one from an appropriate spirit.  In Dire Maul is such a spirit, the Ancient Equine Spirit.  It is currently held by a corrupt treant, Tendris Warpwood.  Pass judgment upon this foul beast, $N.$B$BKnow this - freedom alone is not enough.  You must soothe the spirit before receiving its blessing.  For that, special horse feed is needed.  Travel to Southshore first and speak with Merideth Carlson on this... and prepare for more sacrifice." },
            { ids = { 7644 }, name = "Blessed Arcanite Barding", level = 60, zone = "Dire Maul", giver = "Ancient Equine Spirit", giverMap = 1444, giverX = 60.3, giverY = 30.2, giverInside = "Dire Maul", ender = "Lord Grayson Shadowbreaker", enderMap = 1453, enderX = 48.4, enderY = 50.2, objective = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", summary = "As the barding rests on the back of the Ancient Equine Spirit, it glows ever so slightly.  The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.$B$BIt would seem that the barding has been blessed.  As per Lord Shadowbreaker's instructions, you should now return with it to him in Stormwind." },
            { ids = { 7646 }, name = "The Divination Scryer", level = 60, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "Lord Grayson Shadowbreaker", enderMap = 1453, enderX = 48.4, enderY = 50.2, objective = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", summary = "We now must assemble a Divination Scryer - this will begin the trial that will allow you to redeem the fallen charger.  Your scryer, actually, is almost done.  The exorcism censer used in Terrordale is the catalyst for it, and I will fashion a suitable housing for the device.$B$BThe last components needed, though, are two diamonds.  They must be as juxtaposed in brilliance as they are in purpose - an Azerothian and a Pristine Black.  These two will be the beacon by which the scryer will pierce the shadows!" },
            { ids = { 7647 }, name = "Judgment and Redemption", level = 60, zone = "Stormwind City", giver = "Lord Grayson Shadowbreaker", giverMap = 1453, giverX = 48.4, giverY = 50.2, ender = "Darkreaver's Fallen Charger", enderMap = 1422, enderX = 69.7, enderY = 73.2, enderInside = "Scholomance", objective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance.  Doing so will bring forth the spirits you must judge.  Defeating these spirits will summon forth Death Knight Darkreaver.  Defeat him and reclaim the lost soul of the fallen charger.$B$BGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.", summary = "Take this satchel - in it are the items you will need for your task.$B$BUse the divination scryer in the heart of the Great Ossuary's basement to bring forth accursed spirits that must be judged.  Use your judgments wisely during this trial - they will prove more potent than you realize.  After the spirits, the death knight will appear; defeat him and reclaim the lost soul of the charger.  Only then $N, will you be able to redeem it and place your barding upon your new steed!$B$BGood luck!" },
        },
    },
    {
        id = "q7623",
        name = "Dreadsteed of Xoroth",
        zone = "Burning Steppes",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 7563 }, name = "Rage of Blood", level = 58, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Mor'zul Bloodbringer", enderMap = 1428, enderX = 12.7, enderY = 31.6, objective = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.", summary = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.$B$BIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.$B$BTheir blood is what I need to ink your parchment.  Bring it to me." },
            { ids = { 7623 }, name = "Lord Banehollow", level = 58, zone = "Burning Steppes", giver = "Gorzeeki Wildeyes", giverMap = 1428, giverX = 12.4, giverY = 31.6, ender = "Lord Banehollow", enderMap = 1448, enderX = 35.9, enderY = 44.4, objective = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.$B$BUse the potions to travel through Jaedenar, and speak with Lord Banehollow.", summary = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!$B$BThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.$B$BBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you..." },
            { ids = { 7564 }, name = "Wildeyes", level = 58, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.", summary = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work." },
            { ids = { 7624 }, name = "Ulathek the Traitor", level = 58, zone = "Felwood", giver = "Lord Banehollow", giverMap = 1448, giverX = 35.9, giverY = 44.4, ender = "Lord Banehollow", enderMap = 1448, enderX = 35.9, enderY = 44.4, objective = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.", summary = "You wish to enter my good graces?  Then kill for me.$B$BMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...$B$BProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!" },
            { ids = { 7626 }, name = "Bell of Dethmoora", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.", summary = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.$B$BMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki." },
            { ids = { 7627 }, name = "Wheel of the Black March", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes.", summary = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.$B$BAcquire these and bring them to my servant." },
            { ids = { 7628 }, name = "Doomsday Candle", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.", summary = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!$B$BContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes." },
            { ids = { 7625 }, name = "Xorothian Stardust", level = 60, zone = "Felwood", giver = "Lord Banehollow", giverMap = 1448, giverX = 35.9, giverY = 44.4, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Purchase Xorothian Stardust from Ur'dan.  Bring it to Gorzeeki Wildeyes in the Burning Steppes.", summary = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?$B$BVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price." },
            { ids = { 7630 }, name = "Arcanite", level = 60, zone = "Burning Steppes", giver = "Gorzeeki Wildeyes", giverMap = 1428, giverX = 12.4, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 3 Arcanite Bars to Gorzeeki in the Burning Steppes.", summary = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.$B$BTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.$B$BReturn to me when you have the arcanite, and then I'll make the black lodestone." },
            { ids = { 7629 }, name = "Imp Delivery", level = 60, zone = "Burning Steppes", giver = "Gorzeeki Wildeyes", giverMap = 1428, giverX = 12.4, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring the Imp in a Jar to the alchemy lab in the Scholomance.  After the parchment is created, return the jar to Gorzeeki Wildeyes.", summary = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!$B$BThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.$B$BI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment." },
            { ids = { 7631 }, name = "Dreadsteed of Xoroth", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Dreadsteed Spirit", enderMap = 1444, enderX = 60.3, enderY = 30.2, enderInside = "Dire Maul", objective = "Read Mor'zul's Instructions.  Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.", summary = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.$B$BI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.$B$BFortune to you, $N.  And may the souls of your enemies swiftly find their way into your shard pouch." },
        },
    },
    {
        id = "q9250",
        name = "Atiesh, the Befouled Greatstaff",
        zone = "",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        classes = { 5, 8, 9, 11 },
        quests = {
            { ids = { 9250 }, name = "Frame of Atiesh", level = 60, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil.", summary = "With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.$B$BFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff." },
            { ids = { 9251 }, name = "Atiesh, the Befouled Greatstaff", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.", summary = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, $N. I only do as I must.$B$BKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.$B$BAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.$B$BShould you succeed in recovering the pieces, return them to me." },
        },
    },
    {
        id = "q9123",
        name = "Echoes of War",
        zone = "Eastern Plaguelands",
        minLevel = 60,
        maxLevel = 60,
        importance = 1,
        kind = "raid",
        quests = {
            { ids = { 9123 }, name = "The Dread Citadel - Naxxramas", level = 60, zone = "Eastern Plaguelands", giver = "Archmage Angela Dosantos", giverMap = 1423, giverX = 71.7, giverY = 48.7, ender = "Archmage Angela Dosantos", enderMap = 1423, enderX = 71.7, enderY = 48.7, objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.", summary = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations." },
            { ids = { 9033 }, name = "Echoes of War", level = 60, zone = "Eastern Plaguelands", giver = "Commander Eligor Dawnbringer", giverMap = 1423, giverX = 71.7, giverY = 48.6, ender = "Commander Eligor Dawnbringer", enderMap = 1423, enderX = 71.7, enderY = 48.6, objective = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands wants you to slay 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains and 3 Venom Stalkers.", summary = "Five years since the last war...$B$BTens of thousands of lives were lost and for what? The threat was never fully extinguished.$B$BAnd so the Lich King stirs once more... His yes-man, Kel'Thuzad, amassing for another attack upon our lands.$B$BWe will not allow it! Prove your dedication. Prove that you are willing to risk life and limb to stop this madness and the combined might of the Dawn and the Crusade will be at your beck and call.$B$BEnter Naxxramas and destroy the Scourge within..." },
            { ids = { 9229 }, name = "The Fate of Ramaladni", level = 60, zone = "Eastern Plaguelands", giver = "Korfax, Champion of the Light", giverMap = 1423, giverX = 72.0, giverY = 48.5, ender = "Korfax, Champion of the Light", enderMap = 1423, enderX = 72.0, enderY = 48.5, objective = "Enter Naxxramas and uncover the Fate of Ramaladni.", summary = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.$B$BUnderstand this, $N, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.$B$BEnter Naxxramas and find what became of Ramaladni." },
            { ids = { 9230 }, name = "Ramaladni's Icy Grasp", level = 60, zone = "Eastern Plaguelands", giver = "Korfax, Champion of the Light", giverMap = 1423, giverX = 72.0, giverY = 48.5, ender = "Korfax, Champion of the Light", enderMap = 1423, enderX = 72.0, enderY = 48.5, objective = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.", summary = "Fixing this band may prove to be quite challenging, $N. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory." },
        },
    },
}
